local config = {
  ui_story_5089_50890100_1_dialog_content = "O tempo está realmente bom hoje. É bom vagar sozinho pela cidade de Haojin depois de tanto tempo.",
  ui_story_5089_50890100_2_dialog_content = "Mas eu me senti observado desde que cheguei aqui...",
  ui_story_5089_50890100_3_dialog_content = "Não sinto nenhuma maldade, mas ainda assim me dá arrepios na espinha... Será que sou muito estranho em relação aos outros aqui?",
  ui_story_5089_50890100_4_dialog_content = "Ahem, perdoe-me, jovem, mas você é o enviado de Astra?",
  ui_story_5089_50890100_5_dialog_content = "Hum, sim, isso mesmo. Há algo de que você precisa?",
  ui_story_5089_50890100_6_dialog_content = "Ah, que maravilha! Sou apenas um pequeno empresário, administrando alguns restaurantes e hotéis no Reino Ji.",
  ui_story_5089_50890100_7_dialog_content = "Fui informado que você gosta de tofu seco, e uma das minhas lojas é especializada em fazê-lo. Não é um grande presente, mas por favor, aceite.",
  ui_story_5089_50890100_8_dialog_content = "Se o sabor for do seu agrado, basta pedir e eu te enviarei ainda mais!",
  ui_story_5089_50890100_9_dialog_content = "Hã? Quando foi que eu disse que amo tofu seco? Espere, eu ainda não sei quem você é—",
  ui_story_5089_50890100_10_dialog_content = "O estimado enviado finalmente chegou! Que honra é conhecer você! Por favor, dê uma olhada nas minhas sedas finas!",
  ui_story_5089_50890100_11_dialog_content = "Rápido! Busque o inestimável Brocado de Harmonia da Fênix de nossa loja e apresente-o ao nosso convidado!",
  ui_story_5089_50890100_12_dialog_content = "Oh não, eu não poderia aceitar isso!",
  ui_story_5089_50890100_13_dialog_content = "Perdoe-me, mas meu mestre preparou uma grande refeição para você. Seria uma honra ter o enviado de Astra como nosso convidado de honra!",
  ui_story_5089_50890100_14_dialog_content = "Saudações, senhor! A filha do meu mestre está organizando um encontro de poesia em nossa casa amanhã, e ela escreveu este convite especialmente para você.",
  ui_story_5089_50890100_15_dialog_content = "Quem é aquilo ali? Por que estão causando tal alvoroço?",
  ui_story_5089_50890100_16_dialog_content = "Parece que é o enviado das terras ocidentais!",
  ui_story_5089_50890100_17_dialog_content = "Aquele que ganhou o favor da Donzela do Dragão, e ajudou a aliviar a inundação em Haojin e derrotar um dragão maligno. Ouço dizer que o enviado vai até se casar com o príncipe herdeiro em breve!",
  ui_story_5089_50890100_18_dialog_content = "Sério? Vamos dar uma olhada!",
  ui_story_5089_50890100_19_dialog_content = "Enviada! Por aqui, enviada...!",
  ui_story_5089_50890100_20_dialog_content = "(E-Esse é ruim! Tenho que dar o fora daqui!)",
  ui_story_5089_50890100_21_dialog_content = "Ha... Ufa... Finalmente consegui voltar.",
  ui_story_5089_50890100_22_dialog_content = "Sei que os ajudei antes, mas o entusiasmo de todos parece um pouco exagerado.",
  ui_story_5089_50890100_23_dialog_content = "Eu tenho que pedir para Chen'ni me proteger sempre que eu sair agora?",
  ui_story_5089_50890100_24_dialog_content = "Além disso, tenho quase certeza de que ouvi um deles dizer algo totalmente ridículo agora há pouco.",
  ui_story_5089_50890100_25_dialog_content = "<color=#e8d9bb>Piu-piu!</color>",
  ui_story_5089_50890100_26_dialog_content = "Ei, é o pássaro mecânico que enviei para entregar uma mensagem para Xuan Ji! Vamos ver...",
  ui_story_5089_50890100_27_dialog_content = "Hã?",
  ui_story_5089_50890100_28_dialog_content = "Esta é a carta que enviei, mas nem sequer foi aberta. Será que não conseguiu encontrá-la?",
  ui_story_5089_50890100_29_dialog_content = "Piu.",
  ui_story_5089_50890100_30_dialog_content = "Isso é estranho. Durante o Festival da Primavera, ela disse que estava voltando para o Reino Ye para cuidar de alguns negócios inacabados.",
  ui_story_5089_50890100_31_dialog_content = "Então, como vim parar em uma antiga floresta montanhosa?",
  ui_story_5089_50890100_32_dialog_content = "Agora que penso nisso, desde que cheguei em Longzhou, ela tem mantido distância enquanto investiga algo. Será que...?",
  ui_story_5089_50890100_33_dialog_content = "Senhor, um convidado está aqui para vê-lo.",
  ui_story_5089_50890100_34_dialog_content = "... D-Essas pessoas me seguiram até a Casa de Hóspedes Real?!",
  ui_story_5089_50890100_35_dialog_content = "Desculpe, mas eu não quero vê-los agora. Apenas diga que os Celestitas têm que hibernar para o inverno ou algo assim.",
  ui_story_5089_50890100_36_dialog_content = "Mas... O inverno não acabou de passar?",
  ui_story_5089_50890100_37_dialog_content = "E-Então apenas diga a eles que ainda estou me ajustando à primavera e que tenho que me preparar para a hibernação do próximo ano! Não importa. Apenas invente uma desculpa!",
  ui_story_5089_50890100_38_dialog_content = "Nunca pensei que seria tão difícil conseguir uma audiência com você, PlayerName.",
  ui_story_5089_50890100_39_dialog_content = "D-Dantang?! Não, essas desculpas não eram para você—",
  ui_story_5089_50890100_40_dialog_content = "Eu sei.",
  ui_story_5089_50890100_41_dialog_content = "Você não é mais apenas um enviado de Astra, mas também um herói realizado para o Reino Ji.",
  ui_story_5089_50890100_42_dialog_content = "As ruas de Haojin estão agitadas com rumores de seu próximo noivado com o príncipe herdeiro também.",
  ui_story_5089_50890100_43_dialog_content = "Não é de se admirar que os comerciantes do Reino de Ji estejam competindo para estabelecer um bom relacionamento com você.",
  ui_story_5089_50890100_44_dialog_content = "Por que todo o Haojin sabe disso?! E ninguém tem nenhuma pergunta sobre isso?",
  ui_story_5089_50890100_45_dialog_content = "Até mesmo os rumores mais absurdos contêm um grão de verdade, não?",
  ui_story_5089_50890100_46_dialog_content = "G-Me dê um tempo...",
  ui_story_5089_50890100_47_dialog_content = "Há méritos em aceitar a proposta do príncipe herdeiro, sabe?",
  ui_story_5089_50890100_48_dialog_content = "Ele pode ser um pouco travesso, mas seu coração é puro e cheio de admiração por suas façanhas heroicas durante o equinócio de primavera.",
  ui_story_5089_50890100_49_dialog_content = "Após se tornar a consorte do príncipe herdeiro e se mudar para o palácio real, ninguém jamais ousará espalhar rumores sobre você novamente.",
  ui_story_5089_50890100_50_dialog_content = "Você realmente precisa de algo, Dantang? Ou você veio aqui sério só para me zoar?",
  ui_story_5089_50890100_51_dialog_content = "\"Incomodar você\"? É realmente assim que você me vê, PlayerName?",
  ui_story_5089_50890100_52_dialog_content = "Não! Não foi isso que eu quis dizer...",
  ui_story_5089_50890100_53_dialog_content = "Heheh, te peguei. Não há necessidade de estar tão nervoso.",
  ui_story_5089_50890100_54_dialog_content = "No entanto, há um motivo para eu ter vindo aqui hoje... Jiu.",
  ui_story_5089_50890100_55_dialog_content = "Sim, Sua Alteza.",
  ui_story_5089_50890100_56_dialog_content = "Uau! Você também está aqui, Jiu? Eu totalmente não te vi ali!",
  ui_story_5089_50890100_57_dialog_content = "Sua Alteza tem assuntos importantes para discutir com o enviado. Eu permanecerei ao lado dela; o resto de vocês estão dispensados.",
  ui_story_5089_50890100_58_dialog_content = "Sim, Sua Alteza.",
  ui_story_5089_50890100_59_dialog_content = "Vou fazer um chá.",
  ui_story_5089_50890100_60_dialog_content = "T-Tudo bem, eu posso—",
  ui_story_5089_50890100_61_dialog_content = "Também trouxe alguns petiscos leves do palácio para o seu prazer, então, por favor, sirvam-se. Se não precisarem mais de mim, então me despedirei agora.",
  ui_story_5089_50890100_62_dialog_content = "Hã? Quer dizer que você não vai comer conosco, Jiu?",
  ui_story_5089_50890100_63_dialog_content = "Veja, Jiu? PlayerName deseja sua companhia, agora por favor, sente-se.",
  ui_story_5089_50890100_64_dialog_content = "... Isso seria uma quebra de etiqueta, Alteza. Se precisar de mim, estarei à porta.",
  ui_story_5089_50890100_65_dialog_content = "...",
  ui_story_5089_50890100_66_dialog_content = "... O que foi aquilo?",
  ui_story_5089_50890100_67_dialog_content = "Jiu não é muito de conversar para começar, mas a distância entre nós parece ainda maior do que o habitual hoje.",
  ui_story_5089_50890100_68_dialog_content = "Se for o caso, prefiro que ela discuta comigo.",
  ui_story_5089_50890100_69_dialog_content = "?",
  ui_story_5089_50890100_70_dialog_content = "Mas não vamos falar sobre isso por agora. O motivo de eu ter vindo aqui hoje foi para me despedir de você.",
  ui_story_5089_50890100_71_dialog_content = "Até a próxima...? Você está indo para algum lugar?",
  ui_story_5089_50890100_72_dialog_content = "Meu tio, ou melhor, o atual rei do Reino Ye, convocou-me de volta ao reino.",
  ui_story_5089_50890100_73_dialog_content = "Isso é ótimo! Dantang, você finalmente pode ir para casa agora!",
  ui_story_5089_50890100_74_dialog_content = "Mas é realmente tão simples? Afinal, você veio para o Reino Ji como... Hum, como um estudante de intercâmbio.",
  ui_story_5089_50890100_75_dialog_content = "Não há nada para esconder. É realmente tão difícil dizer a palavra \"refém\"?",
  ui_story_5089_50890100_76_dialog_content = "Suas preocupações, no entanto, são perfeitamente válidas. Como um refém político, retornar para casa de onde fui exilado nunca será uma questão simples.",
  ui_story_5089_50890100_77_dialog_content = "Na superfície, parece que os reinos de Ji e Ye estão negociando novos termos.",
  ui_story_5089_50890100_78_dialog_content = "Mas abaixo da superfície?",
  ui_story_5089_50890100_79_dialog_content = "Meu mestre já me garantiu que o Reino Ji não vai obstruir minha jornada de volta para casa.",
  ui_story_5089_50890100_80_dialog_content = "\"Os comerciantes, embora movidos pelo lucro, de maneira alguma são ingratos.\" Essas foram mais ou menos as palavras do rei.",
  ui_story_5089_50890100_81_dialog_content = "O que isso realmente significa...?",
  ui_story_5089_50890100_82_dialog_content = "Após a agitação do Festival da Primavera, um templo dedicado à Donzela Dragão foi construído dentro do palácio, e uma estátua dourada foi esculpida em sua homenagem.",
  ui_story_5089_50890100_83_dialog_content = "A família Lin está se reagrupando e ficando mais forte a cada dia, e você se torna um cidadão amado e honrado do Reino Ji.",
  ui_story_5089_50890100_84_dialog_content = "Eu mesmo não fui isento de receber as generosas recompensas do reino.",
  ui_story_5089_50890100_85_dialog_content = "Mas há uma pessoa que, apesar de seus esforços, ainda não recebeu qualquer tipo de recompensa.",
  ui_story_5089_50890100_86_dialog_content = "Você quer dizer Xuan Ji, certo? Eu não consegui alcançá-la de jeito nenhum recentemente... Você sabe o que está acontecendo com ela?",
  ui_story_5089_50890100_87_dialog_content = "Essa é a segunda questão que eu queria discutir com você.",
  ui_story_5089_50890100_88_dialog_content = "Recebemos um decreto real do Reino Ye. Por ordem do rei, a Ministra Armilla deve ser presa e encarcerada após a conclusão do Festival da Primavera.",
  ui_story_5089_50890100_89_dialog_content = "Ela é acusada de trair o reino através do uso de maquinário crítico.",
  ui_story_5089_50890100_90_dialog_content = "O quê?!",
  ui_story_5089_50890100_91_dialog_content = "E por essa razão, decidi tomar uma ação imediata e voltar para o Reino Ye amanhã.",
  ui_story_5089_50890100_92_dialog_content = "Eu só gostaria de poder fazer a viagem ainda mais cedo. Pelo bem da Ministra Armilla, devo investigar essas acusações e descobrir a verdade.",
  ui_story_5089_50890100_93_dialog_content = "PlayerName—",
  ui_story_5089_50890100_94_dialog_content = "Eu vou também!",
  ui_story_5089_50890100_95_dialog_content = "Muito bem.",
  ui_story_5089_50890100_96_dialog_content = "Quando você disse que estava saindo, eu já queria te pedir para me levar com você.",
  ui_story_5089_50890100_97_dialog_content = "Eu não sou uma divindade, e não vim para Longzhou apenas para sentar aqui e aceitar oferendas - até a verdadeira divindade não fez isso.",
  ui_story_5089_50890100_98_dialog_content = "Não há nada para mim fazer aqui em Haojin, então agora é um bom momento para partir.",
  ui_story_5089_50890100_99_dialog_content = "E além disso, Xuan Ji também é meu amigo. Não importa o que você diga, eu vou encontrar uma maneira de ir junto. Espere, o que você acabou de dizer?",
  ui_story_5089_50890100_100_dialog_content = "Muito bem.",
  ui_story_5089_50890100_101_dialog_content = "... Eu pensei que você diria que isso não tem nada a ver comigo e me diria para ficar aqui.",
  ui_story_5089_50890100_102_dialog_content = "Ninguém pode sobreviver em isolamento. Aqueles com muitos aliados prosperam, enquanto aqueles com poucos perecem.",
  ui_story_5089_50890100_103_dialog_content = "Os seus ensinamentos ainda ecoam nos meus ouvidos. Eu não ousaria esquecê-los.",
  ui_story_5089_50890100_104_dialog_content = "D-Eu realmente disse algo tão legal para você?",
  ui_story_5089_50890100_105_dialog_content = "Heheh. Se me der licença, preciso voltar ao palácio para fazer nossos preparativos finais. Até amanhã, PlayerName.",
  ui_story_5089_50890100_106_dialog_content = "Eu também deveria empacotar minhas coisas...",
  ui_story_5089_50890100_107_dialog_content = "Partindo tão cedo?",
  ui_story_5089_50890100_108_dialog_content = "Uau! Chen'ni? O que você está fazendo aqui novamente?!",
  ui_story_5089_50890100_109_dialog_content = "Ah, por volta de quando você desejou que eu pudesse usar meu poder para mantê-lo escondido.",
  ui_story_5089_50890100_110_dialog_content = "E-Então você esteve aqui esse tempo todo!",
  ui_story_5089_50890100_111_dialog_content = "... O que significa que você ouviu tudo isso também, certo? Estou indo para o Reino Ye amanhã, então não poderei brincar com você por um tempo.",
  ui_story_5089_50890100_112_dialog_content = "Tudo bem! Eu também vou junto; se alguém ficar no nosso caminho, farei o que faço de melhor!",
  ui_story_5089_50890100_113_dialog_content = "\"Soco os demônios e mande-os voar em todas as direções!\"",
  ui_story_5089_50890100_114_dialog_content = "Não, não, não. Isso não está na Dança do Dragão, por que você insiste em lembrar disso?!",
  ui_story_5089_50890100_115_dialog_content = "Realmente importa? Afinal, as lendas sobre deidades e heróis sempre mudaram ao longo dos anos.",
  ui_story_5089_50890100_116_dialog_content = "E graças a você, decidi fazer aulas de artes marciais e fazer jus à minha nova lenda!",
  ui_story_5089_50890100_117_dialog_content = "Tudo bem, mas lembre-se de controlar seus socos. Não estarei lá para te manter em cheque, então você terá que fazer isso sozinho.",
  ui_story_5089_50890100_118_dialog_content = "Então você realmente não quer que eu vá com você para o Reino Ye? Porque se você apenas fizer um desejo...",
  ui_story_5089_50890100_119_dialog_content = "Se eu fizesse, ainda seria meu amigo?",
  ui_story_5089_50890100_120_dialog_content = "...",
  ui_story_5089_50890100_121_dialog_content = "Quero continuar sendo seu amigo enquanto eu estiver por perto, Chen'ni.",
  ui_story_5089_50890100_122_dialog_content = "Isso significa que nunca tratarei a Divindade do Dragão Benevolente Todo-Poderoso como um recurso a ser explorado.",
  ui_story_5089_50890100_123_dialog_content = "<color=#e8d9bb>De repente, Chen'ni estende a mão e puxa uma folha de uma árvore fora da janela, depois a entrega.</color>",
  ui_story_5089_50890100_124_dialog_content = "O que é isso?",
  ui_story_5089_50890100_125_dialog_content = "Um presente de despedida.",
  ui_story_5089_50890100_126_dialog_content = "É uma tradição Aurorian, certo?",
  ui_story_5089_50890100_127_dialog_content = "Estarei aqui esperando quando você voltar, PlayerName. Vamos nos divertir muito quando você voltar!",
  ui_story_5089_50890100_128_dialog_content = "Tenho certeza de que os Aurorianos usam um galho de salgueiro para—Uh, Chen'ni?",
  ui_story_5089_50890100_129_dialog_content = "Ela saiu sem dizer mais nada... Acho que vou guardar isso por enquanto e secá-los mais tarde.",
  ui_story_5089_50890100_130_dialog_content = "Este também é um bom momento para dizer adeus aos outros.",
  ui_story_5089_50890100_131_dialog_content = "<color=#e8d9bb>No dia seguinte</color>",
  ui_story_5089_50890100_132_dialog_content = "É aqui que eu deveria encontrar Dantang, certo?",
  ui_story_5089_50890100_133_dialog_content = "PlayerName! PlayerName! Você finalmente chegou! Eu estive esperando por muito tempo, sabe!",
  ui_story_5089_50890100_134_dialog_content = "Príncipe Herdeiro... O que você está fazendo aqui? E o que é aquela caixa grande ali?",
  ui_story_5089_50890100_135_dialog_content = "Estou aqui para te despedir, claro. Até preparei alguns presentes de despedida.",
  ui_story_5089_50890100_136_dialog_content = "Eu escolhi cuidadosamente cada um desses tesouros inestimáveis ​​apenas para você!",
  ui_story_5089_50890100_137_dialog_content = "Vê? Esta é a boneca que eu costumava levar para todo lugar quando era criança. E aqui está a lanterna que eu mesmo fiz durante o festival.",
  ui_story_5089_50890100_138_dialog_content = "Ah, e meu livro de histórias favorito! O mestre não me deixava lê-lo, então tive que pedir a muitas pessoas para me ajudarem a comprá-lo!",
  ui_story_5089_50890100_139_dialog_content = "O que me lembra... Dantang e o Conselheiro Chefe me contaram tudo.",
  ui_story_5089_50890100_140_dialog_content = "Nunca pedi sua opinião antes de decidir que você se tornaria meu consorte. Foi errado da minha parte e lamento por colocá-lo em uma posição tão difícil.",
  ui_story_5089_50890100_141_dialog_content = "Sua Alteza...",
  ui_story_5089_50890100_142_dialog_content = "O navio está prestes a zarpar, PlayerName.",
  ui_story_5089_50890100_143_dialog_content = "Ah, ok. De qualquer forma, como estes são todos sinais da sua sinceridade, ficarei feliz em aceitá-los.",
  ui_story_5089_50890100_144_dialog_content = "Esplêndido!",
  ui_story_5089_50890100_145_dialog_content = "Guardas, vão buscar o resto disso!",
  ui_story_5089_50890100_146_dialog_content = "E-Espere... O que há com aqueles caixotes?!",
  ui_story_5089_50890100_147_dialog_content = "Ah, apenas algumas coisas pequenas para a sua jornada. Só tive tempo de preparar esta caixa, então deixei o resto com meus homens.",
  ui_story_5089_50890100_148_dialog_content = "Mas a minha sinceridade é totalmente real! Por favor, acredite em mim!",
  ui_story_5089_50890100_149_dialog_content = "Agora que cresci para entender os caminhos do mundo, percebo o quão imprudente eu era antes.",
  ui_story_5089_50890100_150_dialog_content = "Vejo agora que o cortejo deve sempre acontecer antes do casamento!",
  ui_story_5089_50890100_151_dialog_content = "... Me desculpe?",
  ui_story_5089_50890100_152_dialog_content = "Levantar âncora—",
  ui_story_5089_50890100_153_dialog_content = "Zarpe—",
  ui_story_5089_50890100_154_dialog_content = "<color=#e8d9bb>Enquanto o navio parte lentamente, o príncipe acena e grita da costa.</color>",
  ui_story_5089_50890100_155_dialog_content = "Boa viagem! E fique tranquilo, continuarei a cortejá-lo com presentes até que você concorde em ser meu consorte—",
  ui_story_5089_50890100_156_dialog_content = "...",
  ui_story_5089_50890100_157_dialog_content = "Eu sabia que sair de Haojin era a decisão certa!",
  ui_story_5089_50890100_158_dialog_content = "Até eu estou surpresa com o afeto do príncipe por você, PlayerName. Nunca o vi perseguir algo com tanta determinação única.",
  ui_story_5089_50890100_159_dialog_content = "Mas eu não posso aceitar todos esses presentes, mesmo que sejam apenas um monte de brinquedos...",
  ui_story_5089_50890100_160_dialog_content = "Se você realmente não pode aceitá-los, eu sempre posso organizar para que sejam enviados de volta assim que chegarmos ao Reino Ye.",
  ui_story_5089_50890100_161_dialog_content = "Esse terá que ser o plano. Salvar Xuan Ji tem precedência sobre tudo o resto.",
  ui_story_5089_50890100_162_dialog_content = "Certo. Finalmente é hora de ir... Não, espera.",
  ui_story_5089_50890100_163_dialog_content = "Finalmente é hora de voltar para o Reino Ye.",
  ui_story_5089_50890201_1_dialog_content = "Sua Alteza, PlayerName, por favor, prepare-se para desembarcar.",
  ui_story_5089_50890201_2_dialog_content = "Mas acabamos de passar a fronteira entre os dois reinos, não é? Realmente estamos lá?",
  ui_story_5089_50890201_3_dialog_content = "Ainda não, não. Ao contrário do Reino de Ji e seus muitos canais, o Reino de Ye está situado em uma vasta planície central. Os navios só podem nos levar até aqui.",
  ui_story_5089_50890201_4_dialog_content = "Ei, eu me lembro deste porto... Esta é a cidade de Tongli, não é?",
  ui_story_5089_50890201_5_dialog_content = "Sim, Sua Alteza. Já reservei a estalagem para a noite. Descansaremos lá e continuaremos nossa jornada amanhã.",
  ui_story_5089_50890201_6_dialog_content = "Uma vez que as carruagens estiverem seguras, viajaremos diretamente para a capital por terra.",
  ui_story_5089_50890201_7_dialog_content = "Isso é impressionante, Jiu! Como você conseguiu fazer tudo isso enquanto ainda estamos na água?",
  ui_story_5089_50890201_8_dialog_content = "O navio vem equipado com um pequeno barco a remo. Eu o usei para chegar à costa e organizar tudo com antecedência.",
  ui_story_5089_50890201_9_dialog_content = "Dada a natureza súbita e inesperada de nossa viagem, ninguém foi notificado para nos receber neste momento.",
  ui_story_5089_50890201_10_dialog_content = "Já é crime suficiente que Sua Alteza tenha que se hospedar em uma pousada tão humilde, então devemos pelo menos garantir a segurança dos arredores.",
  ui_story_5089_50890201_11_dialog_content = "Você disse que estamos nos aproximando, mas eu não vejo nenhum sinal de terra...",
  ui_story_5089_50890201_12_dialog_content = "Você remou todo esse caminho sozinho... Não é de se admirar que você esteja completamente encharcado.",
  ui_story_5089_50890201_13_dialog_content = "Você deve trocar para algo seco antes de pegar um resfriado.",
  ui_story_5089_50890201_14_dialog_content = "Agradeço a sua preocupação, mas não sou tão frágil. Uma vida inteira de treinamento em artes marciais me mantém em boa saúde.",
  ui_story_5089_50890201_15_dialog_content = "Desembarquei para explorar a área e garantir sua segurança, mas deixar Sua Alteza por conta de meus próprios assuntos seria uma negligência de dever.",
  ui_story_5089_50890201_16_dialog_content = "Então, novamente, é impróprio da minha parte apresentar tal cena perto de Sua Alteza. Perdoe-me, vou ficar fora de vista.",
  ui_story_5089_50890201_17_dialog_content = "Espere, não foi isso que eu quis dizer—",
  ui_story_5089_50890201_18_dialog_content = "Está bem, PlayerName. Apenas deixe-a ir.",
  ui_story_5089_50890201_19_dialog_content = "Este é o maior tempo que a vi se mostrar em bastante tempo.",
  ui_story_5089_50890201_20_dialog_content = "Mesmo no palácio, quando estou ocupado organizando cartas e documentos, ela frequentemente repõe meu chá e lanches sem que eu perceba.",
  ui_story_5089_50890201_21_dialog_content = "Ou quando volto de reuniões com outras pessoas, sempre encontro meu quarto perfeitamente arrumado e limpo.",
  ui_story_5089_50890201_22_dialog_content = "Ela tem feito ainda mais do que o habitual sem que ninguém a perceba.",
  ui_story_5089_50890201_23_dialog_content = "(Os elfos sapateiros?)",
  ui_story_5089_50890201_24_dialog_content = "Então, o que exatamente aconteceu entre vocês dois?",
  ui_story_5089_50890201_25_dialog_content = "PlayerName, você ainda se lembra do grupo de pessoas responsável pelo caos em Haojin algum tempo atrás?",
  ui_story_5089_50890201_26_dialog_content = "Você quer dizer os caras que se chamavam de Fate Riders?",
  ui_story_5089_50890201_27_dialog_content = "Sim. Com a ajuda do Todo-Poderoso Dragão Benevolente Divindade, o Escritório de Inspeção conseguiu prender um grande número de Fate Riders escondidos dentro do Reino Ji.",
  ui_story_5089_50890201_28_dialog_content = "Entre eles estavam dezenas de pessoas que ocupavam cargos oficiais no tribunal do reino.",
  ui_story_5089_50890201_29_dialog_content = "Embora fossem principalmente funcionários de nível inferior, com o tempo, eles conseguiram estabelecer uma poderosa rede entre si...",
  ui_story_5089_50890201_30_dialog_content = "Poderoso o suficiente para influenciar grandemente a corte, e até mesmo o próprio rei. Na verdade, pode-se dizer que essas pessoas ganharam o poder de abalar um reino inteiro até o seu núcleo.",
  ui_story_5089_50890201_31_dialog_content = "Felizmente, conseguimos capturar todos eles, e agora o rei e seus conselheiros estão mais vigilantes do que nunca. Esses traidores não poderão mais agir com impunidade.",
  ui_story_5089_50890201_32_dialog_content = "Mas mesmo assim, PlayerName... Você realmente acredita que a rede deles estava restrita apenas ao Reino Ji?",
  ui_story_5089_50890201_33_dialog_content = "Quer dizer que...",
  ui_story_5089_50890201_34_dialog_content = "Na noite do tumulto em Haojin, eu estava tentando te procurar, mas fui interceptado assim que saí dos portões do palácio.",
  ui_story_5089_50890201_35_dialog_content = "Esta é a primeira vez que ouço falar disso! Eles não te machucaram, machucaram? Por que você não contou a ninguém?!",
  ui_story_5089_50890201_36_dialog_content = "Porque aqueles que me interceptaram eram espiões do Reino Ye.",
  ui_story_5089_50890201_37_dialog_content = "O quê?!",
  ui_story_5089_50890201_38_dialog_content = "O atual imperador do Império Zhao é jovem, e os oito reis têm cada um suas próprias intenções.",
  ui_story_5089_50890201_39_dialog_content = "Embora a espionagem entre eles seja comum, não é algo que possa ser discutido abertamente.",
  ui_story_5089_50890201_40_dialog_content = "E embora os espiões do Reino Ye me respeitassem como sua princesa, eles ainda só respondem a um homem: meu tio.",
  ui_story_5089_50890201_41_dialog_content = "Então eles me bloquearam, e assim ajudaram os Fate Riders em seus esquemas...",
  ui_story_5089_50890201_42_dialog_content = "O Rei de Ye é realmente o único que pode controlá-los?",
  ui_story_5089_50890201_43_dialog_content = "Meu tio não era bem conhecido antes de assumir o trono e tem sido um governante exemplar. Ele nomeia pessoas com base em seus talentos, se preocupa profundamente com seus súditos e se comporta com a postura de um verdadeiro rei.",
  ui_story_5089_50890201_44_dialog_content = "O que me leva a presumir que isso é obra dos Fate Riders!",
  ui_story_5089_50890201_45_dialog_content = "Eu vejo. Não é à toa que você está com tanta pressa para voltar.",
  ui_story_5089_50890201_46_dialog_content = "Ao evitar o máximo possível os Fate Riders do Reino Ye, você está livre para se movimentar e investigar assuntos, que você pode relatar posteriormente ao rei.",
  ui_story_5089_50890201_47_dialog_content = "E então, logicamente, seríamos capazes de resgatar Xuan Ji, que foi preso por nos ajudar!",
  ui_story_5089_50890201_48_dialog_content = "Você me conhece muito bem, PlayerName.",
  ui_story_5089_50890201_49_dialog_content = "Mas o que qualquer coisa disso tem a ver com Jiu?",
  ui_story_5089_50890201_50_dialog_content = "Pensei que você soubesse.",
  ui_story_5089_50890201_51_dialog_content = "Jiu não é outro senão o líder dos espiões do Reino Ye.",
  ui_story_5089_50890201_52_dialog_content = "O quê?! Ela não é sua guarda pessoal?",
  ui_story_5089_50890201_53_dialog_content = "Jiu era originalmente uma serva confiável sob o comando direto do meu tio. Ela foi designada para mim como guarda pouco antes de eu ser enviado para o Reino de Ji como refém.",
  ui_story_5089_50890201_54_dialog_content = "Meu tio mostrou a ela um grande favor. Ela nunca desafiaria qualquer ordem que viesse dele.",
  ui_story_5089_50890201_55_dialog_content = "E porque meu tio ordenou que ela me protegesse, ela está disposta a arriscar sua vida para fazer isso.",
  ui_story_5089_50890201_56_dialog_content = "Por preocupação com minha segurança, ele pediu a ela que escrevesse para ele todos os meses com atualizações. Independentemente da estação ou circunstância, ela nunca perdeu um prazo.",
  ui_story_5089_50890201_57_dialog_content = "Isso...",
  ui_story_5089_50890201_58_dialog_content = "Entendo a preocupação do meu tio, mas de outra perspectiva, também pode ser considerado vigilância.",
  ui_story_5089_50890201_59_dialog_content = "Espere, isso significa que os Fate Riders ainda estão rastreando nossas ações?! Será que Jiu...",
  ui_story_5089_50890201_60_dialog_content = "Você pode deixar suas dúvidas de lado.",
  ui_story_5089_50890201_61_dialog_content = "Afinal, você viu por si mesmo, não viu? Jiu se recusa a mentir sobre qualquer coisa para mim ou para o meu tio.",
  ui_story_5089_50890201_62_dialog_content = "Ela nunca desobedeceria suas ordens, mas ela entende completamente a importância de nossa jornada. Por essa razão, ela só pode olhar para o outro lado, permanecer em silêncio e não fazer perguntas.",
  ui_story_5089_50890201_63_dialog_content = "Desde que ela cumpra seus deveres como guarda e mantenha distância de mim, ela não terá que relatar nada que não saiba.",
  ui_story_5089_50890201_64_dialog_content = "Ela já está fazendo tudo o que pode por nós.",
  ui_story_5089_50890201_65_dialog_content = "No entanto, não posso negar minha alegria ao ver meu guarda teimoso vacilar levemente.",
  ui_story_5089_50890201_66_dialog_content = "Pelo menos, os cinco anos que passamos juntos no Reino Ji não foram totalmente desperdiçados.",
  ui_story_5089_50890201_67_dialog_content = "Dantang.",
  ui_story_5089_50890201_68_dialog_content = "Sim? Deixe-me adivinhar: você não acha que eu deveria ter prazer em vê-la lutar, não é?",
  ui_story_5089_50890201_69_dialog_content = "Você teve realmente difícil no Reino Ji todos esses anos, não teve?",
  ui_story_5089_50890201_70_dialog_content = "Ahn???",
  ui_story_5089_50890201_71_dialog_content = "Er, bem... Quero dizer...",
  ui_story_5089_50890201_72_dialog_content = "Eu sei que o Rei de Ji, o Príncipe Herdeiro e o Conselheiro Chefe são todas pessoas boas, mas eles não são sua família.",
  ui_story_5089_50890201_73_dialog_content = "Suspirar...",
  ui_story_5089_50890201_74_dialog_content = "O-O que é? Eu disse algo errado?",
  ui_story_5089_50890201_75_dialog_content = "De maneira nenhuma. Na verdade, se você fosse um comandante do exército, algo me diz que você seria excelente em ataques surpresa.",
  ui_story_5089_50890201_76_dialog_content = "Huh? Por que estamos falando disso de repente?",
  ui_story_5089_50890201_77_dialog_content = "Se me der licença, preciso retocar minha maquiagem antes de desembarcarmos.",
  ui_story_5089_50890201_78_dialog_content = "Uh, tudo bem...",
  ui_story_5089_50890201_79_dialog_content = "Cau...",
  ui_story_5089_50890201_80_dialog_content = "Cau...",
  ui_story_5089_50890201_81_dialog_content = "Madeira podre nunca pode ser esculpida!",
  ui_story_5089_50890201_82_dialog_content = "E uma árvore de ferro nunca florescerá!",
  ui_story_5089_50890201_83_dialog_content = "Ei, quem você está chamando de \"madeira podre\"?! Espere... Squawk? Jabber? O que vocês dois estão fazendo aqui?",
  ui_story_5089_50890201_84_dialog_content = "Entregue alguns melões dourados e eu guiarei seu caminho!",
  ui_story_5089_50890201_85_dialog_content = "Ofereça algumas tâmaras de prata, e dissiparei todas as suas dúvidas!",
  ui_story_5089_50890201_86_dialog_content = "Desculpe desapontar, mas não tenho nenhuma dessas coisas.",
  ui_story_5089_50890201_87_dialog_content = "Se você está com fome, apenas peça comida ao seu mestre. Ele também deve estar por aqui, certo? Eu estou bem ciente de sua tendência de aparecer do nada.",
  ui_story_5089_50890201_88_dialog_content = "Tianxian! Você também está aqui, certo?",
  ui_story_5089_50890201_89_dialog_content = "Não temos mais um mestre!",
  ui_story_5089_50890201_90_dialog_content = "As águas o reivindicaram!",
  ui_story_5089_50890201_91_dialog_content = "Bem ali!",
  ui_story_5089_50890201_92_dialog_content = "O quê...?!",
  ui_story_5089_50890201_93_dialog_content = "Glub, glub... Socorro... Eu... Não consigo nadar... Glub, glub, glub...",
  ui_story_5089_50890201_94_dialog_content = "O que ele está fazendo na água?! Ah, isso não é bom...",
  ui_story_5089_50890201_95_dialog_content = "Eu tenho que salvá-lo!",
  ui_story_5089_50890202_1_dialog_content = "Atchim!",
  ui_story_5089_50890202_2_dialog_content = "Graças a Deus, eu vivo para ver outro dia.",
  ui_story_5089_50890202_3_dialog_content = "Que diabos você estava fazendo, se afogando em um lugar como este? Não me diga que você recebeu outro convite para o Palácio do Dragão?!",
  ui_story_5089_50890202_4_dialog_content = "Não... Na verdade, é muito menos complicado do que isso.",
  ui_story_5089_50890202_5_dialog_content = "Eu tinha me cansado de vagar pelo Reino Ji, então pensei em visitar novas terras. Mas como você sabe, muitas vezes estou com falta de fundos.",
  ui_story_5089_50890202_6_dialog_content = "Incapaz de pagar a passagem em um navio maior, não tive escolha a não ser viajar com uma caravana menor de comerciantes. Após inúmeras paradas ao longo do caminho, finalmente chegamos ao Reino de Ye.",
  ui_story_5089_50890202_8_dialog_content = "Que visão rara, considerando que o tribunal realiza uma cerimônia anual para banir esses monstros de suas terras. As terras fronteiriças entre os reinos de Ji e Ye nem sequer estão perto do oceano.",
  ui_story_5089_50890202_10_dialog_content = "E assim eles começaram a perseguir sem pensar duas vezes. Enquanto corria pela minha vida, perdi a noção do meu entorno e acabei mergulhando no mar.",
  ui_story_5089_50890202_11_dialog_content = "Mas graças a todos vocês, minha vida foi poupada mais uma vez. Se ao menos eu tivesse algo de valor para oferecer como sinal da minha gratidão...",
  ui_story_5089_50890202_12_dialog_content = "Parece que não tenho escolha a não ser retribuir com o meu corpo!",
  ui_story_5089_50890202_13_dialog_content = "N-Não há necessidade disso!",
  ui_story_5089_50890202_14_dialog_content = "Você não tem nada melhor para fazer agora mesmo?!",
  ui_story_5089_50890202_15_dialog_content = "Diga-me, você ainda se lembra do meu nome?",
  ui_story_5089_50890202_16_dialog_content = "Uh, sim? É Tianxian, não é?",
  ui_story_5089_50890202_17_dialog_content = "Correto! E se você fosse traduzi-lo na sua interpretação mais literal, significa \"o maior preguiçoso do mundo\"!",
  ui_story_5089_50890202_18_dialog_content = "Então, por favor, não seja tão rápido em me dispensar. Antes de partir, eu adivinhei minha própria sorte. Embora tenha previsto grande infortúnio em minha jornada, também insinuou a chegada de um benfeitor bondoso e rico.",
  ui_story_5089_50890202_19_dialog_content = "Quanto a quem possa ser... Venha, estenda suas mãos para mim.",
  ui_story_5089_50890202_20_dialog_content = "Assim?",
  ui_story_5089_50890202_21_dialog_content = "<color=#e8d9bb>Barulho!</color>",
  ui_story_5089_50890202_22_dialog_content = "Uh... Por que você jogou todos os seus bastões de adivinhação nas minhas mãos?",
  ui_story_5089_50890202_23_dialog_content = "Oh querido, os hexagramas do Dragão Yin e do Rato Yin. Isso não nos augura nada de bom.",
  ui_story_5089_50890202_24_dialog_content = "O dragão ascendente e o rato saltitante são normalmente sinais auspiciosos, mas exatamente o oposto neste caso. Juntos, eles significam que uma terrível ameaça está escondida diante de nós, e que vilões estão tramando algo nefasto enquanto falamos. Em suma, estamos enfrentando um desastre iminente.",
  ui_story_5089_50890202_25_dialog_content = "Em circunstâncias normais, eu estaria correndo para salvar minha vida agora. No entanto, não poderia deixar meus salvadores sozinhos para enfrentar esse desastre.",
  ui_story_5089_50890202_26_dialog_content = "Ah, bem, não pode ser evitado. Permita-me juntar a você em suas viagens para que possamos enfrentar essa terrível ameaça juntos.",
  ui_story_5089_50890202_27_dialog_content = "Estou sempre desconfiado de qualquer coisa que você diz, mas essa situação inteira parece especialmente suspeita.",
  ui_story_5089_50890202_28_dialog_content = "Como assim? Você foi quem me resgatou de um túmulo aquático, não foi?",
  ui_story_5089_50890202_29_dialog_content = "Sim, mas sua fortuna disse que um \"benfeitor rico\" iria resgatar você.",
  ui_story_5089_50890202_30_dialog_content = "Não é para me gabar ou algo assim, mas eu nunca fui rico um dia na minha vida!",
  ui_story_5089_50890202_31_dialog_content = "Hmm, que estranho. Minhas adivinhações indicaram que você seria rico o suficiente para rivalizar com uma nação inteira até agora.",
  ui_story_5089_50890202_32_dialog_content = "Sim, talvez nos meus sonhos...",
  ui_story_5089_50890202_33_dialog_content = "O navio agora está atracado, PlayerName. Um barqueiro virá em breve para carregar seus pertences, então sinta-se à vontade para desembarcar a qualquer momento.",
  ui_story_5089_50890202_34_dialog_content = "Um barqueiro? Isso não vai funcionar de jeito nenhum! Como parte do pagamento da dívida da minha vida para você, permita-me carregar esta caixa—",
  ui_story_5089_50890202_35_dialog_content = "Urgh! Por que é tão pesado...?!",
  ui_story_5089_50890202_36_dialog_content = "<color=#828282>Bater!</color>",
  ui_story_5089_50890202_37_dialog_content = "<color=#e8d9bb>A caixa cai com um estrondo, derrubando sua tampa. Para surpresa de todos, a caixa está cheia até a borda com tesouros deslumbrantes e dourados.</color>",
  ui_story_5089_50890202_38_dialog_content = "PlayerName, é hora de desembarcar—",
  ui_story_5089_50890202_39_dialog_content = "...",
  ui_story_5089_50890202_40_dialog_content = "...",
  ui_story_5089_50890202_41_dialog_content = "...",
  ui_story_5089_50890202_42_dialog_content = "N-Nada está danificado, eu espero? Oh querido, oh céus acima... Eu nunca seria capaz de substituir qualquer coisa disso se eu quebrasse!",
  ui_story_5089_50890202_43_dialog_content = "Uh, pessoal? Tenho quase certeza de que há algo errado com meus olhos.",
  ui_story_5089_50890202_44_dialog_content = "A caixa que o príncipe me deu... Por que parece que está cheia de ouro? Hahaha...",
  ui_story_5089_50890202_45_dialog_content = "... Jiu.",
  ui_story_5089_50890202_46_dialog_content = "<color=#e8d9bb>Jiu aparece repentinamente ao chamado de Dantang. Sem dizer mais uma palavra, ela inspeciona cada caixa dada a eles pelo príncipe herdeiro.</color>",
  ui_story_5089_50890202_47_dialog_content = "Minha inspeção está completa, Senhora Dantang. Além de duas caixas cheias de brinquedos e alguns casos de magatama e pedras preciosas, tudo o resto é ouro.",
  ui_story_5089_50890301_1_dialog_content = "Estamos caminhando há eras... Como ainda não chegamos lá? A estalagem é realmente tão longe do cais...?",
  ui_story_5089_50890301_2_dialog_content = "Não foi você quem insistiu em pegar estradas secundárias por medo de ser roubado? Você não tem ninguém para culpar, além de si mesmo, por convidar o deus da riqueza para sua casa, meu amigo.",
  ui_story_5089_50890301_3_dialog_content = "Não entenda mal! Só estou aterrorizado de ser roubado porque tenho a obrigação de devolver todas essas coisas! Qualquer outra pessoa reagiria da mesma maneira!",
  ui_story_5089_50890301_4_dialog_content = "O príncipe até disse que essas caixas eram apenas \"coisas menores\" para nossa viagem...",
  ui_story_5089_50890301_5_dialog_content = "Para o príncipe herdeiro do Reino de Ji, ouro e prata são apenas objetos triviais.",
  ui_story_5089_50890301_6_dialog_content = "Mas para qualquer outra pessoa... Você poderia facilmente comprar uma cidade inteira no Reino Ye com tanto ouro, PlayerName.",
  ui_story_5089_50890301_7_dialog_content = "Mas não há necessidade de se preocupar. Com Jiu ao nosso lado, nenhum bandido comum poderia sequer esperar se aproximar de nós.",
  ui_story_5089_50890301_8_dialog_content = "Estamos quase na pousada. Está logo no final desta rua.",
  ui_story_5089_50890301_9_dialog_content = "Finalmente, um descanso muito necessário. Esta parte da viagem tem sido tão estressante... Huh? Tem algo errado, Dantang?",
  ui_story_5089_50890301_10_dialog_content = "Não, é só que... Eu me lembro de passar por aqui a caminho do Reino Ji anos atrás.",
  ui_story_5089_50890301_11_dialog_content = "Tongli Town... Um assentamento à beira-mar que faz fronteira com uma das maiores regiões produtoras de grãos do Reino Ye. Pode não se comparar a uma cidade grande, mas certamente estava movimentada na época.",
  ui_story_5089_50890301_12_dialog_content = "No entanto, de alguma forma, parece muito mais desolado desta vez.",
  ui_story_5089_50890301_13_dialog_content = "Então parece que você não esteve aqui por muitos anos, mocinha.",
  ui_story_5089_50890301_14_dialog_content = "Por favor, me esclareça, gentil senhor.",
  ui_story_5089_50890301_15_dialog_content = "Esclarecer você, é? O que posso te ensinar que todos já não sabem?",
  ui_story_5089_50890301_16_dialog_content = "Nos últimos anos, a cidade construiu muitas oficinas grandes, oferecendo salários mensais generosos e atraindo todos os jovens para trabalhar nelas.",
  ui_story_5089_50890301_17_dialog_content = "Se eu não fosse tão velho e decrépito, adoraria trabalhar em um lugar onde não estou à mercê dos elementos.",
  ui_story_5089_50890301_18_dialog_content = "Entendi. May Eu pergunto quanto custa este arroz, gentil senhor?",
  ui_story_5089_50890301_19_dialog_content = "Você está procurando comprar alguns? Devo avisar, o preço dos grãos tem subido nos últimos dois meses, e está um pouco mais alto hoje. Por essa quantidade de arroz—",
  ui_story_5089_50890301_20_dialog_content = "... Entendo. Obrigado.",
  ui_story_5089_50890301_21_dialog_content = "Há algo de errado com aquele saco de arroz?",
  ui_story_5089_50890301_22_dialog_content = "Quando estávamos de volta em Haojin, perguntei sobre o preço do arroz, e parecia combinar com o preço aqui. Isso não deve ser um problema, certo?",
  ui_story_5089_50890301_23_dialog_content = "O custo do arroz em uma pequena cidade como esta é surpreendentemente semelhante ao de Haojin, uma das cidades mais ricas do Império Zhao.",
  ui_story_5089_50890301_24_dialog_content = "Dizer que isso não é um problema não poderia estar mais longe da verdade. Mas como isso pode ser...?",
  ui_story_5089_50890301_25_dialog_content = "<color=#e8d9bb>Pimba!</color>",
  ui_story_5089_50890301_26_dialog_content = "Ah, desculpe por isso! Eu não quis esbarrar em você... Hã? O que é isso nos seus braços...?",
  ui_story_5089_50890301_27_dialog_content = "...!",
  ui_story_5089_50890301_28_dialog_content = "S-Senhor! Você tem que parar aquela criança!",
  ui_story_5089_50890301_29_dialog_content = "Ele está fugindo com sua bagagem!",
  ui_story_5089_50890301_30_dialog_content = "!",
  ui_story_5089_50890301_31_dialog_content = "—!",
  ui_story_5089_50890301_32_dialog_content = "Pare de resistir.",
  ui_story_5089_50890301_33_dialog_content = "Hrngh! Me soltem! Me... SOLTEM!",
  ui_story_5089_50890301_34_dialog_content = "<color=#e8d9bb>O garotinho morde ferozmente a mão de Jiu, mas esta permanece completamente imperturbável, sua expressão é fria e insensível.</color>",
  ui_story_5089_50890301_35_dialog_content = "Devolva o que você roubou.",
  ui_story_5089_50890301_36_dialog_content = "<color=#e8d9bb>Com olhos vermelhos e inchados, o garoto morde ainda mais forte.</color>",
  ui_story_5089_50890301_37_dialog_content = "Jiu!",
  ui_story_5089_50890301_38_dialog_content = "<color=#e8d9bb>Dentro daquele lapso momentâneo de foco, o garoto escapa do aperto de Jiu como um peixe.</color>",
  ui_story_5089_50890301_39_dialog_content = "Pffft!",
  ui_story_5089_50890301_40_dialog_content = "Ei, você—",
  ui_story_5089_50890301_41_dialog_content = "Ajuda! Me salve! Essas pessoas estão tentando me sequestrar!",
  ui_story_5089_50890301_42_dialog_content = "O quê? Quem é estúpido o suficiente para tentar sequestrar uma criança em plena luz do dia?!",
  ui_story_5089_50890301_43_dialog_content = "Aqueles caras ali, os que estão usando aquelas roupas estranhas! Eu sabia que eles eram problema assim que os vi!",
  ui_story_5089_50890301_44_dialog_content = "Chame os guardas da cidade! Prenda esses criminosos!",
  ui_story_5089_50890301_45_dialog_content = "Qu-Que é tudo isso agora? Por favor, não sejam precipitados! Eu asseguro a vocês que estamos todos do mesmo lado, então vamos apenas conversar sobre as coisas com calma e racionalidade!",
  ui_story_5089_50890301_46_dialog_content = "Ninguém está do seu lado, criminoso!",
  ui_story_5089_50890301_47_dialog_content = "Argh, há muitas pessoas aqui! Aquela criança está fugindo!",
  ui_story_5089_50890301_48_dialog_content = "Afaste-se da princesa!",
  ui_story_5089_50890301_49_dialog_content = "Está tudo bem, Jiu. Eles são apenas cidadãos comuns preocupados com a própria segurança.",
  ui_story_5089_50890301_50_dialog_content = "Mas e se...",
  ui_story_5089_50890301_51_dialog_content = "Você é mais rápido sem mim, então pegue PlayerName e vá encontrar aquela criança. Eu vou lidar com o resto dos moradores da cidade.",
  ui_story_5089_50890301_52_dialog_content = "Não posso fazer isso, Alteza. Minhas ordens são para protegê-lo.",
  ui_story_5089_50890301_53_dialog_content = "Então considere isso uma ordem minha. Agora vá.",
  ui_story_5089_50890301_54_dialog_content = "... Sim, Sua Alteza.",
  ui_story_5089_50890301_55_dialog_content = "Por favor, fique perto de mim, PlayerName.",
  ui_story_5089_50890301_56_dialog_content = "Como aquela criança conseguiu escapar tão rapidamente?",
  ui_story_5089_50890301_57_dialog_content = "Suspiro... Eu tinha a sensação de que algo assim aconteceria assim que vi aquele monte de ouro.",
  ui_story_5089_50890301_58_dialog_content = "Ainda assim, estou surpreso que a pessoa que me roubou era apenas uma criança.",
  ui_story_5089_50890301_59_dialog_content = "Ele estava vestido em trapos, no entanto. Tenho certeza de que ele também enfrentou sua parcela de dificuldades.",
  ui_story_5089_50890301_60_dialog_content = "...",
  ui_story_5089_50890301_61_dialog_content = "Você não vai falar comigo a menos que seja absolutamente necessário, vai?",
  ui_story_5089_50890301_62_dialog_content = "...",
  ui_story_5089_50890301_63_dialog_content = "Sei que sou apenas um estrangeiro e ainda tenho muito a aprender sobre Longzhou. Seria arrogante da minha parte dizer que entendo sua situação.",
  ui_story_5089_50890301_64_dialog_content = "Mas conheci muitas pessoas diferentes ao longo das minhas viagens.",
  ui_story_5089_50890301_65_dialog_content = "Alguns deles se sacrificaram voluntariamente por suas crenças e se tornaram faróis para a chegada da alvorada.",
  ui_story_5089_50890301_66_dialog_content = "Algumas pessoas estavam dispostas a destruir tudo por seus sonhos, mesmo que isso significasse cair no abismo mais escuro.",
  ui_story_5089_50890301_67_dialog_content = "Não tenho o direito de julgar seus acertos ou erros, e definitivamente não estou qualificado para definir a vida de outras pessoas em poucas palavras. Acho que é isso que estou tentando dizer.",
  ui_story_5089_50890301_68_dialog_content = "É que só há uma maneira de não realizar nada, e isso é não fazer nada.",
  ui_story_5089_50890301_69_dialog_content = "Sou um guerreiro sob o comando do Rei de Ye e um guarda encarregado da proteção da Princesa Dantang.",
  ui_story_5089_50890301_70_dialog_content = "Meu dever é obedecer ordens e cumprir minhas responsabilidades sem hesitação.",
  ui_story_5089_50890301_71_dialog_content = "Não há necessidade de eu mudar nada.",
  ui_story_5089_50890301_72_dialog_content = "Então, deixe-me perguntar algo. O que você faria se o rei e o Dantang lhe dessem ordens conflitantes?",
  ui_story_5089_50890301_73_dialog_content = "Tanto o rei quanto a princesa são governantes benevolentes que carregam o sofrimento de seus súditos em seus corações. Eles se dedicam inteiramente aos interesses do Reino de Ye.",
  ui_story_5089_50890301_74_dialog_content = "Essa resposta não é muito convincente, sabe.",
  ui_story_5089_50890301_75_dialog_content = "Eu...",
  ui_story_5089_50890301_76_dialog_content = "Ainda não há sinal daquela criança, hein? Talvez eu deva tentar sentir a localização dele.",
  ui_story_5089_50890301_77_dialog_content = "Varredura Psíquica!",
  ui_story_5089_50890301_78_dialog_content = "Ali! Ele está em um beco ao sul de nós—Huh?",
  ui_story_5089_50890301_79_dialog_content = "Pffff—",
  ui_story_5089_50890301_80_dialog_content = "Aquele garoto...",
  ui_story_5089_50890301_81_dialog_content = "(Eh? Acho que tropecei em alguma coisa...)",
  ui_story_5089_50890301_82_dialog_content = "<color=#e8d9bb>Barulho, barulho!</color>",
  ui_story_5089_50890301_83_dialog_content = "<color=#e8d9bb>Um feixe de varas de bambu cai estrondosamente.</color>",
  ui_story_5089_50890301_84_dialog_content = "Uma armadilha?!",
  ui_story_5089_50890301_85_dialog_content = "(E-Eu tenho que sair do caminho!)",
  ui_story_5089_50890301_86_dialog_content = "<color=#e8d9bb>Como se antecipando ao próximo movimento do invasor, os tijolos de pedra logo abaixo da armadilha desabaram em um buraco bem escondido.</color>",
  ui_story_5089_50890301_87_dialog_content = "<color=#e8d9bb>Sploosh!</color>",
  ui_story_5089_50890301_88_dialog_content = "<color=#e8d9bb>Um balde de madeira cheio de água cai do céu—</color>",
  ui_story_5089_50890301_89_dialog_content = "Ahhhh!",
  ui_story_5089_50890301_90_dialog_content = "Cuidado.",
  ui_story_5089_50890301_91_dialog_content = "<color=#e8d9bb>Jiu avança rapidamente como uma rajada de vento invisível.</color>",
  ui_story_5089_50890301_92_dialog_content = "<color=#e8d9bb>Ágil, ela atinge o balde com a ponta de sua lâmina não desembainhada, desviando-o de seu alvo pretendido.</color>",
  ui_story_5089_50890301_93_dialog_content = "<color=#e8d9bb>Com um leve tum, ele pousa graciosamente aos pés do garoto sem derramar sequer uma única gota de água.</color>",
  ui_story_5089_50890301_94_dialog_content = "<color=#e8d9bb>Ao mesmo tempo, os postes de bambu em cascata pairam no ar por um breve momento antes de se dividirem em inúmeras peças e caírem inofensivamente no chão..</color>",
  ui_story_5089_50890301_95_dialog_content = "<color=#e8d9bb>Em algum momento, eles foram cortados ao meio limpidamente.</color>",
  ui_story_5089_50890301_96_dialog_content = "Th-Isso... foi incrível.",
  ui_story_5089_50890301_97_dialog_content = "Como ela...",
  ui_story_5089_50890301_98_dialog_content = "Devolva o que você roubou. Não vou dizer novamente.",
  ui_story_5089_50890301_99_dialog_content = "... Eu não sei do que você está falando!!",
  ui_story_5089_50890301_100_dialog_content = "Pare—",
  ui_story_5089_50890301_101_dialog_content = "Espere, Jiu.",
  ui_story_5089_50890301_102_dialog_content = "Ele passou por muitos problemas para montar essas armadilhas, e até ficou aqui quando não precisava. Provavelmente há uma boa razão para isso.",
  ui_story_5089_50890301_103_dialog_content = "Os itens roubados devem estar escondidos na casa ao lado.",
  ui_story_5089_50890301_104_dialog_content = "!",
  ui_story_5089_50890301_105_dialog_content = "Ei, pare com isso! Eu sou o único que roubou suas coisas, então venha e me pegue!",
  ui_story_5089_50890301_106_dialog_content = "Eu sabia.",
  ui_story_5089_50890301_107_dialog_content = "Eu não vou entrar ainda, mas você estaria disposto a se acalmar e conversar conosco em troca?",
  ui_story_5089_50890301_108_dialog_content = "Não somos pessoas más, eu prometo. Na verdade, se você está passando por momentos difíceis, talvez possamos até ajudar.",
  ui_story_5089_50890301_109_dialog_content = "... Na verdade, eu...",
  ui_story_5089_50890301_110_dialog_content = "Passo para trás!",
  ui_story_5089_50890301_111_dialog_content = "O quê...?!",
  ui_story_5089_50890301_112_dialog_content = "<color=#e8d9bb>Zuuup...</color>",
  ui_story_5089_50890301_113_dialog_content = "<color=#e8d9bb>Jiu desenha sua lâmina mais rápido do que qualquer um pode ver.</color>",
  ui_story_5089_50890301_114_dialog_content = "<color=#828282>Ding!</color>",
  ui_story_5089_50890301_115_dialog_content = "<color=#e8d9bb>Com um floreio, ela desvia de vários fios de metal poderosos e extremamente finos.</color>",
  ui_story_5089_50890301_116_dialog_content = "Aí está você.",
  ui_story_5089_50890301_117_dialog_content = "Quem são—",
  ui_story_5089_50890301_118_dialog_content = "<color=#e8d9bb>Sem responder, a figura misteriosa desencadeia outro ataque impiedoso com fio!</color>",
  ui_story_5089_50890302_1_dialog_content = "Agora é sua chance, Jiu! Leve-o para baixo!",
  ui_story_5089_50890302_2_dialog_content = "Hunf.",
  ui_story_5089_50890302_3_dialog_content = "<color=#e8d9bb>Agora deitado no chão, o assassino de repente levanta o braço e lança um ataque furtivo com seus fios!</color>",
  ui_story_5089_50890302_4_dialog_content = "Ugh!",
  ui_story_5089_50890302_5_dialog_content = "<color=#e8d9bb>Gotejamento.</color>",
  ui_story_5089_50890302_6_dialog_content = "<color=#e8d9bb>Uma única gota de sangue carmesim cai silenciosamente no chão sujo.</color>",
  ui_story_5089_50890302_7_dialog_content = "Jiu...!",
  ui_story_5089_50890302_8_dialog_content = "<color=#e8d9bb>Jiu fica diante de seu atacante, seu fio preso em suas mãos nuas.</color>",
  ui_story_5089_50890302_9_dialog_content = "Peço desculpas por assustá-lo, Senhor PlayerName.",
  ui_story_5089_50890302_10_dialog_content = "<color=#e8d9bb>De repente, ela junta as mãos e puxa com toda a sua força.</color>",
  ui_story_5089_50890302_11_dialog_content = "<color=#e8d9bb>O assassino, que tentou escapar saltando, é puxado por um fio de metal vermelho-sangue e cai pesadamente no chão.</color>",
  ui_story_5089_50890302_12_dialog_content = "Um momento enquanto eu o prendo.",
  ui_story_5089_50890302_13_dialog_content = "Droga... Se ao menos fosse alguém além daquele demônio mascarado...",
  ui_story_5089_50890302_14_dialog_content = "Venha pacificamente e sua vida pode ser poupada.",
  ui_story_5089_50890302_15_dialog_content = "Lâmina de Gelo... Eu posso ser apenas um batedor, mas ambos respondemos diretamente ao rei. Isso significa que estamos do mesmo lado, não é?",
  ui_story_5089_50890302_16_dialog_content = "Estou simplesmente tentando cumprir minha missão. Você realmente pretende me impedir de cumprir as ordens do nosso rei?",
  ui_story_5089_50890302_17_dialog_content = "...",
  ui_story_5089_50890302_18_dialog_content = "Você está de volta, Jiu! Como estão suas feridas? Aquele assassino agora há pouco...",
  ui_story_5089_50890302_19_dialog_content = "Perdoe-me, eu... eu o deixei escapar.",
  ui_story_5089_50890302_20_dialog_content = "Contanto que você esteja bem, então está tudo bem... Espere, não, não está nada bem!",
  ui_story_5089_50890302_21_dialog_content = "Por que você acabou de usar sua mão para bloquear o ataque dele?! Você não sente dor ou algo assim?! Aqui, deixe-me ver suas feridas!",
  ui_story_5089_50890302_22_dialog_content = "São apenas arranhões, PlayerName, nada mais. Eu posso cuidar deles sozinho.",
  ui_story_5089_50890302_23_dialog_content = "De novo? Ah... Deixa pra lá. Faça o que quiser, vou lidar com as crianças.",
  ui_story_5089_50890302_24_dialog_content = "\"Crianças\"?",
  ui_story_5089_50890302_25_dialog_content = "Isso mesmo, aquelas duas crianças de antes. Eles estão naquela casa ali.",
  ui_story_5089_50890302_26_dialog_content = "Aaaaaah! Estou tão assustado!",
  ui_story_5089_50890302_27_dialog_content = "J-Apenas pare de chorar, pode? Olha, eu trouxe algumas coisas realmente legais para você hoje!",
  ui_story_5089_50890302_28_dialog_content = "Viu? Muitos brinquedos fofos e uma linda lanterna, só para você!",
  ui_story_5089_50890302_29_dialog_content = "E olhe todos esses livros de histórias! Quer que eu leia um para você? Vamos lá, não chore...",
  ui_story_5089_50890302_30_dialog_content = "Aaaaaaaaaaa!",
  ui_story_5089_50890302_31_dialog_content = "E foi isso que aconteceu. A criança nunca roubou nenhum ouro do príncipe. Tudo que ele queria era uma caixa cheia de brinquedos.",
  ui_story_5089_50890302_32_dialog_content = "Quem se importa com o seu ouro fedido?",
  ui_story_5089_50890302_33_dialog_content = "Aaaaaaah! Outra pessoa assustadora!",
  ui_story_5089_50890302_34_dialog_content = "Ah, ótimo. Agora veja o que você fez! Apenas saia daqui já! Pronto, pronto, não chore! Eu vou te dar o que você quiser, eu prometo!",
  ui_story_5089_50890302_35_dialog_content = "...",
  ui_story_5089_50890302_36_dialog_content = "Jiu?",
  ui_story_5089_50890302_37_dialog_content = "<color=#e8d9bb>Jiu se agacha na frente da garotinha, levanta a mão de forma desajeitada e coloca sua máscara na cabeça da menina.</color>",
  ui_story_5089_50890302_38_dialog_content = "O-o que você pensa que está fazendo?! Se você encostar um dedo nela—",
  ui_story_5089_50890302_39_dialog_content = "O vento está aqui, a chuva está aqui, o Rei Dragão bate seu tambor.",
  ui_story_5089_50890302_40_dialog_content = "Sob esta máscara, você encontrará um lugar para se esconder, meu pequenino.",
  ui_story_5089_50890302_41_dialog_content = "E nós vamos comer um melão ao sol quando a tempestade passar.",
  ui_story_5089_50890302_42_dialog_content = "<color=#e8d9bb>Enquanto Jiu recita suavemente a canção de ninar, os soluços da garota escondida atrás da máscara diminuem gradualmente.</color>",
  ui_story_5089_50890302_43_dialog_content = "(Eu não tinha ideia de que Jiu poderia ser tão gentil.)",
  ui_story_5089_50890302_44_dialog_content = "PlayerName! Jiu! Graças a Deus finalmente te encontrei!",
  ui_story_5089_50890302_45_dialog_content = "Oh? O que está acontecendo aqui? Por que Jiu decidiu tirar a máscara dela?",
  ui_story_5089_50890302_46_dialog_content = "Sua Alteza! Eu estava apenas...",
  ui_story_5089_50890302_47_dialog_content = "Hum, com licença...",
  ui_story_5089_50890302_48_dialog_content = "Hã?",
  ui_story_5089_50890302_49_dialog_content = "P-Poderia cantar aquela música mais uma vez?",
  ui_story_5089_50890302_50_dialog_content = "É apenas como... A que minha mãe costumava cantar.",
  ui_story_5089_50890302_51_dialog_content = "De nada.",
  ui_story_5089_50890302_52_dialog_content = "Sério? Então meus amigos podem vir e ouvir também?",
  ui_story_5089_50890302_53_dialog_content = "Seus amigos...?",
  ui_story_5089_50890302_54_dialog_content = "Grande irmão Ergou! Vá chamar os outros!",
  ui_story_5089_50890302_55_dialog_content = "Acho que eles não são tão ruins afinal. Só um segundo, vou procurá-los.",
  ui_story_5089_50890302_56_dialog_content = "O que está acontecendo, Xiaohua? Por que nos chamou?",
  ui_story_5089_50890302_57_dialog_content = "Realmente importa? Não é como se tivéssemos algo melhor para fazer.",
  ui_story_5089_50890302_58_dialog_content = "O que todos esses adultos estão fazendo aqui...?",
  ui_story_5089_50890302_59_dialog_content = "Por que há tantas crianças aqui?",
  ui_story_5089_50890302_60_dialog_content = "O estalajadeiro teve a gentileza de me informar sobre a situação aqui na cidade. Permita-me explicar.",
  ui_story_5089_50890302_61_dialog_content = "Lembre-se do que aquele cavalheiro mais velho disse sobre as oficinas da cidade e como a maioria das pessoas aptas da cidade saiu para trabalhar nelas? Por mais lucrativos que esses empregos possam ser, eles ainda exigem que os trabalhadores deixem suas casas para trás.",
  ui_story_5089_50890302_62_dialog_content = "Como tal, muitas crianças foram deixadas aos cuidados de seus avós, que não podem ser esperados para vigiá-las em todas as horas do dia.",
  ui_story_5089_50890302_63_dialog_content = "Sem supervisão, essas crianças tendem a se reunir e correr à vontade.",
  ui_story_5089_50890302_64_dialog_content = "Então eles não são realmente parentes de sangue? Eu pensei que esses dois eram irmão e irmã, então eu...",
  ui_story_5089_50890302_65_dialog_content = "Xiaohua ainda é minha irmã. Meus pais morreram cedo, mas a família dela tem me alimentado todo esse tempo.",
  ui_story_5089_50890302_66_dialog_content = "Então, é claro, concordei em cuidar dela quando me disseram que estavam saindo para trabalhar há alguns dias.",
  ui_story_5089_50890302_67_dialog_content = "Mas Xiaohua realmente sente falta dos pais dela. Ela tem chorado nos últimos dias, então é por isso que eu...",
  ui_story_5089_50890302_68_dialog_content = "Queria animá-la com alguns brinquedos?",
  ui_story_5089_50890302_69_dialog_content = "Sim. Mas agora que você me pegou, aceito qualquer surra ou bronca que você tenha para mim.",
  ui_story_5089_50890302_70_dialog_content = "Mesmo que roubar seja errado, como eu poderia possivelmente repreender você depois de saber de tudo isso?",
  ui_story_5089_50890302_71_dialog_content = "Ah, o que devemos fazer com essas crianças? Agora que elas cercaram Jiu, parece que ela está totalmente presa.",
  ui_story_5089_50890302_72_dialog_content = "Então você deve correr para ajudá-la imediatamente, PlayerName.",
  ui_story_5089_50890302_73_dialog_content = "Mas o que eu faço?",
  ui_story_5089_50890302_74_dialog_content = "Pedir para Jiu cantar para tantas pessoas é um pouco demais, até mesmo para ela. Devemos tentar aliviar o fardo para ela.",
  ui_story_5089_50890302_75_dialog_content = "Vamos, vamos buscar minha pipa na estalajaria.",
  ui_story_5089_50890302_76_dialog_content = "Fui informado há muito tempo que você é bastante habilidoso no piano, mas nunca ouvi você tocar. Estaria disposto a se juntar a mim para um dueto hoje?",
  ui_story_5089_50890302_77_dialog_content = "Eu adoraria, mas não vejo um piano aqui.",
  ui_story_5089_50890302_78_dialog_content = "Ah, isso não deve ser um problema.",
  ui_story_5089_50890302_79_dialog_content = "Os músicos do passado podiam improvisar uma melodia com objetos do dia a dia. Não vejo motivo para um celestita não poder fazer o mesmo, especialmente quando temos todos esses copos.",
  ui_story_5089_50890302_80_dialog_content = "Viu? Podemos produzir todos os tipos de notas ao enchê-las com diferentes quantidades de água e batendo nelas assim.",
  ui_story_5089_50890302_81_dialog_content = "Acho que posso tentar.",
  ui_story_5089_50890302_82_dialog_content = "Jiu, você ainda se lembra do que eu te disse quando visitamos Twin Pavilions Bay pela primeira vez?",
  ui_story_5089_50890302_83_dialog_content = "Se, um dia, eu pudesse fazer um dueto com o pianista, espero que você venha e faça uma dança com sua espada.",
  ui_story_5089_50890302_84_dialog_content = "M-M-Mas há tantas pessoas...",
  ui_story_5089_50890302_85_dialog_content = "Você não está sozinho, Jiu. Nós também estamos com você.",
  ui_story_5089_50890302_86_dialog_content = "Se for demais pedir, eu não vou te forçar. É só que a apresentação de hoje pode ser um pouco deficiente sem a sua ajuda.",
  ui_story_5089_50890302_87_dialog_content = "U-Entendido...",
  ui_story_5089_50890302_88_dialog_content = "Que vergonha.",
  ui_story_5089_50890302_89_dialog_content = "Hehe, eu mal acredito nisso. Apenas olhe como os olhos das crianças estão brilhando intensamente, Jiu!",
  ui_story_5089_50890302_90_dialog_content = "Para eles, sua dança da espada é a melhor do mundo!",
  ui_story_5089_50890302_91_dialog_content = "Você me lisonjeia, Alteza. Estou apenas fazendo o meu melhor para evitar fazer ainda mais papel de bobo.",
  ui_story_5089_50890302_92_dialog_content = "Minha nossa, olhe só para essa performance esplêndida! Há algo que eu possa fazer para contribuir?",
  ui_story_5089_50890302_93_dialog_content = "Talvez uma música jubilosa para animar a todos?",
  ui_story_5089_50890302_94_dialog_content = "Oh? Quais músicas você conhece?",
  ui_story_5089_50890302_95_dialog_content = "Aham, deixa eu ver...",
  ui_story_5089_50890302_96_dialog_content = "De sul a norte, trazemos para você o nosso maravilhoso show!",
  ui_story_5089_50890302_97_dialog_content = "Seja você príncipe ou mendigo, não importa. No entanto, suas moedas sobressalentes significariam muito!",
  ui_story_5089_50890302_98_dialog_content = "<color=#e8d9bb>Ding.</color>",
  ui_story_5089_50890302_99_dialog_content = "<color=#e8d9bb>Surpreendentemente, vários moradores desavisados ​​jogam algumas moedas para ele.</color>",
  ui_story_5089_50890302_100_dialog_content = "Li Tianxian!",
  ui_story_5089_50890302_101_dialog_content = "É-E tudo faz parte do show, Sua Alteza! Lembre-se de se concentrar na música!",
  ui_story_5089_50890302_102_dialog_content = "<color=#e8d9bb>Uma tempestade iminente e um grupo diversificado de artistas improváveis, cada um com suas próprias preocupações.</color>",
  ui_story_5089_50890302_103_dialog_content = "<color=#e8d9bb>Longe de uma performance perfeita, o show deles é mais uma coincidência caprichosa.</color>",
  ui_story_5089_50890302_104_dialog_content = "<color=#e8d9bb>Mas pelo menos, este momento—</color>",
  ui_story_5089_50890302_105_dialog_content = "<color=#e8d9bb>Merece uma música própria.</color>",
  ui_story_5089_50890401_1_dialog_content = "O que você está virando em suas mãos, PlayerName?",
  ui_story_5089_50890401_2_dialog_content = "Você quer dizer isso? É apenas uma estatueta de bronze. Er Gou me devolveu antes de nos separarmos mais cedo.",
  ui_story_5089_50890401_3_dialog_content = "Xiaohua não quis mais brinquedos depois que ela recebeu aquela máscara de Jiu, então Ergou entregou tudo o que ele roubou.",
  ui_story_5089_50890401_4_dialog_content = "E como um pedido de desculpas, ele também me deu isso.",
  ui_story_5089_50890401_5_dialog_content = "Ele disse que uma senhora simpática deu a ele enquanto passava pela cidade. Ele diz que é chamado de boneca Moheluo.",
  ui_story_5089_50890401_6_dialog_content = "Havia um monte de pessoas seguindo ela também. Eles vestiam todo de preto e mal disseram uma palavra o tempo todo, era tão assustador!",
  ui_story_5089_50890401_7_dialog_content = "Mas ela era uma pessoa boa, sem dúvida. Ela até nos convidou para um dos maiores albergues para jantar e nos deu toda a carne que podíamos comer!",
  ui_story_5089_50890401_8_dialog_content = "Ela também é bastante inteligente. Todas as armadilhas que montamos no beco foram feitas usando os projetos dela.",
  ui_story_5089_50890401_9_dialog_content = "Ela disse que eles são os fundamentos das técnicas de armadilhas, e que poderíamos nos tornar mais inteligentes ao entendê-los.",
  ui_story_5089_50890401_10_dialog_content = "Ela mencionou o nome dela de alguma forma?",
  ui_story_5089_50890401_11_dialog_content = "Não... Ela e seus seguidores só ficaram na cidade por um dia, e eles saíram tão rápido quanto chegaram. Mas isso me lembra!",
  ui_story_5089_50890401_12_dialog_content = "Ela tinha um hábito estranho de carregar um guarda-chuva enorme para onde quer que fosse, mesmo que nunca tivesse chovido enquanto ela estava aqui!",
  ui_story_5089_50890401_13_dialog_content = "Isso soa como alguém que conhecemos, não é?",
  ui_story_5089_50890401_14_dialog_content = "É verdade que esta rota é o caminho mais rápido para retornar ao Reino Ji. Talvez a Ministra Armilla realmente tenha passado por aqui?",
  ui_story_5089_50890401_15_dialog_content = "Ainda assim, para ela brincar com as crianças e oferecer-lhes jantares luxuosos, tudo isso enquanto carrega suas armas em plena luz do dia...",
  ui_story_5089_50890401_16_dialog_content = "Parece que o criminoso mais procurado em todo o Reino de Ye está vivendo uma vida bastante despreocupada.",
  ui_story_5089_50890401_17_dialog_content = "Mas com todas aquelas pessoas de preto seguindo-a, ela provavelmente não consegue se mover tão livremente quanto gostaria.",
  ui_story_5089_50890401_18_dialog_content = "Desculpe-me PlayerName, mas posso ver essa miniatura por um momento?",
  ui_story_5089_50890401_19_dialog_content = "Claro. Eu tenho tentado sentir isso para obter informações úteis, mas não encontrei nada.",
  ui_story_5089_50890401_20_dialog_content = "Parece que nossas mentes pensam igual. Se houver alguma informação a ser encontrada, pode muito bem estar escondida dentro desta boneca...",
  ui_story_5089_50890401_21_dialog_content = "<color=#e8d9bb>Tarde da noite</color>",
  ui_story_5089_50890401_22_dialog_content = "*bocejar*",
  ui_story_5089_50890401_23_dialog_content = "Ugh, minha garganta está tão seca. Preciso de água...",
  ui_story_5089_50890401_24_dialog_content = "Ah, a chaleira está vazia... Melhor ir verificar o corredor.",
  ui_story_5089_50890401_25_dialog_content = "Huh? A luz ainda está acesa ali. Não é o quarto do Dantang?",
  ui_story_5089_50890401_26_dialog_content = "É você lá fora, PlayerName?",
  ui_story_5089_50890401_27_dialog_content = "Eh? Você pode me ver ou algo assim?",
  ui_story_5089_50890401_28_dialog_content = "Não, mas eu poderia dizer pelo som dos seus passos. Por favor, entre.",
  ui_story_5089_50890401_29_dialog_content = "Aquela boneca de novo... Você ainda está estudando ela?",
  ui_story_5089_50890401_30_dialog_content = "Sim. Quer ela tenha pretendido deixar isso para trás ou não, tenho certeza de que esta boneca guarda algum conhecimento sobre a Ministra Armilla.",
  ui_story_5089_50890401_31_dialog_content = "Então, o que exatamente é uma boneca Moheluo?",
  ui_story_5089_50890401_32_dialog_content = "É um tipo de brinquedo que era popular no passado. No entanto, geralmente é esculpido em argila ou madeira, não em metal.",
  ui_story_5089_50890401_33_dialog_content = "E ainda assim, essa é feita de bronze, certo?",
  ui_story_5089_50890401_34_dialog_content = "Correto, e a Ministra Armilla é muito habilidosa com bronze. Na verdade, sua primeira fama veio de um conjunto de marionetes mecânicas musicais que ela projetou e criou pessoalmente.",
  ui_story_5089_50890401_35_dialog_content = "Ela tocou música ao lado desses manequins, e não foi até o final do show que seu público percebeu que algo estava errado. Foi quando eles perceberam que os músicos eram todos marionetes mecânicas.",
  ui_story_5089_50890401_36_dialog_content = "Estou impressionado que Xuan Ji pode criar fantoches tão incríveis... Então por que este é tão grosseiro e feio?",
  ui_story_5089_50890401_37_dialog_content = "Esse é outro ponto estranho que eu gostaria de mencionar.",
  ui_story_5089_50890401_38_dialog_content = "As bonecas Moheluo são normalmente feitas à semelhança de uma criança fofa e adorável, mas esta é enrugada e grotesca.",
  ui_story_5089_50890401_39_dialog_content = "Além disso, ele é feito para segurar uma folha de lótus ou flor na mão.",
  ui_story_5089_50890401_40_dialog_content = "Embora essa miniatura esteja de fato segurando uma flor, uma inspeção mais próxima revela ser uma magnólia.",
  ui_story_5089_50890401_41_dialog_content = "Uma espécie prospera debaixo d'água enquanto a outra teme a inundação. Eles são tão incompatíveis quanto água e fogo.",
  ui_story_5089_50890401_42_dialog_content = "Esta boneca se assemelha a uma boneca Moheluo em muitos aspectos, e ainda assim não poderia ser mais diferente. Só posso descrevê-la como um substituto, ou até mesmo uma falsificação.",
  ui_story_5089_50890401_43_dialog_content = "Um substituto ou um falso, hein...",
  ui_story_5089_50890401_44_dialog_content = "No passado, também havia uma peça com o exato mesmo nome.",
  ui_story_5089_50890401_45_dialog_content = "A maioria das pessoas não é muito familiarizada com a peça em si, mas uma de suas falas é extremamente conhecida e reconhecida por todos.",
  ui_story_5089_50890401_46_dialog_content = "Qual é essa linha?",
  ui_story_5089_50890401_47_dialog_content = "\"Você pode pintar o pelo de um tigre, mas não sua alma. Você pode ver o rosto de uma pessoa, mas não o coração dela.\"",
  ui_story_5089_50890401_48_dialog_content = "<color=#e8d9bb>Snap!</color>",
  ui_story_5089_50890401_49_dialog_content = "!",
  ui_story_5089_50890401_50_dialog_content = "Quem vai lá?!",
  ui_story_5089_50890402_1_dialog_content = "Fugindo diante da derrota? Pelo menos, eu medi suas capacidades hoje.",
  ui_story_5089_50890402_2_dialog_content = "Eram aqueles Fate Riders agora há pouco? Ou eram eles...",
  ui_story_5089_50890402_3_dialog_content = "Não tenho certeza.",
  ui_story_5089_50890402_4_dialog_content = "Mas, como as coisas estão, não há distinção entre eles e os espiões do Reino Ye.",
  ui_story_5089_50890402_5_dialog_content = "Felizmente, não havia muitos deles, e suas artes marciais eram medianas.",
  ui_story_5089_50890402_6_dialog_content = "Eles foram excelentes em fazer uma retirada apressada, o que me leva a supor que eram apenas batedores coletando informações.",
  ui_story_5089_50890402_7_dialog_content = "Mas isso significa que fomos descobertos, não é? Não deveríamos sair imediatamente?",
  ui_story_5089_50890402_8_dialog_content = "Diga-me, PlayerName, você notou algo estranho?",
  ui_story_5089_50890402_9_dialog_content = "O que você... Espere aí!",
  ui_story_5089_50890402_10_dialog_content = "Fizemos um alvoroço enorme agora... Mas Jiu não está à vista!",
  ui_story_5089_50890402_11_dialog_content = "Por que esses caras ainda não voltaram? Eles não foram mortos, foram?",
  ui_story_5089_50890402_12_dialog_content = "Hmph, se eles não conseguem lidar com algo tão pequeno, então merecem morrer.",
  ui_story_5089_50890402_13_dialog_content = "*suspiro* Suponho que essa seja a nossa sina na vida. Esqueça-os, e eu vou ao banheiro.",
  ui_story_5089_50890402_14_dialog_content = "Não se mexa.",
  ui_story_5089_50890402_15_dialog_content = "!",
  ui_story_5089_50890402_16_dialog_content = "A-Tudo bem, você me pegou. Eu não vou me mover.",
  ui_story_5089_50890402_17_dialog_content = "Se você conseguiu se infiltrar em nosso acampamento e me fazer refém assim, então definitivamente não sou páreo para você.",
  ui_story_5089_50890402_18_dialog_content = "Então, você poderia, por favor, afastar um pouco a sua lâmina do meu pescoço? Afinal, não conseguirei responder a nenhuma pergunta se a sua mão acontecer a escorregar.",
  ui_story_5089_50890402_19_dialog_content = "Por quê você está aqui? Quais são suas ordens?",
  ui_story_5089_50890402_20_dialog_content = "Há um motivo específico pelo qual você está...",
  ui_story_5089_50890402_21_dialog_content = "Chega. Responda a pergunta.",
  ui_story_5089_50890402_22_dialog_content = "C-Como desejar. Estamos simplesmente seguindo a ordem do nosso mestre para trazer sua filha desobediente de volta para sua casa.",
  ui_story_5089_50890402_23_dialog_content = "Estamos apenas ajudando com pequenas questões familiares, só isso. Não fizemos nada ilegal.",
  ui_story_5089_50890402_24_dialog_content = "Ajudar com um \"pequeno assunto de família\" geralmente requer tantos guerreiros?",
  ui_story_5089_50890402_25_dialog_content = "Você pode nos culpar? A casa do nosso mestre é grandiosa e sua filha é protegida por um dos soldados mais formidáveis do reino.",
  ui_story_5089_50890402_26_dialog_content = "Nosso mestre pessoalmente a designou para sua amada filha, mas ela parece ter se rebelado junto com sua protegida.",
  ui_story_5089_50890402_27_dialog_content = "Nosso mestre está bastante desapontado com ambos.",
  ui_story_5089_50890402_28_dialog_content = "...",
  ui_story_5089_50890402_29_dialog_content = "Como eu disse, é um assunto familiar pequeno, e é melhor deixar em suas mãos.",
  ui_story_5089_50890402_30_dialog_content = "Apesar de sua raiva, nosso mestre nunca machucaria sua filha de maneira alguma.",
  ui_story_5089_50890402_31_dialog_content = "Mesmo que ela continue sendo irracional, nenhum mal lhe acontecerá. No pior dos casos, ela será confinada em sua casa e forçada a escrever os éditos de sua família repetidamente.",
  ui_story_5089_50890402_32_dialog_content = "Por outro lado, sua guarda ameaçou os planos de nossa mestra ao abandonar seus deveres.",
  ui_story_5089_50890402_33_dialog_content = "Só posso imaginar sua dor depois de passar todos esses anos, apenas para criar um traidor ingrato. O que você acha disso—",
  ui_story_5089_50890402_34_dialog_content = "Olá? Você ainda está aí?",
  ui_story_5089_50890402_35_dialog_content = "Hehe.",
  ui_story_5089_50890402_36_dialog_content = "Por que demorou tanto?",
  ui_story_5089_50890402_37_dialog_content = "Desculpe, parei para conversar com um velho amigo agora mesmo.",
  ui_story_5089_50890402_38_dialog_content = "Faça-me um favor e passe uma mensagem para nossos espiões quando eles voltarem.",
  ui_story_5089_50890402_39_dialog_content = "Diga a eles que teremos a princesa em casa até o final de amanhã.",
  ui_story_5089_50890402_40_dialog_content = "E se aquele demônio mascarado se colocar em nosso caminho, considere isso um ato de alta traição...",
  ui_story_5089_50890402_41_dialog_content = "Punível com a morte.",
  ui_story_5089_50890402_42_dialog_content = "... Sua Alteza? PlayerName? Por que vocês dois estão fora?",
  ui_story_5089_50890402_43_dialog_content = "Onde estava você, Jiu? Nós acabamos de chegar—",
  ui_story_5089_50890402_44_dialog_content = "PlayerName.",
  ui_story_5089_50890402_45_dialog_content = "Está tarde. Devemos nos retirar para nossos quartos pelo resto da noite.",
  ui_story_5089_50890402_46_dialog_content = "Ainda tenho muito a considerar, se você não se importa.",
  ui_story_5089_50890402_47_dialog_content = "... Tá bem.",
  ui_story_5089_50890402_48_dialog_content = "Boa noite, Dantang. Você também, Jiu.",
  ui_story_5089_50890402_49_dialog_content = "Boa noite, PlayerName.",
  ui_story_5089_50890402_50_dialog_content = "...",
  ui_story_5089_50890402_51_dialog_content = "<color=#e8d9bb>No dia seguinte</color>",
  ui_story_5089_50890402_52_dialog_content = "Mestre Li? May Posso atrapalhar por um momento?",
  ui_story_5089_50890402_53_dialog_content = "Nngh... Ainda estou sonhando? O sol nasceu do oeste hoje?",
  ui_story_5089_50890402_54_dialog_content = "O que te levou a falar comigo tão educadamente hoje, Sua Alteza?",
  ui_story_5089_50890402_55_dialog_content = "... Eu preciso que você faça uma adivinhação para mim.",
  ui_story_5089_50890402_56_dialog_content = "Nossa, que ocorrência verdadeiramente rara.",
  ui_story_5089_50890402_57_dialog_content = "O que será hoje, Sua Alteza? As maquinações do destino? Uma previsão de fortunas? Ou talvez algo mais urgente, como perspectivas de casamento?",
  ui_story_5089_50890402_58_dialog_content = "Eu... Simplesmente queria perguntar sobre o caminho à frente.",
  ui_story_5089_50890402_59_dialog_content = "Tenho um certo assunto em mãos, mas não sei como prosseguir com ele... Ou se posso até mesmo fazer isso, para esse assunto.",
  ui_story_5089_50890402_60_dialog_content = "Certamente, Sua Alteza! Agora, se puder, por favor estenda sua mão e podemos começar.",
  ui_story_5089_50890402_61_dialog_content = "Muito bem.",
  ui_story_5089_50890402_62_dialog_content = "<color=#e8d9bb>Barulho!</color>",
  ui_story_5089_50890402_63_dialog_content = "<color=#e8d9bb>Dois bastões de adivinhação caem nas mãos de Dantang. Mas antes que ela possa dar uma olhada mais de perto—</color>",
  ui_story_5089_50890402_64_dialog_content = "<color=#e8d9bb>Tianxian derrama o resto de seus bastões de adivinhação.</color>",
  ui_story_5089_50890402_65_dialog_content = "Qu-qual é o significado disso, Mestre Li?",
  ui_story_5089_50890402_66_dialog_content = "Ah, ouvir você dizer isso parece tão artificial. Por favor, me chame de Tianxian ou Lying Li, se preferir.",
  ui_story_5089_50890402_67_dialog_content = "Agora, minhas varas de adivinhação podem não parecer muito para você, mas eu confiei nelas para percorrer o mundo por muito tempo.",
  ui_story_5089_50890402_68_dialog_content = "Há aqueles que acreditam nos meus talentos. Com a fé deles, posso ajudá-los a evitar todo tipo de caos e calamidade.",
  ui_story_5089_50890402_69_dialog_content = "Também existem aqueles que não acreditam, aqueles que riem das minhas profecias e simplesmente seguem o seu dia.",
  ui_story_5089_50890402_70_dialog_content = "Mas para você pedir minha ajuda e duvidar dela na mesma respiração, para você buscar minha orientação e se recusar a segui-la de boa fé...",
  ui_story_5089_50890402_71_dialog_content = "Isso não é diferente de cuspir na minha arte.",
  ui_story_5089_50890402_72_dialog_content = "... Você não acha que pode estar exagerando um pouco?",
  ui_story_5089_50890402_73_dialog_content = "Dificilmente acho que sim.",
  ui_story_5089_50890402_74_dialog_content = "Se eu posso ser tão ousado para perguntar, Senhora Dantang, quando os dois primeiros bastões caíram em sua mão, você já estava esperando por um determinado resultado, não estava?",
  ui_story_5089_50890402_75_dialog_content = "...",
  ui_story_5089_50890402_76_dialog_content = "Posso ver que não estou enganado. A honrada Princesa Zhuohua não é de se resignar ao destino.",
  ui_story_5089_50890402_77_dialog_content = "E já que você já tomou sua decisão, não faz sentido continuar a brincadeira.",
  ui_story_5089_50890402_78_dialog_content = "No entanto, devo pedir que você me ajude a colocar meus bastões de adivinhação de volta em seu lugar. É uma cortesia profissional, entende?",
  ui_story_5089_50890402_79_dialog_content = "Mestre Li.",
  ui_story_5089_50890402_80_dialog_content = "Não há necessidade do honorífico. Eu não fui claro sobre isso agora mesmo?",
  ui_story_5089_50890402_81_dialog_content = "Ainda tenho mais um favor a pedir.",
  ui_story_5089_50890402_82_dialog_content = "... Minhas desculpas. Permita-me retratar minha declaração anterior.",
  ui_story_5089_50890402_83_dialog_content = "Venha, estenda sua mão mais uma vez. Vou garantir que sua sorte te diga para deixar esse assunto de lado.",
  ui_story_5089_50890402_84_dialog_content = "Isso não será necessário. Afinal, eu sou a Princesa Zhuohua.",
  ui_story_5089_50890402_85_dialog_content = "Minha descrença no destino é conhecida por todos.",
  ui_story_5089_50890402_86_dialog_content = "Ah, sim, suponho que acabei de dizer isso.",
  ui_story_5089_50890402_87_dialog_content = "Eu realmente deveria parar de fazer isso comigo mesma!",
  ui_story_5089_50890402_88_dialog_content = "*Suspiro* Muito bem, então... Afinal, ainda te devo um agradecimento por salvar minha vida.",
  ui_story_5089_50890402_89_dialog_content = "Vá em frente, nomeie seu favorito.",
  ui_story_5089_50890402_90_dialog_content = "Ei Dantang, encontrei um serviço de escolta armada como você pediu.",
  ui_story_5089_50890402_91_dialog_content = "Eles concordaram em devolver o ouro do príncipe herdeiro à capital do Reino Ji.",
  ui_story_5089_50890402_92_dialog_content = "Então, qual é o próximo passo para nós? Devemos ir também?",
  ui_story_5089_50890402_93_dialog_content = "Ainda não.",
  ui_story_5089_50890402_94_dialog_content = "O estalajadeiro acabou de trazer dois pacotes frescos de chá, e eles têm um sabor bastante excelente. Não faria mal passar mais alguns minutos apreciando nosso chá, não é?",
  ui_story_5089_50890402_95_dialog_content = "Acho que não, mas será que podemos mesmo relaxar assim?",
  ui_story_5089_50890402_96_dialog_content = "Não se preocupe, isso não vai demorar muito.",
  ui_story_5089_50890402_97_dialog_content = "Você está aí, Jiu?",
  ui_story_5089_50890402_98_dialog_content = "... Sim, Sua Alteza.",
  ui_story_5089_50890402_99_dialog_content = "Venha e tome uma xícara de chá conosco. Tenho algo para lhe dizer assim que terminarmos aqui.",
  ui_story_5089_50890402_100_dialog_content = "Como desejar.",
  ui_story_5089_50890402_101_dialog_content = "Este chá é realmente delicioso! Tem um sabor leve, mas refrescante e um aroma frutado que outros chás geralmente não têm.",
  ui_story_5089_50890402_102_dialog_content = "Ah, isso é porque eu adicionei um pouco de \"pó que gela o sangue\", que é feito de uma fruta levemente tóxica.",
  ui_story_5089_50890402_103_dialog_content = "... Ah?",
  ui_story_5089_50890402_104_dialog_content = "<color=#e8d9bb>Tum!</color>",
  ui_story_5089_50890402_105_dialog_content = "<color=#e8d9bb>De repente, Jiu cai de joelhos.</color>",
  ui_story_5089_50890402_106_dialog_content = "J-Jiu...!",
  ui_story_5089_50890402_107_dialog_content = "Não se preocupe, este tipo de droga apenas paralisa os membros sem prejudicar o corpo em si. Ele vai passar naturalmente depois de algum tempo.",
  ui_story_5089_50890402_108_dialog_content = "Curiosamente, seus efeitos são mais rápidos e potentes naqueles com grande força interior e proezas em artes marciais.",
  ui_story_5089_50890402_109_dialog_content = "Ah, isso explica por que ainda não sinto nada... Espere, esse não é o ponto!",
  ui_story_5089_50890402_110_dialog_content = "Por que você faria algo assim, Dantang?!",
  ui_story_5089_50890402_111_dialog_content = "Porque estamos sem tempo.",
  ui_story_5089_50890402_112_dialog_content = "Sua Alteza, Squawk e Jabber me informaram que já chegaram várias pessoas na pousada.",
  ui_story_5089_50890402_113_dialog_content = "E parece que nossos novos convidados não vêm em paz.",
  ui_story_5089_50890402_114_dialog_content = "Tianxian, você também não... Espere, quem diabos é você?!",
  ui_story_5089_50890402_115_dialog_content = "Claramente, eu sou a única e inigualável Senhorita Jiu. Seja em repouso ou na estrada, isso não muda.",
  ui_story_5089_50890402_116_dialog_content = "Este não é o momento para se reinventar, Tianxian!",
  ui_story_5089_50890402_117_dialog_content = "Também não é hora de fazer tal alarde desnecessário, você não concorda?",
  ui_story_5089_50890402_118_dialog_content = "Você realmente pode me culpar? Isso é completamente ridículo!",
  ui_story_5089_50890402_119_dialog_content = "Já é o suficiente, meu amigo. Agora me ajude a esconder a Senhorita Jiu naquele guarda-roupa ali, e rápido.",
  ui_story_5089_50890402_120_dialog_content = "Uh, claro... Nossa!",
  ui_story_5089_50890402_121_dialog_content = "Jiu, o que você...",
  ui_story_5089_50890402_122_dialog_content = "<color=#e8d9bb>O corpo de Jiu balança levemente enquanto ela resiste aos efeitos do remédio com todas as suas forças. O som de seus ossos chacoalhando por dentro quase pode ser ouvido.</color>",
  ui_story_5089_50890402_123_dialog_content = "<color=#e8d9bb>De repente, as feridas em suas mãos se abriram, encharcando suas roupas com sangue fresco.</color>",
  ui_story_5089_50890402_124_dialog_content = "<color=#e8d9bb>Ela move forçadamente seu corpo rígido apenas o suficiente para agarrar a barra da saia de Dantang.</color>",
  ui_story_5089_50890402_125_dialog_content = "...",
  ui_story_5089_50890402_126_dialog_content = "<color=#e8d9bb>Dantang recua, puxando sua saia da mão ensanguentada de Jiu.</color>",
  ui_story_5089_50890402_127_dialog_content = "Dia e noite pelos últimos cinco anos, você esteve ao meu lado. Sou eternamente grato por tudo que você fez por mim, Jiu.",
  ui_story_5089_50890402_128_dialog_content = "Você é uma boa pessoa, além de ser o servo mais leal que alguém poderia pedir.",
  ui_story_5089_50890402_129_dialog_content = "Mas não há como manter nossa paz por mais tempo.",
  ui_story_5089_50890402_130_dialog_content = "Sei que você não deseja me machucar, mas também nunca desobedeceria as ordens do meu tio.",
  ui_story_5089_50890402_131_dialog_content = "Como uma única pessoa, você não pode seguir dois caminhos opostos, ou servir como uma espada nas mãos de duas pessoas diferentes com objetivos opostos.",
  ui_story_5089_50890402_132_dialog_content = "Princesa... Dantang...",
  ui_story_5089_50890402_133_dialog_content = "Na verdade, não tenho o direito de lhe dar ordens até que você tome sua decisão.",
  ui_story_5089_50890402_134_dialog_content = "Saiba apenas que se você se recusar a fazê-lo, alguém como eu eventualmente intervirá e tirará esse direito de você.",
  ui_story_5089_50890402_135_dialog_content = "Ao renunciar à sua liberdade de escolha, você naturalmente se tornará um fantoche à mercê dos outros.",
  ui_story_5089_50890402_136_dialog_content = "Sua situação atual deve ser a prova disso.",
  ui_story_5089_50890402_137_dialog_content = "Jiu.",
  ui_story_5089_50890402_138_dialog_content = "A partir deste momento, você está agora dispensado do seu dever como guardião da Princesa Zhuohua.",
  ui_story_5089_50890402_139_dialog_content = "!",
  ui_story_5089_50890402_140_dialog_content = "Eu não quero nem preciso de você como você é agora.",
  ui_story_5089_50890402_141_dialog_content = "Recuso-me a viver sob a sua proteção ou, pior, a sua vigilância.",
  ui_story_5089_50890402_142_dialog_content = "O que eu quero é...",
  ui_story_5089_50890402_143_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5089_50890402_144_dialog_content = "<color=#e8d9bb>As últimas palavras de Dantang foram abafadas por um barulho alto do lado de fora.</color>",
  ui_story_5089_50890402_145_dialog_content = "Entre você!",
  ui_story_5089_50890402_146_dialog_content = "?",
  ui_story_5089_50890402_147_dialog_content = "<color=#e8d9bb>Eu também fui empurrado para dentro do guarda-roupa.</color>",
  ui_story_5089_50890402_148_dialog_content = "Perdoe-me por egoisticamente tomar as coisas em minhas próprias mãos, PlayerName.",
  ui_story_5089_50890402_149_dialog_content = "Estou deixando Jiu e tudo mais em suas mãos agora.",
  ui_story_5089_50890402_150_dialog_content = "Espere, Dantang!",
  ui_story_5089_50890402_151_dialog_content = "<color=#e8d9bb>As portas do guarda-roupa se fecham.</color>",
  ui_story_5089_50890402_152_dialog_content = "<color=#e8d9bb>No próximo momento, a porta do quarto é subitamente aberta.</color>",
  ui_story_5089_50890402_153_dialog_content = "Ah, finalmente. Conseguir uma audiência com você não tem sido muito fácil, Princesa Zhuohua.",
  ui_story_5089_50890402_154_dialog_content = "(Aquela voz!)",
  ui_story_5089_50890402_155_dialog_content = "Zhui Hu...",
  ui_story_5089_50890402_156_dialog_content = "Parece que a Ministra Armilla estava certa: você está muito bem e vivo.",
  ui_story_5089_50890402_157_dialog_content = "Mas é claro. Afinal, eu não poderia possivelmente morrer antes de criar a Besta Mecânica mais poderosa do mundo.",
  ui_story_5089_50890402_158_dialog_content = "Não tive a chance de perguntar antes, mas os rumores de sua afiliação com os Fate Riders eram claramente verdadeiros.",
  ui_story_5089_50890402_159_dialog_content = "Sim, mas isso não é perfeitamente normal? Qualquer um disposto a apoiar minha arte merece ser chamado de meu mestre.",
  ui_story_5089_50890402_160_dialog_content = "Ainda assim, não foi fácil obter a Chama Zhuyin mais uma vez. Estive ocupado desenvolvendo um novo sistema de poder para o mais recente Stinger.",
  ui_story_5089_50890402_161_dialog_content = "Mas esses homens insistiram em me arrastar até aqui para te encontrar.",
  ui_story_5089_50890402_162_dialog_content = "Eles prometeram me dar algo bom pelos meus problemas, no entanto.",
  ui_story_5089_50890402_163_dialog_content = "Eles disseram que se você ou sua guarda nos resistisse de qualquer maneira, eu poderia testar minha nova arma em você.",
  ui_story_5089_50890402_164_dialog_content = "Agora então, você se importaria em fazer um pouco de esforço? Até o menor já serviria, hehehe.",
  ui_story_5089_50890402_165_dialog_content = "Não vejo motivo para fazer isso.",
  ui_story_5089_50890402_166_dialog_content = "Eu sou a Princesa Zhuohua do Reino Ye, e além de você, o resto desses soldados são servos leais do meu tio.",
  ui_story_5089_50890402_167_dialog_content = "Assim sendo, eles nunca me machucariam de forma alguma. Eles simplesmente vieram para me dar as boas-vindas em casa, certo Jiu?",
  ui_story_5089_50890402_168_dialog_content = "*acena*",
  ui_story_5089_50890402_169_dialog_content = "Que pena, mas faça do seu jeito então. Ainda há muito a fazer na minha oficina, então vamos lá.",
  ui_story_5089_50890402_170_dialog_content = "... Espere. Havia mais duas pessoas viajando com a princesa.",
  ui_story_5089_50890402_171_dialog_content = "Sim, mas aquele charlatão de adivinhação fugiu no momento em que viu seus homens se aproximando.",
  ui_story_5089_50890402_172_dialog_content = "Quanto ao Celestita, ele é incapaz de realizar qualquer coisa por conta própria, especialmente em terra estrangeira. Por que você está tão preocupado com eles?",
  ui_story_5089_50890402_173_dialog_content = "As ordens do meu tio eram para me escoltar de volta à capital, e mais ninguém. Estou enganado?",
  ui_story_5089_50890402_174_dialog_content = "Não, Sua Alteza... Por aqui, por favor.",
  ui_story_5089_50890402_175_dialog_content = "<color=#e8d9bb>O quarto retorna ao silêncio.</color>",
  ui_story_5089_50890402_176_dialog_content = "<color=#e8d9bb>Mas desta vez, apenas Jiu e eu restamos.</color>",
  ui_story_5089_50890501_1_dialog_content = "... O que esses dois estavam pensando?!",
  ui_story_5089_50890501_2_dialog_content = "Ela estava apenas falando sobre lutar por mais tempo, e agora ela está caindo direto na armadilha deles!",
  ui_story_5089_50890501_3_dialog_content = "Como devemos nos manter seguros quando alguém como Zhui Hu está envolvido?!",
  ui_story_5089_50890501_4_dialog_content = "Nada disso faz sentido! Você também acha, não é, Jiu?",
  ui_story_5089_50890501_5_dialog_content = "Eu... eu não sei.",
  ui_story_5089_50890501_6_dialog_content = "Parece que a Princesa Dantang não confia mais em mim.",
  ui_story_5089_50890501_7_dialog_content = "Talvez ela estivesse certa. Talvez eu tenha falhado em meus deveres.",
  ui_story_5089_50890501_8_dialog_content = "Mas agora que não sou mais o guarda dela, não sei o que deve ser feito...",
  ui_story_5089_50890501_9_dialog_content = "Do que você está falando? Ainda há uma coisa que absolutamente precisa ser feita, lembra?",
  ui_story_5089_50890501_10_dialog_content = "O quê?",
  ui_story_5089_50890501_11_dialog_content = "Dantang disse que estamos sem tempo.",
  ui_story_5089_50890501_12_dialog_content = "Mas ela não estava com pressa quando estávamos no navio. Ela até disse que poderia entender sua hesitação.",
  ui_story_5089_50890501_13_dialog_content = "Mas depois da noite passada, algo aconteceu que fez ela mudar de atitude.",
  ui_story_5089_50890501_14_dialog_content = "Seja o que for, deve ter algo a ver com aquela boneca.",
  ui_story_5089_50890501_15_dialog_content = "Não só isso, mas ela disse que está deixando o resto comigo, mesmo que ela não tenha explicado nada...",
  ui_story_5089_50890501_16_dialog_content = "A minha suposição é que precisamos continuar procurando pistas que nos levarão a Xuan Ji. Uma vez que a encontrarmos, tenho certeza de que entenderemos as coisas muito melhor.",
  ui_story_5089_50890501_17_dialog_content = "Você pode discutir com Dantang o quanto quiser depois que fizermos isso, Jiu.",
  ui_story_5089_50890501_18_dialog_content = "Discutir... com Sua Alteza? E-Eu nunca faria algo tão presunçoso!",
  ui_story_5089_50890501_19_dialog_content = "Mas ela claramente não é mais sua mestre, certo?",
  ui_story_5089_50890501_20_dialog_content = "Mesmo assim...",
  ui_story_5089_50890501_21_dialog_content = "Independentemente da situação, ela tomou essa decisão sozinha sem consultar nenhum de nós.",
  ui_story_5089_50890501_22_dialog_content = "Para ser honesto, até eu estou um pouco chateado com ela.",
  ui_story_5089_50890501_23_dialog_content = "Não só ela me deixou em um lugar sobre o qual quase não sei nada...",
  ui_story_5089_50890501_24_dialog_content = "Ela também me colocou em uma situação em que eu tinha que ver meus amigos arriscarem suas vidas por mim.",
  ui_story_5089_50890501_25_dialog_content = "Então, uma vez que essa bagunça esteja toda resolvida, vamos lá dar um pedaço de nossas mentes para ela.",
  ui_story_5089_50890501_26_dialog_content = "Teremos uma boa e longa conversa com a princesa sobre como tratar adequadamente seus amigos.",
  ui_story_5089_50890501_27_dialog_content = "PlayerName...",
  ui_story_5089_50890501_28_dialog_content = "Mas antes de fazermos isso, você poderia por favor me emprestar seu apoio?",
  ui_story_5089_50890501_29_dialog_content = "Afinal, só há tanto que eu posso fazer sozinho.",
  ui_story_5089_50890501_30_dialog_content = "Fui criado sob o comando do Rei de Ye. Empunhar uma lâmina e seguir ordens é tudo o que eu sei.",
  ui_story_5089_50890501_31_dialog_content = "Mas se minhas habilidades podem ser bem utilizadas, PlayerName, então por favor me comande como achar melhor.",
  ui_story_5089_50890501_32_dialog_content = "Ah claro, mas vamos começar mudando um pouco essa mentalidade...",
  ui_story_5089_50890501_33_dialog_content = "Apenas lembre-se de que somos amigos e sempre nos ajudamos. Simples o suficiente, certo?",
  ui_story_5089_50890501_34_dialog_content = "... Eu nunca tive um amigo antes.",
  ui_story_5089_50890501_35_dialog_content = "Eu não deixaria Dantang ouvir você dizer isso, ou então ela ficará mais irritada do que nós!",
  ui_story_5089_50890501_36_dialog_content = "Sua Alteza Senhora Dantang nasceu de uma linhagem nobre e elevada! Como ela poderia ser amiga de alguém como eu?! Eu—",
  ui_story_5089_50890501_37_dialog_content = "Tudo bem, eu entendi. O remédio ainda não passou, então apenas me dê sua mão e vá com calma.",
  ui_story_5089_50890501_38_dialog_content = "Vamos, estamos indo para a capital juntos.",
  ui_story_5089_50890502_1_dialog_content = "Rugido—",
  ui_story_5089_50890502_2_dialog_content = "Os espíritos malignos foram purificados, PlayerName.",
  ui_story_5089_50890502_3_dialog_content = "Não estamos tão longe da cidade, estamos?",
  ui_story_5089_50890502_4_dialog_content = "Há muitas outras vilas por aqui também, e a capital real fica a menos de meia hora de distância.",
  ui_story_5089_50890502_6_dialog_content = "Bom...",
  ui_story_5089_50890502_8_dialog_content = "Espero que seja apenas uma coincidência. Não temos tempo para lidar com mais problemas agora... Vamos continuar em movimento.",
  ui_story_5089_50890502_9_dialog_content = "Entendi.",
  ui_story_5089_50890502_10_dialog_content = "Tem alguma coisa aí?",
  ui_story_5089_50890502_11_dialog_content = "?",
  ui_story_5089_50890502_12_dialog_content = "Desculpe, parece que seu olhar continua se desviando para lá.",
  ui_story_5089_50890502_13_dialog_content = "É a vila onde eu vivia quando era jovem.",
  ui_story_5089_50890502_14_dialog_content = "Sua cidade natal, hein? Você queria voltar e dar uma olhada?",
  ui_story_5089_50890502_15_dialog_content = "Não há necessidade. Perdi minha família há muito tempo e não sou muito familiarizado com os outros moradores da vila.",
  ui_story_5089_50890502_16_dialog_content = "Além disso, as duas casas restantes mal podem ser chamadas de lares.",
  ui_story_5089_50890502_17_dialog_content = "Temos assuntos mais importantes em mãos.",
  ui_story_5089_50890502_18_dialog_content = "Olhe ali, PlayerName. À sua frente está a capital do Reino Ye: Cidade de Jingliang.",
  ui_story_5089_50890502_19_dialog_content = "...",
  ui_story_5089_50890502_20_dialog_content = "(Pensei que depois de ver o ouro e o magatama do palácio do Reino de Ji, não me surpreenderia com mais nada em Longzhou.)",
  ui_story_5089_50890502_21_dialog_content = "(Mas na cidade de Jingliang, máquinas em forma de dragão expelem nuvens de névoa dos telhados, enquanto fênix de cobre entregam mensagens por toda a cidade.)",
  ui_story_5089_50890502_22_dialog_content = "<color=#e8d9bb>As ruas são largas e movimentadas enquanto fumaça e fogo irrompem de inúmeras oficinas.</color>",
  ui_story_5089_50890502_23_dialog_content = "<color=#e8d9bb>Em vez de ornamentos opulentos e beleza natural extravagante, a cidade de Jingliang é caracterizada por tons metálicos e a energia pulsante do artesanato engenhoso.</color>",
  ui_story_5089_50890502_24_dialog_content = "<color=#e8d9bb>*Rumble*</color>",
  ui_story_5089_50890502_25_dialog_content = "O-O que foi isso?!",
  ui_story_5089_50890502_26_dialog_content = "Apenas o som de um Transporte Huolong.",
  ui_story_5089_50890502_27_dialog_content = "PlayerName, você notou algo incomum nas ruas daqui?",
  ui_story_5089_50890502_28_dialog_content = "Você está falando sobre as duas faixas de metal embutidas no chão, certo? Eu tenho visto elas de vez em quando.",
  ui_story_5089_50890502_29_dialog_content = "Eles são realmente parecidos com algo que já vi antes...",
  ui_story_5089_50890502_30_dialog_content = "O Transporte Huolong foi projetado para o tribunal real muitos anos atrás por um grande inventor conhecido como Lord Houfeng.",
  ui_story_5089_50890502_31_dialog_content = "Ao combinar as Artes da Força da Água e do Fogo como sua fonte de energia, o Transporte Huolong é capaz de transportar grandes quantidades de carga sem perder sua mobilidade.",
  ui_story_5089_50890502_32_dialog_content = "Suas principais desvantagens são seu consumo excessivo de energia e sua limitação a pistas muito específicas.",
  ui_story_5089_50890502_33_dialog_content = "Dessa forma, a corte real é encarregada da maior parte do seu planejamento e infraestrutura, enquanto os proprietários de oficinas maiores apoiam sua construção através de financiamento.",
  ui_story_5089_50890502_34_dialog_content = "Em troca de ajuda com os trilhos do Transporte Huolong, os proprietários de oficinas também têm prioridade no transporte de mercadorias e materiais.",
  ui_story_5089_50890502_35_dialog_content = "Assim como eu pensei... É um trem a vapor, não é?!",
  ui_story_5089_50890502_36_dialog_content = "Um \"trem a vapor\"? O que é isso?",
  ui_story_5089_50890502_37_dialog_content = "Pense nisso como a versão própria de Astra do Porta-Huolong. Estou impressionado que o Senhor Houfeng foi capaz de inventar algo assim também!",
  ui_story_5089_50890502_38_dialog_content = "A princesa Dantang disse algo semelhante no passado.",
  ui_story_5089_50890502_39_dialog_content = "Ela acredita que com suas criações, seus talentos devem rivalizar com os da Senhora Xuan Ji.",
  ui_story_5089_50890502_40_dialog_content = "Em um momento, disseram que ele estava desenvolvendo algum tipo de pipa gigante que poderia transportar pessoas para terras distantes e trazê-las de volta.",
  ui_story_5089_50890502_41_dialog_content = "Infelizmente, devido a conflitos políticos dentro do reino, ele desapareceu sem deixar rastros e sua pesquisa foi finalmente interrompida.",
  ui_story_5089_50890502_42_dialog_content = "Que pena. Tenho certeza de que teria sido tão impressionante quanto seu Porta-Huolong, se não mais.",
  ui_story_5089_50890502_43_dialog_content = "Você parece saber muito sobre isso, Jiu. Eu não pensei que você estaria interessado nesse tipo de coisa?",
  ui_story_5089_50890502_44_dialog_content = "É só porque Sua Alteza me falou tanto sobre isso.",
  ui_story_5089_50890502_45_dialog_content = "Ela também lamentou ser muito jovem e ingênua na época, caso contrário, teria encontrado uma maneira de reter um inventor tão talentoso.",
  ui_story_5089_50890502_46_dialog_content = "Heh, isso definitivamente soa como Dantang.",
  ui_story_5089_50890502_47_dialog_content = "Tá bem, Jiu, vamos fazer o nosso melhor para encontrar uma maneira de fazer isso.",
  ui_story_5089_50890502_48_dialog_content = "Precisamos impedir que o Reino Ye perca um brilhante inventor como Xuan Ji e sua devota Princesa Zhuohua.",
  ui_story_5089_50890502_49_dialog_content = "Primeiro, devemos descobrir uma maneira de encontrá-los...",
  ui_story_5089_50890502_50_dialog_content = "Criminosos que a guarda pessoal do rei prende são normalmente detidos na Prisão do Céu na borda externa do palácio.",
  ui_story_5089_50890502_51_dialog_content = "Embora esteja protegida por uma legião de soldados, mesmo que eu caia, tenho certeza de que você conseguirá resgatar a Senhora Xuan Ji de seu cativeiro, PlayerName.",
  ui_story_5089_50890502_52_dialog_content = "P-Por que estamos começando com a estratégia mais agressiva?!",
  ui_story_5089_50890502_53_dialog_content = "PlayerName, quando você pediu minha ajuda, não queria que eu me tornasse sua espada?",
  ui_story_5089_50890502_54_dialog_content = "Não estou tentando me tornar um inimigo do tribunal, Jiu! E certamente não planejo te enviar para morrer!",
  ui_story_5089_50890502_55_dialog_content = "Deve haver outra maneira. Vamos apenas conferir essa Prisão do Céu primeiro.",
  ui_story_5089_50890502_56_dialog_content = "Se eles machucarem Xuan Ji de alguma forma... É quando usaremos nosso último recurso.",
  ui_story_5089_50890502_57_dialog_content = "Eu queria perguntar, Jiu. Muitas pessoas reconhecem você aqui na cidade de Jingliang?",
  ui_story_5089_50890502_58_dialog_content = "Talvez. Como guarda do rei, servi-o principalmente nas sombras e só interagi com meus companheiros guardas conforme necessário.",
  ui_story_5089_50890502_59_dialog_content = "Algumas pessoas podem me reconhecer pela minha máscara, mas não muito mais. Na verdade, elas podem nem mesmo saber se sou um cara ou uma mulher.",
  ui_story_5089_50890502_60_dialog_content = "Afinal, eles só se referem a mim como \"o demônio mascarado\" quando falam pelas minhas costas.",
  ui_story_5089_50890502_61_dialog_content = "Mas se você acha que vai ajudar, PlayerName...",
  ui_story_5089_50890502_62_dialog_content = "Suponho que isso vai ter que servir.",
  ui_story_5089_50890502_63_dialog_content = "Uh, certo... Por algum motivo, porém, sinto que você se destaca ainda mais agora.",
  ui_story_5089_50890502_64_dialog_content = "Como eu pensei, meu rosto realmente é uma visão insuportável... Vou encontrar algo para cobri-lo imediatamente.",
  ui_story_5089_50890502_65_dialog_content = "Th-Isso não foi o que eu quis dizer! De onde você tirou essa ideia?! A verdade é, você na verdade parece realmente... Uh...",
  ui_story_5089_50890502_66_dialog_content = "Realmente bonito!",
  ui_story_5089_50890502_67_dialog_content = "?",
  ui_story_5089_50890502_68_dialog_content = "Er, não importa. Não há tempo a perder, então vamos continuar a mover.",
  ui_story_5089_50890502_69_dialog_content = "Este lugar está sob a jurisdição do palácio real. Se você não tem negócios aqui, então saia imediatamente.",
  ui_story_5089_50890502_70_dialog_content = "Acho que o método direto é impossível, afinal.",
  ui_story_5089_50890502_71_dialog_content = "Então permita-me infiltrar nas instalações...",
  ui_story_5089_50890502_72_dialog_content = "V-Vamos apenas guardar isso para o final!",
  ui_story_5089_50890502_73_dialog_content = "Isso mesmo, eu ainda tenho o pássaro mecânico de Xuan Ji comigo. Talvez eu possa usá-lo para me comunicar com ela se conseguirmos distrair os soldados.",
  ui_story_5089_50890502_74_dialog_content = "Então permita-me distrair os soldados—",
  ui_story_5089_50890502_75_dialog_content = "Espere—Uh-oh!",
  ui_story_5089_50890502_76_dialog_content = "<color=#e8d9bb>Para surpresa deles, o pássaro mecânico de repente ganha vida e alça voo.</color>",
  ui_story_5089_50890502_77_dialog_content = "<color=#e8d9bb>Como se seguisse um programa predeterminado, ele vai direto para os portões do palácio em busca de Xuan Ji...</color>",
  ui_story_5089_50890502_78_dialog_content = "Estamos acabados... Hã?",
  ui_story_5089_50890502_79_dialog_content = "<color=#e8d9bb>Um raio de luz dourada brilha de uma origem desconhecida.</color>",
  ui_story_5089_50890502_80_dialog_content = "<color=#e8d9bb>Os dois soldados, aparentemente alheios a isso, permitem que o pássaro mecânico passe pelos portões.</color>",
  ui_story_5089_50890502_81_dialog_content = "... Ainda precisa que eu distraia os soldados?",
  ui_story_5089_50890502_82_dialog_content = "Bom...",
  ui_story_5089_50890502_83_dialog_content = "<color=#e8d9bb>De repente, um som suave pode ser ouvido além dos portões do palácio.</color>",
  ui_story_5089_50890502_84_dialog_content = "Perdoe-me, mas posso perguntar se um convidado distinto está esperando lá fora?",
  ui_story_5089_50890502_85_dialog_content = "Uh, quem é você?",
  ui_story_5089_50890502_86_dialog_content = "Apenas uma humilde donzela, senhor. Agora, por favor, siga-me.",
  ui_story_5089_50890502_87_dialog_content = "Senhora Xuan Ji está esperando por você.",
  ui_story_5089_50890502_88_dialog_content = "Bem-vindo, PlayerName. Não nos vimos desde a última primavera, não é?",
  ui_story_5089_50890502_89_dialog_content = "E você também, Jiu. Como você está ultimamente?",
  ui_story_5089_50890502_90_dialog_content = "É o verdadeiro Xuan Ji! Você está bem? Eles não te machucaram, não é?!",
  ui_story_5089_50890502_91_dialog_content = "Claro que não—Ugh, esses trilhos são tão chatos. Só um momento, por favor.",
  ui_story_5089_50890502_92_dialog_content = "... Ah?",
  ui_story_5089_50890502_93_dialog_content = "Venha, sente-se! Você ainda não almoçou, né? Se não, você chegou na hora certa!",
  ui_story_5089_50890502_94_dialog_content = "Fixit, Crafty, vão ver o que eles têm nas cozinhas do palácio hoje.",
  ui_story_5089_50890502_95_dialog_content = "Ganhei uma aposta contra Jie Gaoqing, e ele prometeu me trazer um peixe fresco hoje.",
  ui_story_5089_50890502_96_dialog_content = "Peça aos cozinheiros para cozinhar no vapor e servir com molho de feijão preto.",
  ui_story_5089_50890502_97_dialog_content = "Como desejar.",
  ui_story_5089_50890502_98_dialog_content = "Uh, Xuan Ji...? O que está acontecendo aqui?",
  ui_story_5089_50890502_99_dialog_content = "Ah, não se preocupe, a comida do palácio é perfeitamente deliciosa. É apenas difícil conseguir algo tão fresco por aqui, só isso.",
  ui_story_5089_50890502_100_dialog_content = "...",
  ui_story_5089_50890502_101_dialog_content = "De repente, sinto que nossa determinação para te libertar da prisão foi uma total piada.",
  ui_story_5089_50890502_102_dialog_content = "Você foi preso em primeiro lugar? Isso é mesmo uma prisão, afinal de contas?!",
  ui_story_5089_50890502_103_dialog_content = "Hahaha, claro que é! Não consegue ver como minha cabaça de vinho está vazia?",
  ui_story_5089_50890502_104_dialog_content = "Mas lembre-se, eu já fui um estimado membro da corte real. Ainda tenho muitos amigos por dentro, incluindo alguns colegas que se preocupam profundamente com minha segurança.",
  ui_story_5089_50890502_105_dialog_content = "Além disso, não importa o quanto o rei possa me ressentir, me punir sem me condenar formalmente primeiro não seria correto.",
  ui_story_5089_50890502_106_dialog_content = "Infelizmente, como ainda estou detido como um criminoso, eles não me fornecem nada mais forte do que chá simples. Espero que você não se importe!",
  ui_story_5089_50890502_107_dialog_content = "Senhorita Jiu, PlayerName.",
  ui_story_5089_50890502_108_dialog_content = "A jornada até aqui deve ter sido bastante difícil. Permita-me erguer esta xícara de chá em sua honra.",
  ui_story_5089_50890502_109_dialog_content = "Obrigado por sua gentil consideração.",
  ui_story_5089_50890502_110_dialog_content = "Nunca esperei que o maior tesouro da minha jornada para Astra não fosse a Chama Zhuyin, mas os amigos que fiz ao longo do caminho.",
  ui_story_5089_50890502_111_dialog_content = "Th-Não há necessidade de ser tão formal, Xuan Ji...",
  ui_story_5089_50890502_112_dialog_content = "Mas isso me lembra! Você por acaso sabe quem tem a Chama Zhuyin agora? Porque Dantang é—",
  ui_story_5089_50890502_113_dialog_content = "Shhh.",
  ui_story_5089_50890502_114_dialog_content = "Não esqueça, eu sou apenas um prisioneiro agora. Não adianta me contar sobre o mundo além da minha cela.",
  ui_story_5089_50890502_115_dialog_content = "E além disso, eu tenho tudo o que poderia querer bem aqui. É tão confortável que eu quase poderia esquecer dos problemas da minha vida.",
  ui_story_5089_50890502_116_dialog_content = "Por que eu me importaria com qualquer outra coisa?",
  ui_story_5089_50890502_117_dialog_content = "Mentiroso.",
  ui_story_5089_50890502_118_dialog_content = "Ah?",
  ui_story_5089_50890502_119_dialog_content = "Não há uma única peça de maquinaria aqui, há?",
  ui_story_5089_50890502_120_dialog_content = "Quem em sã consciência acreditaria que o famoso Xuan Ji acharia este lugar sequer remotamente confortável?",
  ui_story_5089_50890502_121_dialog_content = "Hahaha, tão direto como sempre, PlayerName.",
  ui_story_5089_50890502_122_dialog_content = "Então, por favor, ouça com atenção.",
  ui_story_5089_50890502_123_dialog_content = "O rei pessoalmente ordenou minha captura, e agora meu destino está inteiramente em suas mãos.",
  ui_story_5089_50890502_124_dialog_content = "Mesmo que eu conseguisse escapar contando com a superior habilidade marcial da Senhorita Jiu, meu nome ainda seria manchado e minhas palavras nunca seriam aceitas.",
  ui_story_5089_50890502_125_dialog_content = "Mas você deve saber algo sobre tudo isso, certo? O que devemos fazer agora?",
  ui_story_5089_50890502_126_dialog_content = "Agora não é a hora de considerar \"o que fazer.\"",
  ui_story_5089_50890502_127_dialog_content = "Embora não seja minha função comentar sobre assuntos externos, eu servi como estrategista por um tempo, então posso compartilhar algumas das minhas experiências com você.",
  ui_story_5089_50890502_128_dialog_content = "Por exemplo, se você deseja alcançar algo, mas não tem a força e a visão para isso, deve confiar na estratégia e nas táticas para avançar.",
  ui_story_5089_50890502_129_dialog_content = "A melhor escolha será sempre mover-se com propósito e ganhar ímpeto.",
  ui_story_5089_50890502_130_dialog_content = "Mova-se com o fluxo de suas circunstâncias, e os céus guiarão seu caminho.",
  ui_story_5089_50890502_131_dialog_content = "Mas lembre-se, você deve primeiro ampliar seus horizontes para discernir a direção da onda iminente.",
  ui_story_5089_50890502_132_dialog_content = "Só então você será capaz de ganhar ímpeto quando a oportunidade se apresentar.",
  ui_story_5089_50890502_133_dialog_content = "Assim como uma criatura mecânica, até a menor virada de uma engrenagem pode colocar todo o corpo em movimento.",
  ui_story_5089_50890502_134_dialog_content = "E até mesmo as ações mais simples requerem a coordenação de várias partes.",
  ui_story_5089_50890502_135_dialog_content = "Você nunca sabe qual pequeno componente pode falhar, causando o colapso de toda a máquina.",
  ui_story_5089_50890502_136_dialog_content = "Mas... Eu nem sei onde procurar.",
  ui_story_5089_50890502_137_dialog_content = "Então vamos começar dando uma olhada ao nosso redor, certo?",
  ui_story_5089_50890502_138_dialog_content = "Por exemplo, agora mesmo são apenas vocês dois diante de mim. Isso já não parece uma parte deliberada do plano de outra pessoa?",
  ui_story_5089_50890502_139_dialog_content = "!",
  ui_story_5089_50890502_140_dialog_content = "Além disso, conhecemos a Senhorita Jiu aqui há bastante tempo...",
  ui_story_5089_50890502_141_dialog_content = "Mas você realmente sabe de onde ela veio?",
  ui_story_5089_50890502_142_dialog_content = "Senhora Xuan Ji, os pratos estão prontos.",
  ui_story_5089_50890502_143_dialog_content = "Os guardas do rei apareceram de repente agora mesmo, alegando que desejam levá-lo para interrogatório.",
  ui_story_5089_50890502_144_dialog_content = "Crafty está impedindo-os enquanto falamos, mas temo que ela não consiga mantê-los afastados por muito mais tempo...",
  ui_story_5089_50890502_145_dialog_content = "Sim, eu sei.",
  ui_story_5089_50890502_146_dialog_content = "Um interrogatório bem na hora em que íamos almoçar. O timing deles não poderia ser pior!",
  ui_story_5089_50890502_147_dialog_content = "Graças a eles, PlayerName e a senhorita Jiu têm que perder nosso adorável peixe cozido no vapor.",
  ui_story_5089_50890502_148_dialog_content = "Ah, mas tal é a vida de um prisioneiro, eu suponho.",
  ui_story_5089_50890502_149_dialog_content = "... Por que você não vem simplesmente conosco, Xuan Ji?",
  ui_story_5089_50890502_150_dialog_content = "Vimos isso com nossos próprios olhos mais cedo. Os guardas do rei também estão em aliança com Zhui Hu, e eles—",
  ui_story_5089_50890502_151_dialog_content = "Fixit, por favor, mostre a saída aos nossos convidados.",
  ui_story_5089_50890502_152_dialog_content = "Xuan Ji!",
  ui_story_5089_50890502_153_dialog_content = "Chega, agora vá embora. Cada um de nós temos nossos próprios assuntos para lidar, não é?",
  ui_story_5089_50890502_154_dialog_content = "Tenho total confiança em você, PlayerName.",
  ui_story_5089_50890502_155_dialog_content = "Você definitivamente encontrará seu ritmo em breve.",
  ui_story_5089_50890601_1_dialog_content = "<color=#e8d9bb>Fixit nos deixa após nos escoltar para fora da cidade em uma carruagem.</color>",
  ui_story_5089_50890601_2_dialog_content = "Parece que somos só nós dois novamente, Jiu.",
  ui_story_5089_50890601_3_dialog_content = "Xuan Ji disse tanto, mas o que significava tudo isso...?",
  ui_story_5089_50890601_4_dialog_content = "<color=#e8d9bb>Rosnar-</color>",
  ui_story_5089_50890601_5_dialog_content = "...",
  ui_story_5089_50890601_6_dialog_content = "Agora que penso nisso, nós não comemos nada hoje.",
  ui_story_5089_50890601_7_dialog_content = "Vou perguntar se algum dos moradores da vila estaria disposto a nos alimentar em troca de pagamento.",
  ui_story_5089_50890601_8_dialog_content = "Por favor, espere aqui, PlayerName.",
  ui_story_5089_50890601_9_dialog_content = "OK... Hã?",
  ui_story_5089_50890601_10_dialog_content = "Realmente tem uma vila por aqui?",
  ui_story_5089_50890601_11_dialog_content = "O arroz tem sido vendido a preços mais altos ultimamente, o que é improvável por estas bandas, então vendi todo o meu arroz para alguns comerciantes de passagem do Reino Ji.",
  ui_story_5089_50890601_12_dialog_content = "Infelizmente, só tenho um pouco de mingau feito com o arroz integral envelhecido da nossa família. Não é muito, mas espero que seja do seu agrado...",
  ui_story_5089_50890601_13_dialog_content = "Não nos importamos nem um pouco! Não comemos o dia todo, então a comida é uma bênção.",
  ui_story_5089_50890601_14_dialog_content = "Desculpe-me, mas há algum motivo para você não estar comendo? Gostaria de algo mais para acompanhar seu mingau?",
  ui_story_5089_50890601_15_dialog_content = "Não, obrigado. Não preciso de comida agora.",
  ui_story_5089_50890601_16_dialog_content = "Agora, agora, isso não vai funcionar! Seu corpo não será capaz de acompanhar sem uma refeição decente, você sabe?",
  ui_story_5089_50890601_17_dialog_content = "Como eu disse, não preciso de sustento agora. Já fiquei sem comida por dias durante a missão, o que nunca afetou minha esgrima.",
  ui_story_5089_50890601_18_dialog_content = "Além disso, eu preferiria não assustar ninguém com a minha aparência.",
  ui_story_5089_50890601_19_dialog_content = "Sobre isso...",
  ui_story_5089_50890601_20_dialog_content = "Sua máscara e maneira de falar são um pouco familiares... Espere! Jiu-mei... É você?",
  ui_story_5089_50890601_21_dialog_content = "\"Jiu-mei\"?",
  ui_story_5089_50890601_22_dialog_content = "... Sim.",
  ui_story_5089_50890601_23_dialog_content = "Já faz algum tempo, Tio Li.",
  ui_story_5089_50890601_24_dialog_content = "Céus! Não acredito que você ainda está vivo!",
  ui_story_5089_50890601_25_dialog_content = "Depois que seus pais morreram tragicamente naquele ano, até as autoridades estavam convencidas de que você morreu junto com eles!",
  ui_story_5089_50890601_26_dialog_content = "Você era apenas uma criança naquela época! Nossa, como você cresceu, Jiu-mei!",
  ui_story_5089_50890601_27_dialog_content = "Como você tem estado todos esses anos, minha garota...?",
  ui_story_5089_50890601_28_dialog_content = "Estive bem, Tio Li. Um homem gentil me acolheu e me deu uma boa vida.",
  ui_story_5089_50890601_29_dialog_content = "Bom, bom! Ouvir isso faz meu coração se encher de alegria!",
  ui_story_5089_50890601_30_dialog_content = "Venha, sente-se e tome um pouco de mingau! Espere aqui enquanto o Tio Li busca alguns legumes em conserva para você!",
  ui_story_5089_50890601_31_dialog_content = "Este deve ser sua cidade natal, certo, Jiu?",
  ui_story_5089_50890601_32_dialog_content = "De certa forma, sim.",
  ui_story_5089_50890601_33_dialog_content = "Minha família originalmente vivia em uma vila ainda mais remota. Nós nos mudamos para cá para evitar um desastre.",
  ui_story_5089_50890601_34_dialog_content = "Um desastre?",
  ui_story_5089_50890601_35_dialog_content = "Sim. Eu nem tinha dez anos naquela época, então não me lembro de muitos detalhes.",
  ui_story_5089_50890601_36_dialog_content = "Acredito que um certo nobre gostou do meu rosto e quis me comprar para me manter como servo.",
  ui_story_5089_50890601_37_dialog_content = "Mas quando meus pais recusaram, ele e seus homens começaram a nos assediar a cada momento. Eventualmente, fugimos para este lugar.",
  ui_story_5089_50890601_38_dialog_content = "Depois disso, meus pais me obrigaram a usar uma máscara e me fizeram dizer a todos que eu parecia um demônio, indigna de ser vista pelos outros.",
  ui_story_5089_50890601_39_dialog_content = "Isso é inacreditável...",
  ui_story_5089_50890601_40_dialog_content = "Não me importava em usá-lo. Afinal, meu rosto causava sofrimento à minha família, e eu nunca fui de conversar com os outros.",
  ui_story_5089_50890601_41_dialog_content = "Se houver algo, meus pais sentiram mais remorso do que eu.",
  ui_story_5089_50890601_42_dialog_content = "Sempre que as outras crianças da vila me chamavam de aberração, minha mãe me segurava e cantava para mim.",
  ui_story_5089_50890601_43_dialog_content = "E meu pai me dava os doces melões que ele não conseguia suportar comer ele mesmo.",
  ui_story_5089_50890601_44_dialog_content = "Então aquela canção de ninar que você cantou mais cedo... Foi feita apenas para você, não foi? Seus pais devem ter realmente te amado.",
  ui_story_5089_50890601_45_dialog_content = "Posso perguntar o que aconteceu com eles?",
  ui_story_5089_50890601_46_dialog_content = "Há uma montanha logo a oeste desta aldeia. Você notou isso mais cedo, não notou PlayerName?",
  ui_story_5089_50890601_47_dialog_content = "Ah... Qual de novo?",
  ui_story_5089_50890601_48_dialog_content = "Venha. Vamos conversar lá fora.",
  ui_story_5089_50890601_49_dialog_content = "Jiu-mei... Você e seu amigo já estão de partida tão cedo?",
  ui_story_5089_50890601_50_dialog_content = "Sim, Tio Li. Gostaríamos de visitar a mina ali.",
  ui_story_5089_50890601_51_dialog_content = "Muito bem, mas você deve saber que a mina se esgotou há apenas alguns anos, e todos os trabalhadores também já partiram.",
  ui_story_5089_50890601_52_dialog_content = "Uma grande oficina foi construída naquele terreno posteriormente, mas nada de Nota parece ter sido produzido lá.",
  ui_story_5089_50890601_53_dialog_content = "Um dos homens mais jovens da nossa aldeia foi lá em busca de trabalho, mas não havia uma única alma lá. Pelo que entendemos, o lugar está abandonado há algum tempo.",
  ui_story_5089_50890601_54_dialog_content = "Mais uma coisa, Jiu-mei...",
  ui_story_5089_50890601_55_dialog_content = "Sim?",
  ui_story_5089_50890601_56_dialog_content = "N-Não é nada muito importante... É só que todos nós temos lutado nos últimos anos.",
  ui_story_5089_50890601_57_dialog_content = "Mas você teve sorte o suficiente para encontrar uma boa vida, então por favor... Viva bem e seja feliz.",
  ui_story_5089_50890601_58_dialog_content = "Se seus pais pudessem te ver agora, tenho certeza de que eles também estariam muito felizes com você.",
  ui_story_5089_50890601_59_dialog_content = "... Entendido.",
  ui_story_5089_50890601_60_dialog_content = "É essa a montanha que você mencionou antes, Jiu?",
  ui_story_5089_50890601_61_dialog_content = "Sim. Antes de nosso rei ascender ao trono, todas essas terras, incluindo a minha, eram seu domínio.",
  ui_story_5089_50890601_62_dialog_content = "Ele montou um campo de trabalho aos pés da montanha, onde colocaria refugiados e prisioneiros para trabalhar.",
  ui_story_5089_50890601_63_dialog_content = "Um dia, dois dos retentores do rei estavam escoltando um condenado à morte para o campo de trabalho, mas eles ficaram preguiçosos e decidiram se hospedar em nossa casa próxima.",
  ui_story_5089_50890601_64_dialog_content = "Meus pais foram forçados a servi-los o dia todo e trocar nossos preciosos suprimentos de grãos pelo vinho deles. Eles até tiveram que entregar comida para aquele prisioneiro.",
  ui_story_5089_50890601_65_dialog_content = "Em sua embriaguez, eles insistiram em ver meu verdadeiro rosto. Eles removeram à força minha máscara e ameaçaram me prejudicar.",
  ui_story_5089_50890601_66_dialog_content = "Foi quando um transeunte misterioso derrubou a pesada cerca atrás dos meus atacantes, prendendo e matando-os no processo.",
  ui_story_5089_50890601_67_dialog_content = "Ele se manteve escondido nas sombras o tempo todo, provavelmente para evitar ser implicado em suas mortes. Mas eu não tive tempo para pensar nele ou em suas ações.",
  ui_story_5089_50890601_68_dialog_content = "Tudo o que eu sabia era que tinha causado problemas aos meus pais novamente, então voltei para procurá-los...",
  ui_story_5089_50890601_69_dialog_content = "Mas quando eu voltei, tudo que encontrei foram seus corpos deitados numa poça de sangue.",
  ui_story_5089_50890601_70_dialog_content = "Ao lado deles estava uma tigela de mingau quente derramada. O prisioneiro há muito tempo havia se libertado de suas correntes e escapado.",
  ui_story_5089_50890601_71_dialog_content = "Às vezes, me pergunto se há alguma verdade no ditado, \"O destino faz tolos de todos nós.\"",
  ui_story_5089_50890601_72_dialog_content = "Nunca tive medo. Mesmo quando outros me chamavam de aberração ou demônio, ou me submetiam a insultos e ferimentos, nunca senti medo deles.",
  ui_story_5089_50890601_73_dialog_content = "Mas naquele dia, quando vi os corpos sem vida dos meus pais... Foi o dia em que realmente senti medo.",
  ui_story_5089_50890601_74_dialog_content = "Mas apenas naquela vez, minha mãe não pôde estar lá para me cantar sua canção.",
  ui_story_5089_50890601_75_dialog_content = "Me perdoe, falei demais. De agora em diante, eu vou—",
  ui_story_5089_50890601_76_dialog_content = "Jiu!",
  ui_story_5089_50890601_77_dialog_content = "?",
  ui_story_5089_50890601_78_dialog_content = "Você não precisa me contar nada disso, especialmente se não quiser.",
  ui_story_5089_50890601_79_dialog_content = "Não tem nada a ver com eu querer ou não te contar.",
  ui_story_5089_50890601_80_dialog_content = "Ainda não entendo o significado das palavras da Senhora Xuan Ji, mas sei que cada palavra que ela diz carrega sua própria importância.",
  ui_story_5089_50890601_81_dialog_content = "E já que ela mencionou minhas origens, achei que seria adequado compartilhá-las com você.",
  ui_story_5089_50890601_82_dialog_content = "Os detalhes da minha vida são triviais no melhor dos casos, mas agradeço a todos por ouvirem eles, PlayerName.",
  ui_story_5089_50890601_83_dialog_content = "... Como você poderia possivelmente dizer isso sobre si mesmo, Jiu?",
  ui_story_5089_50890601_84_dialog_content = "Se você realmente não se importasse...",
  ui_story_5089_50890601_85_dialog_content = "Você não teria lembrado de algo tão pequeno como aquela tigela de mingau derramado no chão!",
  ui_story_5089_50890601_86_dialog_content = "Você está com raiva, PlayerName?",
  ui_story_5089_50890601_87_dialog_content = "Estou surpreso que você conseguiu perceber!",
  ui_story_5089_50890601_88_dialog_content = "Sim, claro que estou com raiva!",
  ui_story_5089_50890601_89_dialog_content = "Perdoe-me... Eu sei que não é a história mais agradável de se ouvir.",
  ui_story_5089_50890601_90_dialog_content = "Mas se isso serve de consolo... Minha vingança veio logo depois.",
  ui_story_5089_50890601_91_dialog_content = "Depois de encontrar meus pais daquele jeito, peguei a adaga de um dos oficiais mortos e cacei o prisioneiro por um dia e uma noite.",
  ui_story_5089_50890601_92_dialog_content = "Para minha surpresa, ele viajou direto para o campo de trabalho da mina e tentou assassinar nosso senhor, o cara que mais tarde se tornaria o Rei de Ye.",
  ui_story_5089_50890601_93_dialog_content = "Até o momento em que o alcancei, a justiça já havia sido servida.",
  ui_story_5089_50890601_94_dialog_content = "Sua Alteza perguntou os motivos da minha presença. Depois de saber sobre a queda da minha família, ele me acolheu e me concedeu o nome Jiu.",
  ui_story_5089_50890601_95_dialog_content = "Não só ele me vingou, mas também me permitiu morar em sua mansão. Lá, ele me ensinou a ler e escrever, e me fortaleceu através do treinamento de artes marciais.",
  ui_story_5089_50890601_96_dialog_content = "Por essa razão, devo a ele minha vida e farei de tudo para retribuir sua gentileza.",
  ui_story_5089_50890601_97_dialog_content = "Além desta dívida de gratidão, não tenho outra razão para empunhar minha espada... Ou para continuar vivendo, nesse caso.",
  ui_story_5089_50890601_98_dialog_content = "Não é sobre isso que estou falando, Jiu.",
  ui_story_5089_50890601_99_dialog_content = "Tudo o que você faz é falar sobre vingança e gratidão.",
  ui_story_5089_50890601_100_dialog_content = "Mas e os seus próprios sentimentos? E as coisas que você quer fazer?",
  ui_story_5089_50890601_101_dialog_content = "Seja levando um golpe por mim antes, sugerindo casualmente invadir a prisão, ou pensando que seus sentimentos não importam... É sempre a mesma coisa com você.",
  ui_story_5089_50890601_102_dialog_content = "Por que você continua desconsiderando seus sacrifícios, como se eles não importassem?!",
  ui_story_5089_50890601_103_dialog_content = "Você pode ser forte, mas ainda é feito de carne e osso. Você pode se machucar, sentir dor, ficar triste e, se não for cuidadoso, pode realmente morrer.",
  ui_story_5089_50890601_104_dialog_content = "Não é que eu não reconheça isso. É só que, pelo bem das minhas missões...",
  ui_story_5089_50890601_105_dialog_content = "Tudo bem, entendi. Acho que estou começando a entender como falar com você.",
  ui_story_5089_50890601_106_dialog_content = "E agora que eu pessoalmente experimentei o quão teimoso você pode ser, sinto que também devo um pedido de desculpas a Dantang.",
  ui_story_5089_50890601_107_dialog_content = "Deixe-me colocar isso de uma maneira que você possa entender.",
  ui_story_5089_50890601_108_dialog_content = "?",
  ui_story_5089_50890601_109_dialog_content = "Francamente, sua imprudência e disposição para se sacrificar sempre me assustam.",
  ui_story_5089_50890601_110_dialog_content = "Os Celestitas são uma raça gentil e pacífica. Nós não queremos ver derramamento de sangue, e especialmente não queremos ver nossos amigos se machucarem.",
  ui_story_5089_50890601_111_dialog_content = "Quero te levar de volta para Dantang, são e salvo.",
  ui_story_5089_50890601_112_dialog_content = "Então, se ordens são as únicas coisas que você vai ouvir, então eu tenho uma ordem apenas para você.",
  ui_story_5089_50890601_113_dialog_content = "\"Não importa a sua situação, sempre valorize sua vida e proteja-se em primeiro lugar.\"",
  ui_story_5089_50890601_114_dialog_content = "Eu...",
  ui_story_5089_50890601_115_dialog_content = "Eu também não estou procurando por desculpas. Um simples sim será suficiente.",
  ui_story_5089_50890601_116_dialog_content = "Sim. Vou lembrar das suas ordens.",
  ui_story_5089_50890601_117_dialog_content = "Mas há um limite de tempo para esses pedidos?",
  ui_story_5089_50890601_118_dialog_content = "Você realmente não entende, não é?",
  ui_story_5089_50890601_119_dialog_content = "Não importa. Se você realmente precisa de um limite de tempo, então...",
  ui_story_5089_50890601_120_dialog_content = "Suas ordens não terminarão até o dia em que você possa balançar sua lâmina sem fazê-lo por gratidão ou vingança. Que tal isso?",
  ui_story_5089_50890601_121_dialog_content = "Hum...",
  ui_story_5089_50890601_122_dialog_content = "Não vou mudar nenhuma parte das suas ordens, se é isso que você está prestes a perguntar.",
  ui_story_5089_50890601_123_dialog_content = "Não, é só que meu mestre já me disse a mesma coisa uma vez.",
  ui_story_5089_50890601_124_dialog_content = "Seu \"mestre\"?",
  ui_story_5089_50890601_125_dialog_content = "O maior espadachim do mundo e o homem que me ensinou o caminho da lâmina.",
  ui_story_5089_50890601_126_dialog_content = "Embora ele tenha se recusado a aceitar alguém tão teimoso quanto eu como um discípulo formal, ele ainda me ensinou muitas coisas.",
  ui_story_5089_50890601_127_dialog_content = "Mas havia uma coisa que ele não me ensinaria: a Lâmina Trovejante, uma técnica rumorejada de ter o poder de dividir montanhas e mares.",
  ui_story_5089_50890601_128_dialog_content = "Ele afirmou que não era uma técnica de espada real, e por isso não podia me ensinar.",
  ui_story_5089_50890601_129_dialog_content = "Apenas quando eu puder empunhar minha espada sem ser por vingança ou gratidão, serei digno de aprendê-la.",
  ui_story_5089_50890601_130_dialog_content = "Isso é estranho. Não vejo nenhuma outra pista por aqui—Urk!",
  ui_story_5089_50890601_131_dialog_content = "Perdoe-me, PlayerName, mas não estamos sozinhos.",
  ui_story_5089_50890601_132_dialog_content = "Mmf... É esse Zhui Hu?!",
  ui_story_5089_50890601_133_dialog_content = "O que ela poderia estar fazendo aqui...? Vamos Jiu, vamos segui-la!",
  ui_story_5089_50890601_134_dialog_content = "Ela entrou naquela oficina, certo? Vamos—",
  ui_story_5089_50890601_135_dialog_content = "Ranger—",
  ui_story_5089_50890601_136_dialog_content = "Cuidado, Jiu! Existem bestas mecânicas guardando a oficina!",
  ui_story_5089_50890602_1_dialog_content = "Por que uma oficina abandonada precisaria de tanta proteção?",
  ui_story_5089_50890602_2_dialog_content = "Há muitos sinais de atividade recente. Não só isso, mas Zhui Hu também apareceu por aqui.",
  ui_story_5089_50890602_3_dialog_content = "Se eu tivesse que adivinhar, provavelmente é uma fortaleza do Cavaleiro do Destino.",
  ui_story_5089_50890602_4_dialog_content = "Então, precisaremos ser extremamente cuidadosos. Além de seu interior enorme e labiríntico, parte da oficina também está localizada profundamente no subsolo.",
  ui_story_5089_50890602_5_dialog_content = "Uma vez lá dentro, não podemos nos dar ao luxo de perder o caminho.",
  ui_story_5089_50890602_6_dialog_content = "Então temos sorte porque tenho muita experiência com prédios assim. As habilidades psíquicas podem ser bastante úteis para analisar o caminho à frente.",
  ui_story_5089_50890602_7_dialog_content = "Varredura Psíquica—",
  ui_story_5089_50890602_8_dialog_content = "Uau! Há tantas armas armazenadas aqui!",
  ui_story_5089_50890602_9_dialog_content = "O que os Cavaleiros do Destino planejam fazer com eles? Hein?",
  ui_story_5089_50890602_10_dialog_content = "Parece que alguém está trancado naquela sala ali.",
  ui_story_5089_50890602_11_dialog_content = "!",
  ui_story_5089_50890602_12_dialog_content = "<color=#e8d9bb>No momento em que eles entram na sala, um cheiro desagradável ataca seus sentidos.</color>",
  ui_story_5089_50890602_13_dialog_content = "<color=#e8d9bb>Uma figura encolhida treme no canto da sala, se afastando desesperadamente deles.</color>",
  ui_story_5089_50890602_14_dialog_content = "Apenas olhe para este lugar. Eles devem tê-lo mantido aqui por muito tempo agora.",
  ui_story_5089_50890602_15_dialog_content = "Quem é você? O que você está fazendo aqui?",
  ui_story_5089_50890602_16_dialog_content = "Ahh—Ahh—",
  ui_story_5089_50890602_17_dialog_content = "Urgh... Haha... Uuuu—",
  ui_story_5089_50890602_18_dialog_content = "Parece que o pobre coitado já está muito longe. Não vamos conseguir mais nada dele.",
  ui_story_5089_50890602_19_dialog_content = "Vamos continuar investigando a oficina. Talvez encontraremos uma maneira de salvá-lo...",
  ui_story_5089_50890602_20_dialog_content = "Jiu? Por que você ainda está parado aí?",
  ui_story_5089_50890602_21_dialog_content = "Não... Isso não pode ser... Por que você...",
  ui_story_5089_50890602_22_dialog_content = "Por que você está aqui, meu rei?!",
  ui_story_5089_50890602_23_dialog_content = "Espere... Esse é o Rei de Ye?!",
  ui_story_5089_50890700_1_dialog_content = "<color=#e8d9bb>No dia seguinte</color>",
  ui_story_5089_50890700_2_dialog_content = "... Princesa?",
  ui_story_5089_50890700_3_dialog_content = "Hmm? Sim?",
  ui_story_5089_50890700_4_dialog_content = "Você me pediu para perguntar sobre essas duas princesas, não foi? Fang Ze e Shao Qin?",
  ui_story_5089_50890700_5_dialog_content = "Ah, sim. Me diga, o que você descobriu sobre minhas irmãs?",
  ui_story_5089_50890700_6_dialog_content = "Parece que o rei os enviou para venerar os ancestrais reais há algum tempo. Como tal, eles ficarão em uma das vilas imperiais em vez de retornar à cidade de Jingliang.",
  ui_story_5089_50890700_7_dialog_content = "Eu deveria saber...",
  ui_story_5089_50890700_8_dialog_content = "Você ficou parado aqui o tempo todo? Você mal tocou no seu café da manhã... Deixar todos esses pratos deliciosos esfriarem é um desperdício.",
  ui_story_5089_50890700_9_dialog_content = "Perdoe-me, mas não tenho muito apetite.",
  ui_story_5089_50890700_10_dialog_content = "Não importa quão grandes sejam nossas preocupações, negligenciar nossos corpos não resolverá nada. Você não concorda?",
  ui_story_5089_50890700_11_dialog_content = "E além disso, se preocupar não vai ajudar agora que estamos presos no palácio. Tudo o que podemos fazer é depositar nossas esperanças em PlayerName e na Senhorita Jiu.",
  ui_story_5089_50890700_12_dialog_content = "Sua donzela nos disse que nossos amigos estão bem, certo?",
  ui_story_5089_50890700_13_dialog_content = "Ou você está dizendo que não acredita neles?",
  ui_story_5089_50890700_14_dialog_content = "Claro que acredito neles. Você, por outro lado...",
  ui_story_5089_50890700_15_dialog_content = "Eu esperava que você fugisse na primeira oportunidade, e ainda assim, aqui está você.",
  ui_story_5089_50890700_16_dialog_content = "Vamos lá, por que eu escolheria partir? O palácio me oferece muita comida e um lugar quente para dormir. Se for o caso, esses são alguns dos melhores dias da minha vida!",
  ui_story_5089_50890700_17_dialog_content = "Não suportava a ideia de me separar de uma vida tão maravilhosa, então realizei uma adivinhação para ver quanto tempo mais eu poderia ficar aqui. Consegue adivinhar o que eu vi, Alteza?",
  ui_story_5089_50890700_18_dialog_content = "Minha adivinhação revelou que você ainda precisa de mim aqui.",
  ui_story_5089_50890700_19_dialog_content = "Pedir para você se passar por Jiu já é pedir demais. Como eu poderia impor a você algo ainda maior?",
  ui_story_5089_50890700_20_dialog_content = "Assim que este assunto for resolvido, ainda tenho que lhe oferecer uma recompensa adequada—",
  ui_story_5089_50890700_21_dialog_content = "<color=#e8d9bb>Bum!!—</color>",
  ui_story_5089_50890700_22_dialog_content = "O-O que foi isso?!",
  ui_story_5089_50890700_23_dialog_content = "Sua Alteza! Um intruso forçou a entrada no palácio! Por favor, apresse-se para o—Nngh!",
  ui_story_5089_50890700_24_dialog_content = "Por que você deixou aquele pobre homem inconsciente, Tianxian?",
  ui_story_5089_50890700_25_dialog_content = "Para mostrar a você que eu ainda tenho muito a oferecer, claro!",
  ui_story_5089_50890700_26_dialog_content = "Ah— Ahhh—",
  ui_story_5089_50890700_27_dialog_content = "*bocejo* Ah, já é de manhã?",
  ui_story_5089_50890700_28_dialog_content = "Eu estava com muito medo para dormir ontem à noite...",
  ui_story_5089_50890700_29_dialog_content = "Ahh—",
  ui_story_5089_50890700_30_dialog_content = "*suspiro* Já corremos um grande risco ao levá-lo a vários médicos diferentes no meio da noite.",
  ui_story_5089_50890700_31_dialog_content = "Mas todos disseram a mesma coisa: que sua condição foi causada por envenenamento e que o veneno já se infiltrou em seus ossos. Segundo eles, você está além da salvação agora.",
  ui_story_5089_50890700_32_dialog_content = "Awu, uau...",
  ui_story_5089_50890700_33_dialog_content = "Você é realmente o Rei de Ye em pessoa? Se sim...",
  ui_story_5089_50890700_34_dialog_content = "\"Resistência\" nem começa a descrever a situação em que estamos agora.",
  ui_story_5089_50890700_35_dialog_content = "Não apenas isso, mas algo que Jiu disse ontem me deu um mau pressentimento.",
  ui_story_5089_50890700_36_dialog_content = "Então essa clínica também não pode fazer nada por ele, huh?",
  ui_story_5089_50890700_37_dialog_content = "Não desista ainda, Jiu. Talvez possamos conseguir que um desses médicos escreva uma carta para Liqing?",
  ui_story_5089_50890700_38_dialog_content = "Até poderíamos tentar encontrar aquele cara \"Bucunzi\" que Dantang mencionou antes—",
  ui_story_5089_50890700_39_dialog_content = "PlayerName.",
  ui_story_5089_50890700_40_dialog_content = "Se a pessoa no trono não for o verdadeiro Rei de Ye, então o que acontecerá com Sua Alteza?",
  ui_story_5089_50890700_41_dialog_content = "Bom...",
  ui_story_5089_50890700_42_dialog_content = "Estou profundamente endividado não apenas com o rei, mas também com ela. Em nosso tempo juntos, Sua Alteza não me mostrou nada além de bondade.",
  ui_story_5089_50890700_43_dialog_content = "Agora que a princesa me aliviou de meus deveres como seu guarda-costas, eu posso não ter o direito de me intrometer em seus assuntos.",
  ui_story_5089_50890700_44_dialog_content = "Mas se eu não puder mais protegê-la...",
  ui_story_5089_50890700_45_dialog_content = "Então estou confiando a segurança de Sua Alteza a você.",
  ui_story_5089_50890700_46_dialog_content = "Desculpe.",
  ui_story_5089_50890700_47_dialog_content = "Espere um minuto... Cadê ela, afinal?!",
  ui_story_5089_50890700_48_dialog_content = "Grrr... Eu sabia!",
  ui_story_5089_50890700_49_dialog_content = "Ainda bem que planejei algo assim acontecer...",
  ui_story_5089_50890700_50_dialog_content = "Tio Li! Me desculpe, mas poderia pedir para você cuidar deste homem?",
  ui_story_5089_50890700_51_dialog_content = "Eh? Claro, meu jovem amigo, mas para onde você está indo com tanta pressa?",
  ui_story_5089_50890700_52_dialog_content = "Para a cidade de Jingliang!",
  ui_story_5089_50890700_53_dialog_content = "Ahh—",
  ui_story_5089_50890700_54_dialog_content = "Meu senhor, um assassino invadiu os portões do palácio e nossos guardas não são páreo para ela. Ela está se aproximando do salão principal neste exato momento!",
  ui_story_5089_50890700_55_dialog_content = "Deve ser a Lâmina Gelada, Sua Alteza.",
  ui_story_5089_50890700_56_dialog_content = "Devemos interceptá-la?",
  ui_story_5089_50890700_57_dialog_content = "Sem necessidade. Se ela busca uma audiência com o rei, então eu a aguardarei bem aqui.",
  ui_story_5089_50890700_58_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5089_50890700_59_dialog_content = "Pare! Você está diante do poderoso Rei de Ye, agora não avance mais!",
  ui_story_5089_50890700_60_dialog_content = "Fique de lado.",
  ui_story_5089_50890700_61_dialog_content = "Eurgh—",
  ui_story_5089_50890700_62_dialog_content = "<color=#e8d9bb>Jiu entra no salão principal e trava olhares com o homem no trono.</color>",
  ui_story_5089_50890700_63_dialog_content = "Parece que sua reputação como a lâmina mais afiada do rei é bem merecida.",
  ui_story_5089_50890700_64_dialog_content = "Nenhum guerreiro em todo o palácio poderia sequer esperar rivalizar com você.",
  ui_story_5089_50890700_65_dialog_content = "Mentirosa!",
  ui_story_5089_50890700_66_dialog_content = "Eu já me encontrei com o verdadeiro rei, seu impostor—",
  ui_story_5089_50890700_67_dialog_content = "Agora retire-se do trono dele!",
  ui_story_5089_50890700_68_dialog_content = "Ah, então você já viu aquele tolo confuso por si mesmo.",
  ui_story_5089_50890700_69_dialog_content = "<color=#e8d9bb>Clam—</color>",
  ui_story_5089_50890700_70_dialog_content = "<color=#e8d9bb>As espadas deles se chocam, preenchendo o salão com sua poderosa reverberação.</color>",
  ui_story_5089_50890700_71_dialog_content = "Como ousa insultar o rei tão friamente!",
  ui_story_5089_50890700_72_dialog_content = "Heh, admiro sua ferocidade.",
  ui_story_5089_50890700_73_dialog_content = "Você realmente é o espadachim mais poderoso sob o meu comando.",
  ui_story_5089_50890700_74_dialog_content = "Você...!",
  ui_story_5089_50890700_75_dialog_content = "Guardas! Cumprimentem seu superior com um amigável teste de força!",
  ui_story_5089_50890700_76_dialog_content = "Sim, Sua Alteza!",
  ui_story_5089_50890700_77_dialog_content = "<color=#e8d9bb>Os guardas sombrios do rei se aproximam de ambos os lados, seus fios de metal afiados cortando o ar.</color>",
  ui_story_5089_50890700_78_dialog_content = "<color=#e8d9bb>Justo quando Jiu está prestes a desviar, ela percebe uma falha na defesa do falso rei e ataca.</color>",
  ui_story_5089_50890700_79_dialog_content = "—!",
  ui_story_5089_50890700_80_dialog_content = "<color=#e8d9bb>Um fio de metal perfura sua perna inferior, mas seu ataque não vacila nem por um momento. Ela empurra sua lâmina diretamente no coração do falso rei com toda a sua força!</color>",
  ui_story_5089_50890700_81_dialog_content = "Desde que você era criança, sempre teve esse terrível hábito.",
  ui_story_5089_50890700_82_dialog_content = "<color=#e8d9bb>Clam—</color>",
  ui_story_5089_50890700_83_dialog_content = "<color=#e8d9bb>A ponta de sua lâmina pressiona a leve armadura do rei e recua levemente.</color>",
  ui_story_5089_50890700_84_dialog_content = "Maldito seja você...",
  ui_story_5089_50890700_85_dialog_content = "<color=#e8d9bb>Jiu se recupera imediatamente e se prepara para atacar mais uma vez.</color>",
  ui_story_5089_50890700_86_dialog_content = "Sua lâmina é afiada, mas aprimorar uma borda ao seu limite vem ao custo da durabilidade da lâmina.",
  ui_story_5089_50890700_87_dialog_content = "Você esqueceu a razão pela qual eu te dei o nome \"Jiu\"?",
  ui_story_5089_50890700_88_dialog_content = "!",
  ui_story_5089_50890700_89_dialog_content = "<color=#e8d9bb>—Dez anos atrás</color>",
  ui_story_5089_50890700_90_dialog_content = "Então você perseguiu o assassino de sua família aqui, descalço e sozinho, sem comer ou beber nada por um dia inteiro?",
  ui_story_5089_50890700_91_dialog_content = "Hahaha, eu nunca esperava que alguém tão jovem fosse tão determinado.",
  ui_story_5089_50890700_92_dialog_content = "Mas olhe só para você agora: faminto, coberto de bolhas e mal consegue ficar de pé.",
  ui_story_5089_50890700_93_dialog_content = "Mesmo que você alcance seu inimigo nessa condição, a única vitória que você pode esperar é uma em que ambos morrem.",
  ui_story_5089_50890700_94_dialog_content = "... Mas isso não te incomodou, não é? Afinal, o que mais você poderia fazer com sua vida além de sacrificá-la em nome da vingança?",
  ui_story_5089_50890700_95_dialog_content = "Mas agora que executei sua vingança, é apenas justo que sua vida me pertença agora.",
  ui_story_5089_50890700_96_dialog_content = "\"Jiu-mei,\" era isso? Um nome que significa \"a nona filha\" dificilmente vale a pena manter.",
  ui_story_5089_50890700_97_dialog_content = "A partir deste dia, você será conhecido simplesmente como \"Jiu\".",
  ui_story_5089_50890700_98_dialog_content = "Um nome que se refere a uma pedra preciosa do mais puro preto. É tão bonita quanto uma magatama, mas muito mais forte.",
  ui_story_5089_50890700_99_dialog_content = "Sob meu comando, você vai afiar sua lâmina e se tornar minha arma mais afiada, contanto que não se permita se tornar frágil.",
  ui_story_5089_50890700_100_dialog_content = "<color=#e8d9bb>Jiu perde o foco momentaneamente e é imediatamente preso ao chão por uma rede de incontáveis fios de metal.</color>",
  ui_story_5089_50890700_101_dialog_content = "<color=#e8d9bb>Sua máscara cai no chão, mas ela continua a olhar ameaçadoramente para o falso rei.</color>",
  ui_story_5089_50890700_102_dialog_content = "Quem... Quem é você?",
  ui_story_5089_50890700_103_dialog_content = "Não disseram que alguém infiltrou o palácio? Por que ainda há tantos guardas vigiando este lugar?",
  ui_story_5089_50890700_104_dialog_content = "Quando você disse para fugir agora há pouco, eu pensei que era porque você tinha algum tipo de plano brilhante.",
  ui_story_5089_50890700_105_dialog_content = "Improvisar é um plano de ação perfeitamente aceitável, dadas as nossas circunstâncias.",
  ui_story_5089_50890700_106_dialog_content = "Entendo que você deposita muito pouca fé na minha adivinhação, mas eu acredito nela de todo coração.",
  ui_story_5089_50890700_107_dialog_content = "A sinistra fortuna que PlayerName tirou anteriormente combina perfeitamente com nossa situação atual.",
  ui_story_5089_50890700_108_dialog_content = "No entanto, se meus cálculos estiverem corretos, não podemos confiar inteiramente em PlayerName e Senhorita Jiu para resolver este predicamento.",
  ui_story_5089_50890700_109_dialog_content = "O que você quer dizer?",
  ui_story_5089_50890700_110_dialog_content = "É simples: enquanto eu distraio os soldados, você aproveitará a oportunidade para escapar do palácio.",
  ui_story_5089_50890700_111_dialog_content = "Quanto ao que vem a seguir, vamos ter que improvisar!",
  ui_story_5089_50890700_112_dialog_content = "Espere, Tianxian!",
  ui_story_5089_50890700_113_dialog_content = "Quem vai lá?!",
  ui_story_5089_50890700_114_dialog_content = "Depois deles!",
  ui_story_5089_50890700_115_dialog_content = "Eu nunca entenderei aquele cara.",
  ui_story_5089_50890700_116_dialog_content = "Mas parece que não tenho escolha agora—",
  ui_story_5089_50890700_117_dialog_content = "Para onde você está indo, Sua Alteza?",
  ui_story_5089_50890700_118_dialog_content = "...",
  ui_story_5089_50890700_119_dialog_content = "Xuan Ji, os soldados—",
  ui_story_5089_50890700_120_dialog_content = "Acalme-se, estou ocupado aqui.",
  ui_story_5089_50890700_121_dialog_content = "Mas não há mais tempo! Por que você ainda está mexendo nessas peças?",
  ui_story_5089_50890700_122_dialog_content = "Esses não são azulejos comuns! São dispositivos engenhosos que venho meticulosamente criando há vários dias.",
  ui_story_5089_50890700_123_dialog_content = "Você se tornou muito mais sábio, mas ainda tem muito a aprender quando se trata de astúcia e engano.",
  ui_story_5089_50890700_124_dialog_content = "O que você quer dizer com isso?",
  ui_story_5089_50890700_125_dialog_content = "O que quero dizer é que isso pode parecer uma cela de prisão comum para você.",
  ui_story_5089_50890700_126_dialog_content = "Mas nas mãos de um verdadeiro artesão, qualquer coisa pode ser modificada em um dispositivo ou mecanismo: bancos, mesas, vigas do telhado e até mesmo o chão sob seus pés.",
  ui_story_5089_50890700_127_dialog_content = "Agora, deleite seus olhos com a minha mais recente invenção, que foi inspirada pelo nosso Celestita favorito e feita usando itens domésticos simples: a Telha Defletora de Lúmina!",
  ui_story_5089_50890700_128_dialog_content = "... Você está brincando, certo? Então, o que exatamente ele faz?",
  ui_story_5089_50890700_129_dialog_content = "Este excelente equipamento é capaz de redirecionar qualquer luz ou Lumina recebida para um local desejado.",
  ui_story_5089_50890700_130_dialog_content = "E como exatamente isso deve nos ajudar?",
  ui_story_5089_50890700_131_dialog_content = "Descobriremos em breve!",
  ui_story_5089_50890700_132_dialog_content = "Dez anos atrás, um alto funcionário, exausto pelas lutas pelo poder dentro da corte real, caiu em desgraça e tornou-se um prisioneiro. Ele foi condenado a trabalhos forçados nas minas até a sua morte.",
  ui_story_5089_50890700_133_dialog_content = "O destino, no entanto, tinha outros planos para ele. Os oficiais que o escoltavam para o campo de trabalho eram indolentes e, em vez de terminar a viagem, decidiram se hospedar na casa de uma família próxima.",
  ui_story_5089_50890700_134_dialog_content = "Eles não eram nada mais do que cidadãos comuns, o que facilitou para ele emboscá-los e fazer sua fuga.",
  ui_story_5089_50890700_135_dialog_content = "Mas enquanto ele fugia do pátio, encontrou seus captores tentando se aproveitar da jovem filha da família.",
  ui_story_5089_50890700_136_dialog_content = "E assim ele os matou sem pensar duas vezes, e continuou em sua rota original para o campo de trabalho.",
  ui_story_5089_50890700_137_dialog_content = "O príncipe que estava encarregado do campo de trabalho na época era um bom homem, mas mesmo assim um pateta desajeitado. Com apenas uma única dose de um certo medicamento, sua mente foi completamente perdida.",
  ui_story_5089_50890700_138_dialog_content = "E assim, após vestir um leve disfarce, o prisioneiro trocou de lugar com o príncipe.",
  ui_story_5089_50890700_139_dialog_content = "Os homens em sua presença eram tão desprovidos de lealdade, que nunca perceberam que outro cara havia silenciosamente substituído seu mestre.",
  ui_story_5089_50890700_140_dialog_content = "Coincidentemente, foi neste momento que a jovem filha chegou, buscando vingança por sua família caída.",
  ui_story_5089_50890700_141_dialog_content = "Foi então que o prisioneiro percebeu que sua fuga pesada resultou em suas mortes.",
  ui_story_5089_50890700_142_dialog_content = "E assim ele acolheu a garota, e a forjou em uma lâmina leal e fiel.",
  ui_story_5089_50890700_143_dialog_content = "E-Era você o tempo todo—!",
  ui_story_5089_50890700_144_dialog_content = "<color=#e8d9bb>Os olhos de Jiu ficam vermelhos enquanto ela se esforça para levantar o corpo. A rede de arame que a prende emite um gemido agudo, como se estivesse prestes a quebrar.</color>",
  ui_story_5089_50890700_145_dialog_content = "Chegou a hora de eu revelar a verdade.",
  ui_story_5089_50890700_146_dialog_content = "Agora me diga, você ainda pretende vingar a morte de sua família?",
  ui_story_5089_50890700_147_dialog_content = "Ou você vai expressar gratidão a mim por ter te acolhido e criado todos esses anos?",
  ui_story_5089_50890700_148_dialog_content = "Eu...",
  ui_story_5089_50890700_149_dialog_content = "<color=#e8d9bb>Pela primeira vez, a lâmina de Jiu treme em sua mão.</color>",
  ui_story_5089_50890700_150_dialog_content = "Pelo que você tem vivido todo esse tempo, Jiu? Qual é o seu propósito?",
  ui_story_5089_50890700_151_dialog_content = "Hraaagh—!",
  ui_story_5089_50890700_152_dialog_content = "<color=#e8d9bb>Um raio de luz passa rapidamente.</color>",
  ui_story_5089_50890700_153_dialog_content = "<color=#e8d9bb>Os fios de metal estalam e voam em todas as direções. Entre os destroços caindo, Jiu desencadeia seu ataque final.</color>",
  ui_story_5089_50890700_154_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5089_50890700_155_dialog_content = "<color=#e8d9bb>Ela balança sua lâmina carregada de Lumina, e a onda de choque resultante divide o palácio em dois, deixando trincheiras profundas no chão de pedra.</color>",
  ui_story_5089_50890700_156_dialog_content = "<color=#e8d9bb>O Rei de Ye, no entanto, desvia facilmente do ataque e emerge ileso.</color>",
  ui_story_5089_50890700_157_dialog_content = "Você realmente está tão duvidoso que não consegue nem segurar sua espada firme?",
  ui_story_5089_50890700_158_dialog_content = "<color=#e8d9bb>Wham—</color>",
  ui_story_5089_50890700_159_dialog_content = "<color=#e8d9bb>O rei golpeia a espada de Jiu para fora de sua mão e para um canto da sala.</color>",
  ui_story_5089_50890700_160_dialog_content = "<color=#e8d9bb>Momentos atrás.</color>",
  ui_story_5089_50890700_161_dialog_content = "Alteza, se insistir em partir, não teremos outra escolha senão detê-lo à força.",
  ui_story_5089_50890700_162_dialog_content = "Nunca pensei que veria o dia em que teria que lutar contra meus guardas do palácio no Reino de Ye.",
  ui_story_5089_50890700_163_dialog_content = "Infelizmente para você, recuar não é mais uma opção para mim.",
  ui_story_5089_50890700_164_dialog_content = "Ainda tenho alguém me esperando lá fora.",
  ui_story_5089_50890700_165_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5089_50890700_166_dialog_content = "<color=#e8d9bb>De repente, o salão principal próximo é rasgado por um poderoso surto de Lumina.</color>",
  ui_story_5089_50890700_167_dialog_content = "<color=#e8d9bb>Imediatamente depois, um flash de luz preenche o quarto enquanto a onda de Lumina se dirige diretamente para eles!</color>",
  ui_story_5089_50890700_168_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5089_50890700_169_dialog_content = "<color=#e8d9bb>A torre do palácio está dividida ao meio, criando um abismo entre os guardas reais e Dantang.</color>",
  ui_story_5089_50890700_170_dialog_content = "<color=#e8d9bb>Outro súbito flash de luz ilumina o caminho para fora do palácio.</color>",
  ui_story_5089_50890700_171_dialog_content = "Aquela direção... Ministra Armilla?",
  ui_story_5089_50890700_172_dialog_content = "Tive a sensação de que ela nunca ficaria ociosa em sua cela de prisão.",
  ui_story_5089_50890700_173_dialog_content = "Então você acha que eu deveria fugir do palácio também?",
  ui_story_5089_50890700_174_dialog_content = "Sua Alteza.",
  ui_story_5089_50890700_175_dialog_content = "O que foi?",
  ui_story_5089_50890700_176_dialog_content = "Perdoe-nos, mas a Princesa escapou do palácio.",
  ui_story_5089_50890700_177_dialog_content = "O status da pessoa que entrou no palácio com a princesa também é desconhecido, assim como seu paradeiro.",
  ui_story_5089_50890700_178_dialog_content = "Nossos guardas afirmam tê-lo visto mergulhando em um arbusto, mas quando foram investigar, tudo o que encontraram foi uma estatueta de açúcar.",
  ui_story_5089_50890700_179_dialog_content = "Ah, uma coisinha...",
  ui_story_5089_50890700_180_dialog_content = "O que mais? Fala logo.",
  ui_story_5089_50890700_181_dialog_content = "Parece que \"eles\" estão planejando fazer sua jogada em breve.",
  ui_story_5089_50890700_182_dialog_content = "Eles insistem que entreguemos as armas nos próximos três dias.",
  ui_story_5089_50890700_183_dialog_content = "No entanto, a oficina alega não ter capacidade para preencher seu enorme pedido em tão pouco tempo. O Reino de Ji também está nos pressionando para concluir sua transação anterior...",
  ui_story_5089_50890700_184_dialog_content = "Entendi.",
  ui_story_5089_50890700_185_dialog_content = "Discutiremos isso mais tarde.",
  ui_story_5089_50890700_186_dialog_content = "Por enquanto, contenha seu ex-líder até que ela recupere a compostura.",
  ui_story_5089_50890700_187_dialog_content = "Sim, Sua Alteza.",
  ui_story_5089_50890700_188_dialog_content = "<color=#e8d9bb>Pimba!</color>",
  ui_story_5089_50890700_189_dialog_content = "<color=#e8d9bb>O guarda sombra joga Jiu em uma sala vazia e sai.</color>",
  ui_story_5089_50890700_190_dialog_content = "Bem, se não é a Senhorita Jiu!",
  ui_story_5089_50890700_191_dialog_content = "Você veio me fazer companhia?",
  ui_story_5089_50890700_192_dialog_content = "...",
  ui_story_5089_50890802_1_dialog_content = "Alerte todos os guardas na cidade! A princesa foi sequestrada!",
  ui_story_5089_50890802_2_dialog_content = "Procure em cada canto da cidade! Denuncie qualquer personagem suspeito imediatamente!",
  ui_story_5089_50890802_3_dialog_content = "Entendido!",
  ui_story_5089_50890802_4_dialog_content = "Tantos guardas... Parece que a atmosfera inteira da cidade de Jingliang mudou de repente.",
  ui_story_5089_50890802_5_dialog_content = "E algo me diz que eu sou um dos \"personagens suspeitos\" que eles estão procurando.",
  ui_story_5089_50890802_6_dialog_content = "Quem está aí? Mostre-se!",
  ui_story_5089_50890802_7_dialog_content = "Uh-oh—Urk! S-Solte-me...!",
  ui_story_5089_50890802_8_dialog_content = "Shh, sou só eu.",
  ui_story_5089_50890802_9_dialog_content = "Dantang?!",
  ui_story_5089_50890802_10_dialog_content = "Sim, agora me siga.",
  ui_story_5089_50890802_11_dialog_content = "Que lugar é esse?",
  ui_story_5089_50890802_12_dialog_content = "É uma sala segura preparada pelos escoltas armados que contratamos para devolver o ouro do príncipe herdeiro.",
  ui_story_5089_50890802_13_dialog_content = "Como eles frequentemente trabalham com o submundo do crime, naturalmente têm uma necessidade de espaços como este.",
  ui_story_5089_50890802_14_dialog_content = "E já que fizemos um pedido tão caro, é normal que eles nos fornecessem algumas comodidades adicionais.",
  ui_story_5089_50890802_15_dialog_content = "Você estava planejando isso tão à frente o tempo todo?!",
  ui_story_5089_50890802_16_dialog_content = "Então havia uma razão para nos deixar para trás na pousada!",
  ui_story_5089_50890802_17_dialog_content = "Naquela época, eu não tinha certeza absoluta da verdade. Tudo o que eu tinha eram as dicas vagas da Ministra Armilla para me guiar.",
  ui_story_5089_50890802_18_dialog_content = "Embora as chances fossem pequenas, a mera possibilidade de jogo sujo representava uma grande ameaça para todo o Reino Ye.",
  ui_story_5089_50890802_19_dialog_content = "Não só isso... Mas o preço do ganho é muito alto.",
  ui_story_5089_50890802_20_dialog_content = "O Tio Li também nos informou que os comerciantes do Reino Ji têm comprado alimentos apesar dos altos preços recentemente.",
  ui_story_5089_50890802_21_dialog_content = "... O tumulto no início da primavera também se deveu em parte à relutância do Reino Ye em entregar canhões à costa.",
  ui_story_5089_50890802_22_dialog_content = "O Reino de Ji nunca suportaria essas perdas sem obter algo em troca.",
  ui_story_5089_50890802_23_dialog_content = "Você está dizendo... que o Reino Ji está deliberadamente aumentando o preço dos grãos?",
  ui_story_5089_50890802_24_dialog_content = "O cidadão comum é o mais prejudicado quando os preços são aumentados dessa maneira. Quando isso acontece, eles são mais propensos a sair e procurar outras maneiras de sobreviver.",
  ui_story_5089_50890802_25_dialog_content = "Nos últimos anos, o Reino de Ye estabeleceu inúmeras oficinas de vários tamanhos. Ao fazer isso, atraíram muitos dos jovens e saudáveis cidadãos do reino, forçando-os a abandonar seus campos na esperança de um trabalho melhor remunerado.",
  ui_story_5089_50890802_26_dialog_content = "Nossos estoques de grãos já eram insuficientes para lidar com uma mudança populacional desta magnitude.",
  ui_story_5089_50890802_27_dialog_content = "O aumento do custo dos grãos também aumentou os custos para outros setores. Em resumo, a economia do reino está presa em um ciclo vicioso.",
  ui_story_5089_50890802_28_dialog_content = "O Reino Ji, no entanto, não está de todo sem fundos. Se decidirem nos desafiar para uma guerra de atrito, receio que não temos chance de vencer.",
  ui_story_5089_50890802_29_dialog_content = "No entanto, não estou convencido de que o Reino de Ji deseja romper completamente os laços. Se alguma coisa, eles provavelmente desejam capitalizar em nossa fraqueza para continuar nos explorando.",
  ui_story_5089_50890802_30_dialog_content = "... O timing deles não poderia ser pior.",
  ui_story_5089_50890802_31_dialog_content = "O tempo deles?",
  ui_story_5089_50890802_32_dialog_content = "Diga-me, PlayerName: o que exatamente você considera ser uma \"nação\"?",
  ui_story_5089_50890802_33_dialog_content = "Hã? Bem... Eu diria que é um grupo de pessoas que se unem em busca de uma vida melhor.",
  ui_story_5089_50890802_34_dialog_content = "Além de promover seus interesses, eles também trabalham duro para todos os outros no grupo.",
  ui_story_5089_50890802_35_dialog_content = "É assim que o povo de Eraveil define uma nação? Devo dizer, parece uma existência bastante utópica.",
  ui_story_5089_50890802_36_dialog_content = "E-Estou errado?",
  ui_story_5089_50890802_37_dialog_content = "De jeito nenhum, PlayerName.",
  ui_story_5089_50890802_38_dialog_content = "Embora cada reino vassalo em Longzhou esteja sob o domínio do Império Zhao, cada um tem sua própria visão sobre o que significa ser uma nação.",
  ui_story_5089_50890802_39_dialog_content = "Por exemplo, o Reino de Ji acredita que governar um país não é diferente de administrar um negócio. O Reino de Ye, por outro lado, vê as coisas de maneira diferente.",
  ui_story_5089_50890802_40_dialog_content = "Em nossos olhos, uma nação é um mecanismo massivo e sem forma. Dia e noite, opera sem descanso.",
  ui_story_5089_50890802_41_dialog_content = "Você é o pivô, eu sou a engrenagem, o artesão é o óleo, e as massas são sua força motriz.",
  ui_story_5089_50890802_42_dialog_content = "Contanto que cada peça da máquina cumpra seu papel diligentemente e normalmente, nossa nação prosperará naturalmente.",
  ui_story_5089_50890802_43_dialog_content = "Então, e agora?",
  ui_story_5089_50890802_44_dialog_content = "Nosso rei é um impostor, interesses conflitantes marcam seu tribunal, os artesãos não são livres e as massas estão à beira de um sofrimento ainda maior. Este é o estado atual da nossa nação.",
  ui_story_5089_50890802_45_dialog_content = "Em vez de tentar resolver cada um desses problemas individualmente, decidi ir direto ao cerne do conflito.",
  ui_story_5089_50890802_46_dialog_content = "E assim, eu voluntariamente retornei ao palácio, na esperança de encontrar uma falha no cerne do sofrimento de nossa nação.",
  ui_story_5089_50890802_47_dialog_content = "Fazer isso também permitiu que você e Jiu continuassem procurando por evidências sem serem perseguidos pelos soldados do rei.",
  ui_story_5089_50890802_48_dialog_content = "Falando francamente, eu sabia que Jiu nunca concordaria com isso, o que me deixou sem escolha a não ser recorrer à decepção. Por favor, não me culpe, PlayerName.",
  ui_story_5089_50890802_49_dialog_content = "Não te culpo por isso, Dantang. Depois do nosso tempo juntos, aprendi o quão teimosa ela também pode ser.",
  ui_story_5089_50890802_50_dialog_content = "É por isso que eu tive que fazer algo semelhante com ela...",
  ui_story_5089_50890802_51_dialog_content = "Desculpe a interrupção, jovens mestres, mas a sua remessa chegou em segurança. May Posso incomodá-los para uma assinatura?",
  ui_story_5089_50890802_52_dialog_content = "Sim, claro. Muito obrigado pela sua ajuda.",
  ui_story_5089_50890802_53_dialog_content = "Além disso, Sua Alteza, progredimos na questão desde a nossa última conversa.",
  ui_story_5089_50890802_54_dialog_content = "Os meus homens fora da cidade me informaram que realmente existem Carregadores Huolong se movendo nessa direção, e que eles parecem estar transportando uma grande quantidade de mercadorias.",
  ui_story_5089_50890802_55_dialog_content = "Entendido. Obrigado por toda a sua ajuda.",
  ui_story_5089_50890802_56_dialog_content = "Apenas fazendo o nosso trabalho. Adeus.",
  ui_story_5089_50890802_57_dialog_content = "Ele estava falando sobre a oficina secreta?",
  ui_story_5089_50890802_58_dialog_content = "De fato. Durante o meu tempo no palácio, consegui reunir uma quantidade considerável de informações.",
  ui_story_5089_50890802_59_dialog_content = "O falso rei tem explorado os recursos do Reino Ye para fabricar armas para os Fate Riders.",
  ui_story_5089_50890802_60_dialog_content = "O Reino de Ji também tem atrasado a entrega de seus canhões costeiros. Minha suspeita é que eles também estão conspirando com os Cavaleiros do Destino, que desejam reivindicar esses canhões para si mesmos.",
  ui_story_5089_50890802_61_dialog_content = "E recentemente eles aumentaram novamente a demanda por armas de fogo.",
  ui_story_5089_50890802_62_dialog_content = "Eles insistiram no assunto várias vezes agora e até ameaçaram o falso rei se ele não cumprir.",
  ui_story_5089_50890802_63_dialog_content = "Quando você mencionou a existência de uma oficina escondida, eu imediatamente enviei esses homens para investigar.",
  ui_story_5089_50890802_64_dialog_content = "No entanto, eu não esperava que eles agissem tão rápido...",
  ui_story_5089_50890802_65_dialog_content = "Não podemos apenas ficar aqui e deixar os Cavaleiros do Destino colocar as mãos em todas essas armas!",
  ui_story_5089_50890802_66_dialog_content = "Concordo plenamente com você.",
  ui_story_5089_50890802_67_dialog_content = "Mas, dada a nossa situação atual, é bastante difícil para nós tomar qualquer ação.",
  ui_story_5089_50890802_68_dialog_content = "Mesmo com a sua ajuda, descobrir a verdade não foi de maneira alguma simples. Se ao menos eu pudesse ter me preparado antes...",
  ui_story_5089_50890802_69_dialog_content = "Isso não parece ou soa como você de forma alguma, Dantang.",
  ui_story_5089_50890802_70_dialog_content = "PlayerName?",
  ui_story_5089_50890802_71_dialog_content = "A Dantang que eu conheço, nunca duvidaria de si mesma ao desafiar uma situação como essa, especialmente se o destino supostamente tivesse uma mão nisso.",
  ui_story_5089_50890802_72_dialog_content = "O Dantang que eu conheço é corajoso, a ponto de ser quase assustador.",
  ui_story_5089_50890802_73_dialog_content = "... Você me lisonjeia, meu amigo. Mas infelizmente, nosso dilema não pode ser resolvido apenas pela bravura.",
  ui_story_5089_50890802_74_dialog_content = "Mas se conseguirmos trazer chips suficientes para a mesa de negociação...",
  ui_story_5089_50890802_75_dialog_content = "Isso não deve ser um problema.",
  ui_story_5089_50890802_76_dialog_content = "O quê?",
  ui_story_5089_50890802_77_dialog_content = "Se você está preocupado com as moedas de troca, temos de sobra.",
  ui_story_5089_50890802_78_dialog_content = "Por exemplo... Temos ouro suficiente em nossas mãos para comprar uma cidade inteira.",
  ui_story_5089_50890802_79_dialog_content = "!",
  ui_story_5089_50890802_80_dialog_content = "Mas esse foi um presente do príncipe herdeiro para você, um que você planejava devolver!",
  ui_story_5089_50890802_81_dialog_content = "Bem, não foi fácil para nós chegar aqui. Seria um desperdício não utilizar tudo à nossa disposição.",
  ui_story_5089_50890802_82_dialog_content = "Mas mesmo com todo esse ouro, tentar reunir mão de obra suficiente em tão pouco tempo—",
  ui_story_5089_50890802_83_dialog_content = "Eu tenho uma ideia para isso também.",
  ui_story_5089_50890802_84_dialog_content = "Não entendo as complexidades da política do tribunal, então não posso oferecer muita opinião.",
  ui_story_5089_50890802_85_dialog_content = "Mas acho que podemos simplificar um pouco as coisas com esse ouro.",
  ui_story_5089_50890802_86_dialog_content = "Afinal, o dinheiro é para ser gasto em coisas, certo?",
  ui_story_5089_50890802_87_dialog_content = "Então... O que exatamente você deseja comprar PlayerName?",
  ui_story_5089_50890802_88_dialog_content = "Estou adivinhando que esses caras nunca dirigiram um Transporte Huolong antes, certo?",
  ui_story_5089_50890802_89_dialog_content = "E com todos os transportadores indo e vindo da oficina secreta, é improvável que os moradores da vila próximos não tenham visto ou ouvido nada. Em outras palavras, não há como alguém acreditar que foi abandonado, pelo menos não recentemente.",
  ui_story_5089_50890802_90_dialog_content = "E ainda assim, de alguma forma, parece que ninguém sabia nada sobre isso até agora.",
  ui_story_5089_50890802_91_dialog_content = "Isso só pode significar que a oficina tem garantido seu sigilo recebendo remessas menores em várias entregas.",
  ui_story_5089_50890802_92_dialog_content = "Mas agora, por causa do enorme pedido dos Cavaleiros do Destino, eles parecem estar usando vários transportadores para transportar os materiais necessários.",
  ui_story_5089_50890802_93_dialog_content = "A Guilda dos Artesãos supervisiona o uso dos Transportes Huolong.",
  ui_story_5089_50890802_94_dialog_content = "A própria associação é composta por oficiais de ambas as principais seitas, bem como administradores nomeados pelo tribunal real. Juntos, eles regulam o uso dos Portadores de Huolong.",
  ui_story_5089_50890802_95_dialog_content = "Mesmo o rei não pode ignorar seus protocolos ou usá-los livremente.",
  ui_story_5089_50890802_96_dialog_content = "No entanto, eles não monitoram de perto as pessoas que alugam os transportadores.",
  ui_story_5089_50890802_97_dialog_content = "Em outras palavras, os Fate Riders provavelmente não tiveram problemas em emprestar os direitos dos transportes através de uma dessas oficinas, certo?",
  ui_story_5089_50890802_98_dialog_content = "Você está dizendo que quer investigar todas as oficinas?",
  ui_story_5089_50890802_99_dialog_content = "Não.",
  ui_story_5089_50890802_100_dialog_content = "Não há necessidade de confrontá-los diretamente. Afinal, os Fate Riders são os que estamos procurando.",
  ui_story_5089_50890802_101_dialog_content = "Agora que estou olhando de fora, acho que estou começando a entender o \"ímpeto\" que Xuan Ji estava falando.",
  ui_story_5089_50890802_102_dialog_content = "Dantang! A Guilda dos Artesãos é responsável apenas pelo aluguel dos transportadores, certo?",
  ui_story_5089_50890802_103_dialog_content = "Sim, isso mesmo.",
  ui_story_5089_50890802_104_dialog_content = "Então o que eu quero comprar...",
  ui_story_5089_50890802_105_dialog_content = "São os próprios trilhos.",
  ui_story_5089_50890802_106_dialog_content = "... Você é realmente um gênio, PlayerName!",
  ui_story_5089_50890802_107_dialog_content = "<color=#e8d9bb>Oficina Secreta</color>",
  ui_story_5089_50890802_108_dialog_content = "Qual é o problema com esses transportadores Huolong? Quem deu a vocês permissão para agir por conta própria?!",
  ui_story_5089_50890802_109_dialog_content = "Cuidado com o tom. Eu estava prestes a te fazer a mesma pergunta.",
  ui_story_5089_50890802_110_dialog_content = "Vocês nunca param de nos pressionar para entregar as armas, mas o que vocês têm feito todo esse tempo?",
  ui_story_5089_50890802_111_dialog_content = "Se não conseguirmos produzir o suficiente a tempo, apenas envie o lote destinado ao Reino Ji. Isso não deve ser muito difícil para você, certo?",
  ui_story_5089_50890802_112_dialog_content = "... Se falharmos em cumprir o pedido do Reino de Ji, isso pode afetar as relações entre nossas duas nações.",
  ui_story_5089_50890802_113_dialog_content = "Ha, até uma criança de três anos não seria tão ingênua.",
  ui_story_5089_50890802_114_dialog_content = "Estamos todos em aliança com os Fate Riders agora. Eu realmente preciso dizer a você cujas ordens seguir? Os laços entre os dois reinos não são mais nossa preocupação.",
  ui_story_5089_50890802_115_dialog_content = "A menos que... Não me diga que seu suposto \"rei\" se considera o verdadeiro governante do Reino Ye?",
  ui_story_5089_50890802_116_dialog_content = "Claro que não.",
  ui_story_5089_50890802_117_dialog_content = "Bom. Entendo que ele já foi condenado à morte, mas sua lealdade aos Cavaleiros do Destino é a única coisa que o manteve vivo como rei até hoje.",
  ui_story_5089_50890802_118_dialog_content = "Se ele ousar traí-los, perderá tudo tão rapidamente quanto ganhou.",
  ui_story_5089_50890802_119_dialog_content = "Por outro lado, com a revolta quase em mãos, qualquer caos causado pela desobediência dos estados vassalos também trabalhará a nosso favor.",
  ui_story_5089_50890802_120_dialog_content = "Certamente você entende isso, certo?",
  ui_story_5089_50890802_121_dialog_content = "... É claro.",
  ui_story_5089_50890802_122_dialog_content = "Bom, agora apresse-se e carregue as mercadorias.",
  ui_story_5089_50890802_123_dialog_content = "Senhora Zhui Hu, encontramos um problema.",
  ui_story_5089_50890802_124_dialog_content = "E agora?",
  ui_story_5089_50890802_125_dialog_content = "Parece que não podemos usar os Transportes Huolong no momento.",
  ui_story_5089_50890802_126_dialog_content = "O quê? Não pagamos os workshops para garantir o uso exclusivo dos transportes?!",
  ui_story_5089_50890802_127_dialog_content = "Th-Isso não é o problema. É só que...",
  ui_story_5089_50890802_128_dialog_content = "A estrada foi bloqueada.",
  ui_story_5089_50890802_129_dialog_content = "O quê?!",
  ui_story_5089_50890901_1_dialog_content = "Sua generosa contribuição tornou as coisas muito mais simples, PlayerName.",
  ui_story_5089_50890901_2_dialog_content = "Depois de alugar temporariamente as terras ao redor dos trilhos, pedi às pessoas para bloquear o caminho que leva à oficina secreta.",
  ui_story_5089_50890901_3_dialog_content = "Nós efetivamente paramos os Fate Riders em suas trilhas.",
  ui_story_5089_50890901_4_dialog_content = "Mas parece que nosso bloqueio está começando a causar problemas para alguns dos comerciantes itinerantes—",
  ui_story_5089_50890901_5_dialog_content = "Por favor, amigos! Estou aqui apenas para adquirir alguns grãos. Eu não fiz nada de errado!",
  ui_story_5089_50890901_6_dialog_content = "Você não deixaria nossa caravana passar, por favor?",
  ui_story_5089_50890901_7_dialog_content = "Você é do Reino Ji, não é?",
  ui_story_5089_50890901_8_dialog_content = "Por que, sim, estou. Isso é um problema? Posso garantir que tenho todos os meus documentos de negócios em ordem...",
  ui_story_5089_50890901_9_dialog_content = "(Dantang.)",
  ui_story_5089_50890901_10_dialog_content = "(Certo.)",
  ui_story_5089_50890901_11_dialog_content = "Cof, você percebe com quem está falando agora?",
  ui_story_5089_50890901_12_dialog_content = "Er, não... Eu não posso dizer que sim...",
  ui_story_5089_50890901_13_dialog_content = "Este é PlayerName, Senhor de Eraveil. Ele é um enviado especial da terra de Astra e um oficial honrado pessoalmente nomeado pelo Rei de Ji.",
  ui_story_5089_50890901_14_dialog_content = "Abençoado pela Donzela Dragão, ele é um aliado próximo da Guilda Lin, e o objeto dos avanços sinceros do príncipe herdeiro...",
  ui_story_5089_50890901_15_dialog_content = "(Tá bom, já entendi, você já fez seu ponto! Você pode ver que ele já está convencido pelo olhar nos olhos dele, então dê um descanso!)",
  ui_story_5089_50890901_16_dialog_content = "Ah, sim, eu me lembro agora! Vê-lo mais uma vez é a maior honra que eu poderia esperar, meu senhor!",
  ui_story_5089_50890901_17_dialog_content = "Diga-me, como posso ser útil para você? Farei qualquer coisa que me pedir, desde que esteja ao meu alcance... Espere, foi você quem selou a estrada, certo?",
  ui_story_5089_50890901_18_dialog_content = "Perdoe-me pela minha ignorância, meu senhor! Mesmo que você me banisse até o fim dos tempos, eu não guardaria ressentimento!",
  ui_story_5089_50890901_19_dialog_content = "N-Não é nada tão sério. Eu apenas tenho uma proposta de negócio para você, só isso.",
  ui_story_5089_50890901_20_dialog_content = "Por todos os meios, meu senhor! Oferecerei o melhor preço para tudo que desejar!",
  ui_story_5089_50890901_21_dialog_content = "Quanto ouro nos resta, Dantang?",
  ui_story_5089_50890901_22_dialog_content = "Depois de pagar pelas pistas, pela terra ao redor delas e pelos salários dos artesãos... Usamos apenas uma pequena parte de nossos fundos.",
  ui_story_5089_50890901_23_dialog_content = "Dê a ele o descanso, então.",
  ui_story_5089_50890901_24_dialog_content = "Perdão...?",
  ui_story_5089_50890901_25_dialog_content = "Quero usar esse ouro para comprar toda a comida que você adquiriu do Reino Ye.",
  ui_story_5089_50890901_26_dialog_content = "Ah, meu senhor... Isso apresenta um grande desafio, você sabe...",
  ui_story_5089_50890901_27_dialog_content = "Eu sei que você está trabalhando para o Rei de Ji.",
  ui_story_5089_50890901_28_dialog_content = "!",
  ui_story_5089_50890901_29_dialog_content = "Você pode dizer a ele que nós te forçamos a fazer isso, se precisar. Eu assumirei total responsabilidade por tudo.",
  ui_story_5089_50890901_30_dialog_content = "Eu vejo... Suponho que posso fazer uma exceção para você, meu senhor.",
  ui_story_5089_50890901_31_dialog_content = "Bom. E não se preocupe, eu sempre cumpro a minha palavra.",
  ui_story_5089_50890901_32_dialog_content = "Ufa, eles finalmente foram embora.",
  ui_story_5089_50890901_33_dialog_content = "Hehehe.",
  ui_story_5089_50890901_34_dialog_content = "Sim, sim, vá em frente e ria. Tenho certeza que minha atuação \"senhorial\" deve ter sido divertida de assistir...",
  ui_story_5089_50890901_35_dialog_content = "De maneira alguma, PlayerName. Sua performance foi muito cativante.",
  ui_story_5089_50890901_36_dialog_content = "Hum?",
  ui_story_5089_50890901_37_dialog_content = "Aquelas pessoas ali...",
  ui_story_5089_50890901_38_dialog_content = "<color=#e8d9bb>Momentos atrás—</color>",
  ui_story_5089_50890901_39_dialog_content = "Toc, toc, toc.",
  ui_story_5089_50890901_40_dialog_content = "Hã? Quem poderia ser em um momento como este?",
  ui_story_5089_50890901_41_dialog_content = "...",
  ui_story_5089_50890901_42_dialog_content = "Irmã Xuan Ji! Nosso irmão da Guilda dos Artesãos diz que o Celestita é—",
  ui_story_5089_50890901_43_dialog_content = "Suspiro, quantas vezes eu tenho que te dizer, Qian Ji? Pare de nos referir como irmãos enquanto estamos no palácio.",
  ui_story_5089_50890901_44_dialog_content = "Embora não tenhamos intenção de tomar partido, nunca é uma boa ideia dar-lhes um motivo para nos interpretar mal.",
  ui_story_5089_50890901_45_dialog_content = "É o que levou à condenação do Mestre Houfeng da última vez, lembra?",
  ui_story_5089_50890901_46_dialog_content = "Mestre Houfeng... Você quer dizer o inventor de dez anos atrás?",
  ui_story_5089_50890901_47_dialog_content = "Pelo que me lembro, ele era um artesão renegado que se recusava a se aliar a qualquer facção, e em vez disso tentava aprender de todas as fontes imagináveis.",
  ui_story_5089_50890901_48_dialog_content = "Ele supostamente era muito talentoso, mas também um tanto arrogante por causa disso. Embora ambas as facções tentassem coagi-lo a se juntar a eles, ele sempre os rejeitava.",
  ui_story_5089_50890901_49_dialog_content = "E depois que ele entrou para o tribunal como conselheiro, ele era conhecido por propor muitas ideias radicais de reforma.",
  ui_story_5089_50890901_50_dialog_content = "Ele propôs a suspensão das restrições comerciais sobre as criações de relojoaria e a instituição do controle do tribunal sobre os recursos para todas as facções.",
  ui_story_5089_50890901_51_dialog_content = "Seu fervor em servir seu país era inegável, mas suas ações eram extremas demais e falharam em considerar a realidade.",
  ui_story_5089_50890901_52_dialog_content = "Você não pode culpar mais ninguém se acabar como ele, Senhora Xuan Ji. Seu exemplo não deve ser seguido.",
  ui_story_5089_50890901_53_dialog_content = "Eu sei, mas sou um cidadão perfeitamente cumpridor da lei do reino. Você não se lembra de como fui obediente quando o rei decidiu me colocar atrás das grades?",
  ui_story_5089_50890901_54_dialog_content = "Parece que você esqueceu a razão pela qual foi preso em primeiro lugar.",
  ui_story_5089_50890901_55_dialog_content = "Seja qual for o motivo, tenho certeza de que não teve nada a ver comigo mexendo nos blasters arcanos que eu pessoalmente ajudei a projetar.",
  ui_story_5089_50890901_56_dialog_content = "Tudo bem, agora deixe-me ver essa carta.",
  ui_story_5089_50890901_57_dialog_content = "... Hahaha! Que interessante. Eu deveria ter esperado tanto de PlayerName.",
  ui_story_5089_50890901_58_dialog_content = "A estratégia dele é um pouco ortodoxa, mas para minha surpresa, parece ser a melhor linha de ação dada as circunstâncias.",
  ui_story_5089_50890901_59_dialog_content = "Parece que ele finalmente vê as coisas claramente.",
  ui_story_5089_50890901_60_dialog_content = "E o que exatamente seria isso?",
  ui_story_5089_50890901_61_dialog_content = "Não é nada para se preocupar. De qualquer forma, vou precisar que você entregue uma mensagem em breve.",
  ui_story_5089_50890901_62_dialog_content = "Como um artesão comum sem envolvimento na política, seria errado me envolver nesses assuntos.",
  ui_story_5089_50890901_63_dialog_content = "Mas como membro da guilda, é meu dever fornecer informações se isso significa eliminar qualquer traidor em nosso meio.",
  ui_story_5089_50890901_64_dialog_content = "Então, por favor, faça o seu melhor, irmão.",
  ui_story_5089_50890901_65_dialog_content = "Sim irmã.",
  ui_story_5089_50890901_66_dialog_content = "Agora então... Como você está se sentindo aí, vizinho?",
  ui_story_5089_50890901_67_dialog_content = "...",
  ui_story_5089_50890901_68_dialog_content = "Isso é estranho, pensei que falar sobre o Mestre Houfeng faria você se abrir.",
  ui_story_5089_50890901_69_dialog_content = "Afinal, seu passado parece tão familiar agora. Um cara nomeado para o tribunal real dez anos atrás, mas que se envolveu em suas lutas pelo poder e, caiu em desgraça, nunca mais foi visto ou ouvido.",
  ui_story_5089_50890901_70_dialog_content = "Posso pensar em apenas uma pessoa que atenda a todos esses critérios.",
  ui_story_5089_50890901_71_dialog_content = "... Isso não é mais da minha conta.",
  ui_story_5089_50890901_72_dialog_content = "Minhas obsessões de vida inteira com gratidão e vingança não passam de uma piada agora.",
  ui_story_5089_50890901_73_dialog_content = "Eu não sei mais como empunhar minha lâmina, o que significa que não sirvo mais para nada.",
  ui_story_5089_50890901_74_dialog_content = "Então, por favor, pare de se preocupar por minha causa, Senhora Xuan Ji.",
  ui_story_5089_50890901_75_dialog_content = "Viver para um único propósito, e merecer ser abandonado se não puder mais alcançá-lo.",
  ui_story_5089_50890901_77_dialog_content = "Eu tenho uma pergunta para você, senhorita Jiu.",
  ui_story_5089_50890901_79_dialog_content = "...",
  ui_story_5089_50890901_80_dialog_content = "Existe até uma diferença?",
  ui_story_5089_50890901_81_dialog_content = "Suspiro... Parece que não vou fazer muito progresso aqui tão cedo.",
  ui_story_5089_50890901_82_dialog_content = "Depende de você agora, meu amigo.",
  ui_story_5089_50890901_83_dialog_content = "...",
  ui_story_5089_50890901_84_dialog_content = "Algo está te incomodando, PlayerName?",
  ui_story_5089_50890901_86_dialog_content = "Perdão?",
  ui_story_5089_50890901_87_dialog_content = "Er, não é nada. Você estava dizendo algo agora?",
  ui_story_5089_50890901_88_dialog_content = "Sim. Eu estava dizendo que se os Fate Riders realmente quisessem superar nossos obstáculos, não conseguiríamos impedi-los.",
  ui_story_5089_50890901_89_dialog_content = "É por isso que sugiro que chamemos reforços.",
  ui_story_5089_50890901_90_dialog_content = "A cidade de Jingliang só pode acomodar tantos soldados dentro de suas muralhas, então a maioria deles está posicionada fora da cidade.",
  ui_story_5089_50890901_91_dialog_content = "Eles podem não ser tão poderosos quanto os soldados dentro da cidade, mas ainda estamos em clara desvantagem numérica.",
  ui_story_5089_50890901_92_dialog_content = "Então você está pensando em usar sua autoridade como princesa para trazer alguns deles para o nosso lado?",
  ui_story_5089_50890901_93_dialog_content = "Não, PlayerName.",
  ui_story_5089_50890901_94_dialog_content = "Espere... Por que você está de repente me entregando uma adaga?!",
  ui_story_5089_50890901_95_dialog_content = "Eles podem estar estacionados fora da cidade, mas isso não os torna menos unificados como soldados. Até agora, as notícias de dentro da cidade já devem ter chegado até eles.",
  ui_story_5089_50890901_96_dialog_content = "Nós dois sabemos que, neste ponto, meu \"tio\" não tem motivo para manter a mão contra mim.",
  ui_story_5089_50890901_97_dialog_content = "É seguro presumir que eles não vão me obedecer se eu me revelar para eles.",
  ui_story_5089_50890901_98_dialog_content = "Então, por que estamos aqui?",
  ui_story_5089_50890901_99_dialog_content = "Para isso.",
  ui_story_5089_50890901_100_dialog_content = "... Por que você está me dando uma adaga?",
  ui_story_5089_50890901_101_dialog_content = "Não podemos ter certeza sobre as ordens dadas aos soldados neste lugar.",
  ui_story_5089_50890901_102_dialog_content = "Mas enquanto meu \"tio\" se importar com seu status, ele não enviará abertamente alguém para me assassinar.",
  ui_story_5089_50890901_103_dialog_content = "Se esse é o caso, então eu ainda deveria ser visto como alguém que precisa de sua proteção. Sendo assim...",
  ui_story_5089_50890901_104_dialog_content = "Você quer que eu finja te sequestrar e os leve até a oficina?",
  ui_story_5089_50890901_105_dialog_content = "Mas isso é muito arriscado! Não há como prever o que pode dar errado!",
  ui_story_5089_50890901_106_dialog_content = "E se conseguirem nos capturar ao mesmo tempo? Ou pior, e se o falso rei já decidiu que você não vale a pena manter vivo?!",
  ui_story_5089_50890901_107_dialog_content = "Devemos voltar e repensar nossa estratégia antes de-",
  ui_story_5089_50890901_108_dialog_content = "<color=#e8d9bb>De repente, Dantang agarra a mão que estou usando para segurar a adaga, e a leva rapidamente ao seu pescoço.</color>",
  ui_story_5089_50890901_109_dialog_content = "Dantang?!",
  ui_story_5089_50890901_110_dialog_content = "<color=#e8d9bb>Tento desesperadamente puxá-lo para longe, mas a adaga ainda deixa uma marca vermelha em seu pescoço.</color>",
  ui_story_5089_50890901_111_dialog_content = "Por favor, me observe, PlayerName.",
  ui_story_5089_50890901_112_dialog_content = "<color=#e8d9bb>Uma gota de sangue desliza pela lâmina até minha palma, mas Dantang simplesmente ri sob a luz do sol, filtrando através das folhas da floresta.</color>",
  ui_story_5089_50890901_113_dialog_content = "Eu confio em você.",
  ui_story_5089_50890901_114_dialog_content = "... Eu sei.",
  ui_story_5089_50890901_115_dialog_content = "Quem vai lá?",
  ui_story_5089_50890901_116_dialog_content = "S-Fique atrás!",
  ui_story_5089_50890901_117_dialog_content = "Sua Princesa Zhuohua está em minhas mãos agora!",
  ui_story_5089_50890901_118_dialog_content = "!",
  ui_story_5089_50890901_119_dialog_content = "A princesa foi sequestrada! Todos os soldados, reúnam-se!",
  ui_story_5089_50890901_120_dialog_content = "Solte a princesa imediatamente, e sua vida ainda pode ser poupada!",
  ui_story_5089_50890901_121_dialog_content = "Vocês não me assustam! E além disso, você realmente acha que eu me renderia tão facilmente?!",
  ui_story_5089_50890901_122_dialog_content = "Sou um membro dos Fate Riders, e nossa fortaleza não está muito longe daqui! Temos mais lutadores e armas do que você pode lidar!",
  ui_story_5089_50890901_123_dialog_content = "Então não faça nenhum movimento brusco, ou teremos uma guerra em nossas mãos!",
  ui_story_5089_50890901_124_dialog_content = "Arqueiro! Mira!",
  ui_story_5089_50890901_125_dialog_content = "Aumento de Força!",
  ui_story_5089_50890901_126_dialog_content = "Urgh—",
  ui_story_5089_50890901_127_dialog_content = "Não o deixe escapar!",
  ui_story_5089_50890901_128_dialog_content = "Perdemos de vista a princesa e o sequestrador, senhor!",
  ui_story_5089_50890901_129_dialog_content = "Então se espalhem e procurem por eles, seu tolo! Não podemos nos dar ao luxo de deixar algo acontecer com a princesa!",
  ui_story_5089_50890901_130_dialog_content = "Mas não temos pistas para—Espere! Há uma begônia no chão aqui!",
  ui_story_5089_50890901_131_dialog_content = "Deve ser uma pista deixada pela princesa. Rápido, procure mais delas!",
  ui_story_5089_50890901_132_dialog_content = "Eles podem nos levar ao esconderijo deles!",
  ui_story_5089_50890901_133_dialog_content = "Meu senhor, um grupo de soldados de fora da cidade está se aproximando da oficina.",
  ui_story_5089_50890901_134_dialog_content = "Por que razão?",
  ui_story_5089_50890901_135_dialog_content = "Dizem que encontraram um criminoso que sequestrou a princesa.",
  ui_story_5089_50890901_136_dialog_content = "Sem ousar perder o rastro deles, o capitão do esquadrão seguiu o rastro deles até este local.",
  ui_story_5089_50890901_137_dialog_content = "Então não apenas as estradas estão bloqueadas, mas também estamos cercados por guardas da cidade.",
  ui_story_5089_50890901_138_dialog_content = "É provável que um cerco ocorra em breve.",
  ui_story_5089_50890901_139_dialog_content = "Se isso acontecer, nosso povo deve ser capaz de defender a oficina. Sugiro que os mantenhamos em posição por enquanto.",
  ui_story_5089_50890901_140_dialog_content = "No entanto, eles ainda insistem em ver o que está acontecendo aqui.",
  ui_story_5089_50890901_141_dialog_content = "Hehe.",
  ui_story_5089_50890901_142_dialog_content = "Então essa é a estratégia deles, não é? Patético.",
  ui_story_5089_50890901_143_dialog_content = "Vai.",
  ui_story_5089_50890901_144_dialog_content = "Se eles desejarem que eu me revele, então como rei, eu os confrontarei com prazer.",
  ui_story_5089_50890901_145_dialog_content = "<color=#e8d9bb>Momentos depois—</color>",
  ui_story_5089_50890901_146_dialog_content = "Graças a Deus, eles finalmente se foram.",
  ui_story_5089_50890901_147_dialog_content = "Dizem que é mais escuro debaixo da lâmpada, mas eu acho que se esconder bem debaixo do nariz do inimigo é sempre a escolha mais segura.",
  ui_story_5089_50890901_148_dialog_content = "Ainda assim, eu nunca esperava que ele ficasse aqui e remoesse o dia todo. Mesmo com o palácio em um estado tão lamentável, ele nunca chamou ninguém para consertá-lo.",
  ui_story_5089_50890901_149_dialog_content = "Mas graças a essas vigas largas, consegui me manter escondido sem forçar muito meus pobres ossos velhos.",
  ui_story_5089_50890901_150_dialog_content = "Agora que eles se foram, eu deveria conseguir sair do palácio sem nenhum problema.",
  ui_story_5089_50890901_151_dialog_content = "Hm? Não é essa... a espada da senhorita Jiu?",
  ui_story_5089_50890901_152_dialog_content = "Suponho que eu deva devolver para ela.",
  ui_story_5089_50890901_153_dialog_content = "*Ofegante* Caramba... Esse tempo todo... Eu estive correndo o mais rápido que pude...",
  ui_story_5089_50890901_154_dialog_content = "Como esses soldados conseguiram nos alcançar tão rapidamente?!",
  ui_story_5089_50890901_155_dialog_content = "Tentei distraí-los com minhas begônias o melhor que pude, mas eles perceberam mais rápido do que eu imaginava.",
  ui_story_5089_50890901_156_dialog_content = "Além disso, a perseguição implacável deles prova que o treinamento deles não é insuficiente, mesmo fora da cidade.",
  ui_story_5089_50890901_157_dialog_content = "Para o meu \"tio\" manter soldados tão bem treinados sob seu comando e aquele arsenal de armas...",
  ui_story_5089_50890901_158_dialog_content = "O que os Fate Riders poderiam estar planejando...?",
  ui_story_5089_50890901_159_dialog_content = "Não adianta pensar nisso agora. Já fizemos tudo o que podíamos fazer.",
  ui_story_5089_50890901_160_dialog_content = "Vamos apenas recuperar o fôlego aqui por um tempo.",
  ui_story_5089_50890901_161_dialog_content = "Não vi nenhum movimento vindo da oficina, mas não há como prever como eles reagirão quando nos virem.",
  ui_story_5089_50890901_162_dialog_content = "<color=#e8d9bb>Atrás de nós, os soldados bem treinados se espalham e nos cercam. As tochas em suas mãos pintam o céu noturno de vermelho fogo.</color>",
  ui_story_5089_50890901_163_dialog_content = "<color=#e8d9bb>Diante de nós, a oficina mostra sinais de atividade apesar de ninguém estar à vista. Ela se ergue sinistramente sobre nós, como uma besta enorme se preparando para atacar.</color>",
  ui_story_5089_50890901_164_dialog_content = "Eu nunca tive a chance de te dizer isso antes, PlayerName.",
  ui_story_5089_50890901_165_dialog_content = "Mesmo que eu tenha pedido sua ajuda sem vergonha, nunca tive a intenção de colocá-lo em uma situação tão perigosa hoje.",
  ui_story_5089_50890901_166_dialog_content = "Por isso, sinto muito.",
  ui_story_5089_50890901_167_dialog_content = "Não se preocupe, Dantang. Tenho a sensação de que ficaremos bem.",
  ui_story_5089_50890901_168_dialog_content = "Afinal, eu também confio em você.",
  ui_story_5089_50890901_169_dialog_content = "Huh? Algo está acontecendo com os soldados...",
  ui_story_5089_50890901_170_dialog_content = "O rei chegou—",
  ui_story_5089_50890901_171_dialog_content = "Olha, é...",
  ui_story_5089_50890901_172_dialog_content = "Meu suposto tio.",
  ui_story_5089_50890901_173_dialog_content = "Oh Dantang, eu pensei que você seria mais esperto do que isso.",
  ui_story_5089_50890901_174_dialog_content = "Você não sabe que com um único comando meu, aquela oficina permanecerá completamente intocada?",
  ui_story_5089_50890901_175_dialog_content = "Vocês são os únicos que encontrarão seu fim aqui, em um lugar onde ninguém jamais os encontrará.",
  ui_story_5089_50890901_176_dialog_content = "Vocês caminharam direto para os próprios túmulos.",
  ui_story_5089_50890901_177_dialog_content = "Se você fosse realmente meu tio, teria autoridade para nos descartar assim.",
  ui_story_5089_50890901_178_dialog_content = "Mas você não tem direito de fazer isso como um impostor e um fantoche!",
  ui_story_5089_50890901_179_dialog_content = "Diante de todas essas pessoas, vamos expor quem você realmente é—Mestre Houfeng!",
  ui_story_5089_50890902_1_dialog_content = "Agora, PlayerName!",
  ui_story_5089_50890902_2_dialog_content = "Aumento de Força!",
  ui_story_5089_50890902_3_dialog_content = "Ugh...",
  ui_story_5089_50890902_4_dialog_content = "(Esses soldados não são nosso alvo, então não devemos perder tempo lutando contra eles.)",
  ui_story_5089_50890902_5_dialog_content = "(Os Fate Riders usam máscaras semelhantes à carne para se esconderem.)",
  ui_story_5089_50890902_6_dialog_content = "(Tudo que eu preciso é de uma única abertura... Para rasgar sua máscara—!)",
  ui_story_5089_50890902_7_dialog_content = "O quê?!",
  ui_story_5089_50890902_8_dialog_content = "<color=#e8d9bb>A adaga encontra seu alvo ao lado do rosto do falso rei.</color>",
  ui_story_5089_50890902_9_dialog_content = "<color=#e8d9bb>Mas o que corta não é a máscara inorgânica que eles esperavam.</color>",
  ui_story_5089_50890902_10_dialog_content = "<color=#e8d9bb>Ao contrário, o sangue começa a se infiltrar a partir da ferida, indicando que o rosto do alvo é totalmente real.</color>",
  ui_story_5089_50890902_11_dialog_content = "Como isso pode ser...?",
  ui_story_5089_50890902_12_dialog_content = "Está praticamente confirmado agora.",
  ui_story_5089_50890902_13_dialog_content = "Diga-me, os resultados foram do seu agrado?",
  ui_story_5089_50891001_1_dialog_content = "V-Vossa Alteza...! Não fiquem aí parados, seus tolos! Defendam o rei!",
  ui_story_5089_50891001_2_dialog_content = "Abaixem as armas, todos vocês. Isso não é mais do que uma criança fazendo birra.",
  ui_story_5089_50891001_3_dialog_content = "Não... Você não pode ser o verdadeiro Rei de Ye, então por quê...?",
  ui_story_5089_50891001_4_dialog_content = "Se todo o seu esquema foi para este único momento, então sua tolice é ainda maior do que eu imaginava.",
  ui_story_5089_50891001_5_dialog_content = "Eu tenho usado essa identidade por tantos anos, e ninguém notou nada de incomum.",
  ui_story_5089_50891001_6_dialog_content = "Você realmente achou que isso poderia ser realizado com algo tão simples quanto uma máscara?",
  ui_story_5089_50891001_7_dialog_content = "!",
  ui_story_5089_50891001_8_dialog_content = "Claro que não. Nos últimos dez anos, venho fazendo pequenos ajustes graduais na minha aparência.",
  ui_story_5089_50891001_9_dialog_content = "Fatiando e esculpindo minha própria carne e ossos, tudo para obter o disfarce perfeito.",
  ui_story_5089_50891001_10_dialog_content = "Quando meus braços não eram longos o suficiente, eu os quebrei para que crescessem mais.",
  ui_story_5089_50891001_11_dialog_content = "Quando minha voz não combinava, gargarejei veneno para remodelar minha garganta e cordas vocais.",
  ui_story_5089_50891001_12_dialog_content = "Fui informado que antes de ascender ao trono, meu tio era frequentemente alvo de assassinato... Eu vejo agora.",
  ui_story_5089_50891001_13_dialog_content = "Você certamente foi além do esperado pelos Fate Riders.",
  ui_story_5089_50891001_14_dialog_content = "Os Cavaleiros do Destino, você diz? Ha! Esses covardes não são diferentes dos ratos que infestam as sombras do império.",
  ui_story_5089_50891001_15_dialog_content = "Esses vermes insolentes estão terrivelmente enganados se pensam que podem desafiar o legítimo rei do Reino de Ye!",
  ui_story_5089_50891001_16_dialog_content = "Você...",
  ui_story_5089_50891001_17_dialog_content = "Nosso ritual anual de supressão começou a nos falhar, e o novo imperador é jovem e inexperiente demais para nos guiar através da tempestade que se aproxima. Se nada mudar, nossas terras logo serão mergulhadas na escuridão.",
  ui_story_5089_50891001_18_dialog_content = "Inicialmente, pretendia proceder com cuidado para manter nosso relacionamento com o Reino Ji.",
  ui_story_5089_50891001_19_dialog_content = "Mas com as coisas como estão agora, não vejo problema em entregar todas as nossas armas aos Cavaleiros do Destino.",
  ui_story_5089_50891001_20_dialog_content = "Com essas armas de fogo em mãos, a rebelião deles começará ainda mais cedo.",
  ui_story_5089_50891001_21_dialog_content = "Por anos, os Cavaleiros do Destino infiltraram-se nos tribunais dos vários reinos de Longzhou. A inundação de Haojin apenas demonstrou o que acontecerá com o resto dos estados vassalos. Uma vez que eles estejam ocupados com suas próprias crises, os Cavaleiros do Destino voltarão a mirar a capital imperial de Yangjing.",
  ui_story_5089_50891001_22_dialog_content = "Enquanto o louva-a-deus persegue a cigarra, o pardal espera pacientemente para reivindicar os despojos de sua batalha.",
  ui_story_5089_50891001_23_dialog_content = "Por anos, aguardei meu tempo, esperando pela rajada de vento perfeita, mas ela nunca veio.",
  ui_story_5089_50891001_24_dialog_content = "Recuso-me a esperar mais. Serei o vento que me leva à vitória!",
  ui_story_5089_50891001_25_dialog_content = "Ao longo de dez longos anos, treinei incansavelmente as minhas tropas para que estejam prontas para a guerra a qualquer momento.",
  ui_story_5089_50891001_26_dialog_content = "Quando as forças dessas terras finalmente se chocarem, o vencedor não será necessariamente decidido pelo poder dos Fate Riders.",
  ui_story_5089_50891001_27_dialog_content = "Você descobriu meu segredo, Dantang.",
  ui_story_5089_50891001_28_dialog_content = "Mas, apesar de sua tolice, seus talentos ainda seriam de grande valor para o reino. Você está disposto a continuar me seguindo como seu rei?",
  ui_story_5089_50891001_29_dialog_content = "Basta acenar com a cabeça e eu garanto que você continuará sendo a Princesa Zhuohua do Reino Ye.",
  ui_story_5089_50891001_30_dialog_content = "Quanto a você, Celestita, suas habilidades também seriam de uso inegável para mim na batalha. Você se alinhará com meus nobres objetivos?",
  ui_story_5089_50891001_31_dialog_content = "Pois em breve, os sete reinos de Longzhou cairão sob o meu domínio...",
  ui_story_5089_50891001_32_dialog_content = "Você está ciente de que os Fate Riders têm conspirado com os espíritos malignos, e que inúmeras vidas foram perdidas como resultado de sua traição?",
  ui_story_5089_50891001_33_dialog_content = "Claro. Estou plenamente ciente de seus métodos, dado que o Reino Ye é a principal fonte de suas armas.",
  ui_story_5089_50891001_34_dialog_content = "Mas por que eu deveria me preocupar com as vidas dos outros quando eles não podem ser úteis para mim? Preocupar-se com os súditos dos meus inimigos mortais é mostrar fraqueza como conquistador.",
  ui_story_5089_50891001_35_dialog_content = "Quanto aos espíritos malignos, eles não são diferentes de animais selvagens. Se os Cavaleiros do Destino têm a audácia de empregá-los em seus métodos, que assim seja.",
  ui_story_5089_50891001_36_dialog_content = "Eu sempre posso me desfazer deles mais tarde, se a necessidade exigir.",
  ui_story_5089_50891001_37_dialog_content = "Eu entendo suas opiniões, mas parece—",
  ui_story_5089_50891001_38_dialog_content = "Que nossos caminhos são muito diferentes para serem alinhados.",
  ui_story_5089_50891001_39_dialog_content = "Eu sugiro fortemente que você não me desafie, princesa.",
  ui_story_5089_50891001_40_dialog_content = "Uh... Posso te perguntar uma coisa?",
  ui_story_5089_50891001_41_dialog_content = "É realmente ok para você estar dizendo tudo isso em voz alta?",
  ui_story_5089_50891001_42_dialog_content = "Há uma oficina cheia de Fate Riders bem ao nosso lado.",
  ui_story_5089_50891001_43_dialog_content = "Já ordenei ao meu pessoal para trancar aquela oficina. Ao contrário de você, eu me esforço muito para me preparar para o meu próximo passo.",
  ui_story_5089_50891001_44_dialog_content = "Os Fate Riders aspiram alcançar grandes coisas, mas ainda dependem do meu poder de fogo.",
  ui_story_5089_50891001_45_dialog_content = "Uma vez que as armas tenham sido entregues, não tenho razão para me importar se as pessoas naquela oficina vivem ou morrem.",
  ui_story_5089_50891001_46_dialog_content = "Então, o que acontecerá se você não conseguir entregar suas armas nos próximos três dias?",
  ui_story_5089_50891001_47_dialog_content = "... Como você descobriu isso?",
  ui_story_5089_50891001_48_dialog_content = "Bem, me disseram que minhas habilidades como Celestita são inegavelmente úteis.",
  ui_story_5089_50891001_49_dialog_content = "Mas, mais ao ponto, tenho quase certeza de que você não vai mais cumprir seu prazo.",
  ui_story_5089_50891001_50_dialog_content = "O que é que você fez?",
  ui_story_5089_50891001_51_dialog_content = "Grande Rei! Houve um problema—",
  ui_story_5089_50891001_52_dialog_content = "Falar!",
  ui_story_5089_50891001_53_dialog_content = "É a Guilda dos Artesãos! Seus membros estão desmontando os trilhos do Transportador Huolong neste exato momento! Todas as nossas rotas de transporte planejadas originalmente estão fora de serviço!",
  ui_story_5089_50891001_54_dialog_content = "Quem permitiu que uma coisa dessas acontecesse?!",
  ui_story_5089_50891001_55_dialog_content = "A guilda alega que—",
  ui_story_5089_50891001_56_dialog_content = "Um filantropo rico fez uma generosa doação para alguns reparos muito necessários, é tudo.",
  ui_story_5089_50891001_57_dialog_content = "Os trilhos estavam completamente desgastados devido ao descuido e mau uso pelos operadores de transporte.",
  ui_story_5089_50891001_58_dialog_content = "Minha única condição era especificar a ordem em que as faixas foram reparadas. Um pedido simples o suficiente, certo?",
  ui_story_5089_50891001_59_dialog_content = "Até nos ajudou a direcionar sua atenção para um problema muito sério que afeta seu reino.",
  ui_story_5089_50891001_60_dialog_content = "Eles já fizeram grande parte do trabalho de desmontagem. Mesmo que você começasse a reconstruir as faixas agora, levaria mais de três dias para terminá-las.",
  ui_story_5089_50891001_61_dialog_content = "Desde o início, este era o \"caminho\" que eu queria seguir... Se me permite a brincadeira.",
  ui_story_5089_50891001_62_dialog_content = "Seus truques sujos nunca terão sucesso! Tudo que é preciso é uma ordem do rei para...",
  ui_story_5089_50891001_63_dialog_content = "Silêncio, idiota!",
  ui_story_5089_50891001_64_dialog_content = "Talvez você esteja certo: talvez minhas táticas realmente sejam desonestas.",
  ui_story_5089_50891001_65_dialog_content = "Mas você deveria saber até agora que não estamos mais focados nos meios.",
  ui_story_5089_50891001_66_dialog_content = "Para a Guilda dos Artesãos se aliar a você... Foi obra da Ministra Armilla?",
  ui_story_5089_50891001_67_dialog_content = "Ela não foi presa por mexer nos blasters arcanos, mas por descobrir seu segredo. Não é isso, \"Sua Alteza\"?",
  ui_story_5089_50891001_68_dialog_content = "Desde o momento em que você falhou em trancá-la completamente, você perdeu.",
  ui_story_5089_50891001_69_dialog_content = "Mesmo que você consiga manter o trono do Reino Ye—",
  ui_story_5089_50891001_70_dialog_content = "Todos os funcionários do tribunal e artesãos em Longzhou podem estar observando cada movimento seu pelas sombras agora.",
  ui_story_5089_50891001_71_dialog_content = "Hoje, as trilhas do transporte estão sendo desmontadas, mas amanhã, pode haver uma falha em um boi de madeira.",
  ui_story_5089_50891001_72_dialog_content = "Mesmo que você mude para uma carruagem puxada por cavalos, os cavalos podem não ser fortes o suficiente para manter as coisas em movimento.",
  ui_story_5089_50891001_73_dialog_content = "Sem os Transportes Huolong, imagino que seria impossível transportar grandes quantidades de carga rapidamente.",
  ui_story_5089_50891001_74_dialog_content = "Mas a coisa mais importante, é claro...",
  ui_story_5089_50891001_75_dialog_content = "Quão difícil seria explicar ao seu reino por que você está enviando tantas armas de fogo para fora do país?",
  ui_story_5089_50891001_76_dialog_content = "...",
  ui_story_5089_50891001_77_dialog_content = "Minhas desculpas, \"Sua Alteza\".",
  ui_story_5089_50891001_78_dialog_content = "Independentemente do que acontece a seguir...",
  ui_story_5089_50891001_79_dialog_content = "O \"ímpeto\" está atualmente a meu favor.",
  ui_story_5089_50891001_80_dialog_content = "Entendi.",
  ui_story_5089_50891001_81_dialog_content = "O caminho que você está bloqueando não é o do destino, mas o meu.",
  ui_story_5089_50891001_82_dialog_content = "Quando você disse que estávamos entrando em uma armadilha, você já considerou que na verdade estávamos armando a armadilha para você?",
  ui_story_5089_50891001_83_dialog_content = "Você está sem opções, Mestre Houfeng.",
  ui_story_5089_50891001_84_dialog_content = "Se você não entregar as armas a tempo, os Fate Riders inevitavelmente virão investigar.",
  ui_story_5089_50891001_85_dialog_content = "Com base no que você acabou de dizer, sua lealdade a Junming é questionável, no mínimo. Suas ações, temo, podem não resistir ao escrutínio deles.",
  ui_story_5089_50891001_86_dialog_content = "Agora podemos, por favor, sentar e ter uma discussão civilizada?",
  ui_story_5089_50891001_88_dialog_content = "Uma discussão civilizada, você diz? Hahaha! Você esqueceu que eu ainda sou o rei?",
  ui_story_5089_50891001_89_dialog_content = "O destino do Reino Ye repousa unicamente em minhas mãos!",
  ui_story_5089_50891001_90_dialog_content = "Recuso-me a deixar qualquer um de vocês atrapalhar o meu—!",
  ui_story_5089_50891001_91_dialog_content = "<color=#e8d9bb>Jato—</color>",
  ui_story_5089_50891001_92_dialog_content = "<color=#e8d9bb>O som abafado de uma lâmina entrando na carne é ouvido.</color>",
  ui_story_5089_50891001_93_dialog_content = "<color=#e8d9bb>Logo depois, o sangue começa a respingar em todas as direções.</color>",
  ui_story_5089_50891001_94_dialog_content = "Houfeng—!",
  ui_story_5089_50891001_95_dialog_content = "<color=#e8d9bb>Por trás, um gancho de metal afiado perfura o corpo do falso rei.</color>",
  ui_story_5089_50891001_96_dialog_content = "Isso é... Um Ferrão!",
  ui_story_5089_50891001_97_dialog_content = "*suspiro* Por que você simplesmente não ficou quieto e seguiu as ordens?",
  ui_story_5089_50891001_98_dialog_content = "Ao contrário das minhas belas criações de relojoaria, que são o resultado de extensa pesquisa e planejamento paciente...",
  ui_story_5089_50891001_99_dialog_content = "Ambições imprudentes e irreais como as suas podem ser mortais.",
  ui_story_5089_50891001_100_dialog_content = "Você... Como ousa...!",
  ui_story_5089_50891001_101_dialog_content = "A princesa fez uma observação válida.",
  ui_story_5089_50891001_102_dialog_content = "Você subestima demais os Fate Riders.",
  ui_story_5089_50891001_103_dialog_content = "Meu mestre decretou que o Reino já não nos serve mais para nenhum propósito.",
  ui_story_5089_50891001_104_dialog_content = "Recebi total liberdade sobre suas terras e começarei testando todo o poder de fogo do meu Stinger!",
  ui_story_5089_50891001_105_dialog_content = "E eu devo tudo a você, poderoso rei. Se você não tivesse me dado a Chama Zhuyin, nada disso teria acontecido! Hahaha!",
  ui_story_5089_50891001_106_dialog_content = "Agora então... Acredito que minhas ordens eram para nivelar aquela montanha ali.",
  ui_story_5089_50891001_107_dialog_content = "Ajuste os alvos e comece a carregar, Stinger. Ainda temos muito trabalho a fazer.",
  ui_story_5089_50891001_108_dialog_content = "<color=#e8d9bb>O Stinger arranca violentamente sua cauda do falso rei, que desmorona no chão.</color>",
  ui_story_5089_50891001_109_dialog_content = "Isso mesmo, quase esqueci desse traidor inútil...",
  ui_story_5089_50891001_110_dialog_content = "Por ordem dos Cavaleiros do Destino, execute este homem!",
  ui_story_5089_50891001_111_dialog_content = "Sua Alteza—",
  ui_story_5089_50891001_112_dialog_content = "<color=#e8d9bb>Os guardas reais se preparam para avançar, mas algo lança suas fileiras em completo pandemônio.</color>",
  ui_story_5089_50891001_113_dialog_content = "<color=#e8d9bb>Para seu total choque, vários soldados levantam suas armas e começam a atacar seus camaradas!</color>",
  ui_story_5089_50891001_114_dialog_content = "Isso não é bom! O Rei tá em—",
  ui_story_5089_50891001_115_dialog_content = "Begônias Brilhantes!",
  ui_story_5089_50891001_116_dialog_content = "Você...",
  ui_story_5089_50891001_117_dialog_content = "Não se engane, eu não tenho a intenção de me aliar a você.",
  ui_story_5089_50891001_118_dialog_content = "Mas enquanto você viver, podemos enfrentar os Fate Riders.",
  ui_story_5089_50891001_119_dialog_content = "Há também a questão de responsabilizá-lo por seus crimes.",
  ui_story_5089_50891001_120_dialog_content = "Tosse... Por que se dar ao trabalho...",
  ui_story_5089_50891001_121_dialog_content = "Se você não escapar agora... Você não vai viver... Para se arrepender.",
  ui_story_5089_50891001_122_dialog_content = "Meu único arrependimento é que eu não arrisquei tudo e te substituí antes.",
  ui_story_5089_50891001_123_dialog_content = "Aos pés daquela montanha estão inúmeros civis inocentes, bem como os campos que os nutrem e sustentam.",
  ui_story_5089_50891001_124_dialog_content = "Se eu fugisse agora, nunca mais poderia me chamar de princesa do Reino Ye.",
  ui_story_5089_50891001_125_dialog_content = "Então aqui estou, e PlayerName não é diferente. É tarde demais para virar as costas e fugir agora!",
  ui_story_5089_50891001_126_dialog_content = "Heh... Que surpresa... Eu nunca soube...",
  ui_story_5089_50891001_127_dialog_content = "Você era ainda mais arrogante do que eu.",
  ui_story_5089_50891001_128_dialog_content = "Mas palavras não significam nada... Se você não conseguir sobreviver.",
  ui_story_5089_50891001_129_dialog_content = "<color=#e8d9bb>Enquanto os guardas reais continuam sua batalha uns contra os outros, outro grupo de assassinos Cavaleiro do Destino sai correndo da oficina!</color>",
  ui_story_5089_50891002_1_dialog_content = "Se a batalha continuar assim, receio que as probabilidades estarão contra nós.",
  ui_story_5089_50891002_2_dialog_content = "Senhorita Jiu.",
  ui_story_5089_50891002_3_dialog_content = "Você realmente não tem nada a dizer sobre tudo isso?",
  ui_story_5089_50891002_4_dialog_content = "...",
  ui_story_5089_50891002_5_dialog_content = "Ahn???",
  ui_story_5089_50891002_6_dialog_content = "Quem tá aí?!",
  ui_story_5089_50891002_7_dialog_content = "Nosso mestre nos ordenou para exterminar aqueles que estão em nosso caminho.",
  ui_story_5089_50891002_8_dialog_content = "Hmph, então eles também infiltraram o palácio.",
  ui_story_5089_50891002_9_dialog_content = "Relâmpago Flash!",
  ui_story_5089_50891002_10_dialog_content = "...",
  ui_story_5089_50891002_11_dialog_content = "!",
  ui_story_5089_50891002_12_dialog_content = "Sai do meu caminho!",
  ui_story_5089_50891002_13_dialog_content = "Senhorita Jiu, mesmo que você decida ignorar tudo o que está acontecendo ao seu redor...",
  ui_story_5089_50891002_14_dialog_content = "Você realmente vai se deixar ser morto por esses ratos que são covardes demais para mostrar seus próprios rostos?!",
  ui_story_5089_50891002_15_dialog_content = "...",
  ui_story_5089_50891101_1_dialog_content = "Eurgh—",
  ui_story_5089_50891101_2_dialog_content = "Mantenha-se, Dantang! Estamos quase—Ugh...",
  ui_story_5089_50891101_3_dialog_content = "PlayerName! Essa não... Você está pegando fogo!",
  ui_story_5089_50891101_4_dialog_content = "Tudo bem; eu apenas usei demais minhas habilidades. Vou ficar bem logo...",
  ui_story_5089_50891101_5_dialog_content = "Certamente não me parece assim!",
  ui_story_5089_50891101_6_dialog_content = "... Espere.",
  ui_story_5089_50891101_7_dialog_content = "Nós nos conhecemos o suficiente para que eu entenda suas habilidades bastante bem.",
  ui_story_5089_50891101_8_dialog_content = "Podemos estar em menor número, mas mesmo uma batalha dessa intensidade não deveria ser suficiente para te exaurir assim.",
  ui_story_5089_50891101_9_dialog_content = "O que mais você tem feito?",
  ui_story_5089_50891101_10_dialog_content = "... Parece que o gabarito acabou.",
  ui_story_5089_50891101_11_dialog_content = "Desculpe, eu queria te contar, mas nunca encontrei a chance.",
  ui_story_5089_50891101_12_dialog_content = "Mas agora... Acho que é mais rápido apenas mostrar a você.",
  ui_story_5089_50891101_13_dialog_content = "?",
  ui_story_5089_50891101_14_dialog_content = "Varredura Psíquica!",
  ui_story_5089_50891101_15_dialog_content = "Então, você finalmente chegou.",
  ui_story_5089_50891101_16_dialog_content = "Você me fez esperar por bastante tempo, princesa.",
  ui_story_5089_50891101_17_dialog_content = "Ministra Armilla! Mas... Por que você está...",
  ui_story_5089_50891101_18_dialog_content = "Por mais que eu gostaria de colocar o papo em dia, ainda tenho alguns convidados indesejados para lidar do meu lado.",
  ui_story_5089_50891101_19_dialog_content = "Xuan Ji, atrás de você!",
  ui_story_5089_50891101_20_dialog_content = "Relâmpago Flash!",
  ui_story_5089_50891101_21_dialog_content = "Muito apreciado, PlayerName.",
  ui_story_5089_50891101_22_dialog_content = "Você tem guiado ambas as nossas batalhas todo esse tempo, PlayerName?! Não é à toa que seu fardo é tão grande!",
  ui_story_5089_50891101_23_dialog_content = "Se você está preocupado com isso, deveria perguntar a ele quanto tempo ele manteve sua conexão psíquica comigo. A resposta pode te surpreender!",
  ui_story_5089_50891101_24_dialog_content = "...",
  ui_story_5089_50891101_25_dialog_content = "PlayerName?",
  ui_story_5089_50891101_26_dialog_content = "É... Não faz muito tempo... Eu só comecei a me comunicar com Xuan Ji ontem.",
  ui_story_5089_50891101_27_dialog_content = "Sim. Para ser exato, um dia e uma noite inteira.",
  ui_story_5089_50891101_28_dialog_content = "É sua própria culpa por não explicar as coisas mais claramente, sabe...",
  ui_story_5089_50891101_29_dialog_content = "Além disso, tenho sido cuidadoso para não manter uma conexão forte com ela, a menos que aconteça uma emergência...",
  ui_story_5089_50891101_30_dialog_content = "Mas para manter até mesmo uma conexão fraca, significa que você não dormiu esse tempo todo.",
  ui_story_5089_50891101_31_dialog_content = "...",
  ui_story_5089_50891101_32_dialog_content = "Eu também não sou o único.",
  ui_story_5089_50891101_33_dialog_content = "Você está certo... Eu também devo um pedido de desculpas a Jiu.",
  ui_story_5089_50891101_34_dialog_content = "O que você disse ontem à noite me fez preocupar que você faria algo imprudente, então eu secretamente me conectei com você para estar seguro.",
  ui_story_5089_50891101_35_dialog_content = "Também vi sua batalha com o Rei de Ye.",
  ui_story_5089_50891101_36_dialog_content = "Eu sei como você deve se sentir, mas...",
  ui_story_5089_50891101_37_dialog_content = "Cuidado!",
  ui_story_5089_50891101_38_dialog_content = "Nngh...",
  ui_story_5089_50891101_39_dialog_content = "Dantang! Você está bem?!",
  ui_story_5089_50891101_40_dialog_content = "!",
  ui_story_5089_50891101_41_dialog_content = "Por favor, Jiu! Eu sei que você está em um lugar terrível agora, mas precisamos da sua ajuda!",
  ui_story_5089_50891101_42_dialog_content = "Mas... Mas eu...",
  ui_story_5089_50891101_43_dialog_content = "<color=#e8d9bb>Jiu faz uma pausa e solta um suspiro pesado.</color>",
  ui_story_5089_50891101_44_dialog_content = "<color=#e8d9bb>Sem dizer nada, ela pega a adaga que o assassino Cavaleiro do Destino deixou cair e a empurra contra ele.</color>",
  ui_story_5089_50891101_45_dialog_content = "!",
  ui_story_5089_50891101_46_dialog_content = "<color=#e8d9bb>Ele desvia em pânico, mas a adaga apenas o roça antes de escorregar da mão de Jiu e bater contra a parede.</color>",
  ui_story_5089_50891101_47_dialog_content = "Senhorita Jiu, você...",
  ui_story_5089_50891101_48_dialog_content = "No passado, minha lâmina não era diferente do meu corpo.",
  ui_story_5089_50891101_49_dialog_content = "Seja ferido ou manchado de sangue, não fazia diferença para mim.",
  ui_story_5089_50891101_50_dialog_content = "O caminho da minha espada era claro - a gratidão é o que guiou cada balanço e cada golpe.",
  ui_story_5089_50891101_51_dialog_content = "Mas agora que meu caminho não está mais claro, minha habilidade com a espada também me abandonou.",
  ui_story_5089_50891101_52_dialog_content = "Como você pode ver, eu não consigo mais empunhar uma lâmina.",
  ui_story_5089_50891101_53_dialog_content = "Jiu...",
  ui_story_5089_50891101_54_dialog_content = "Concentre-se na batalha, PlayerName. Não temos mais tempo para nos preocupar com pessoas irrelevantes como ela.",
  ui_story_5089_50891101_55_dialog_content = "No início eu tinha dúvidas, mas agora vejo que aliviá-la como minha guarda foi a escolha certa afinal.",
  ui_story_5089_50891101_56_dialog_content = "D-Dantang?",
  ui_story_5089_50891101_57_dialog_content = "Por dez anos, ela se dedicou à arte da lâmina, mas agora está disposta a jogar tudo fora sem pensar duas vezes.",
  ui_story_5089_50891101_58_dialog_content = "Sua professora, a chamada \"maior espadachim do mundo\", aparentemente não era nada mais do que um nome sem substância.",
  ui_story_5089_50891101_59_dialog_content = "... Minha falta de habilidade não é motivo para caluniar o nome do meu mestre assim, Alteza.",
  ui_story_5089_50891101_60_dialog_content = "Seu \"mestre\"? Você ainda pode chamá-lo assim como você está agora?",
  ui_story_5089_50891101_61_dialog_content = "Porque parece que os ensinamentos dele não são mais refletidos na sua esgrima.",
  ui_story_5089_50891101_62_dialog_content = "...",
  ui_story_5089_50891101_63_dialog_content = "Se você está tão obcecado em acertar as contas, então vamos acertar algumas agora mesmo.",
  ui_story_5089_50891101_64_dialog_content = "Você teve pais que te amaram, vizinhos que cuidaram de você e professores que te orientaram.",
  ui_story_5089_50891101_65_dialog_content = "Se não fosse pelos esforços da Capitã Yuebai e da Ministra Armilla a bordo do Shadowind, provavelmente estaríamos no fundo do mar agora.",
  ui_story_5089_50891101_66_dialog_content = "E não vamos esquecer que PlayerName nunca te abandonou, especialmente agora.",
  ui_story_5089_50891101_67_dialog_content = "No entanto, você nunca realmente prestou atenção à consideração que lhe foi concedida. Que desperdício vergonhoso de bondade.",
  ui_story_5089_50891101_68_dialog_content = "... Suas percepções sobre meu caráter são totalmente corretas, Sua Alteza.",
  ui_story_5089_50891101_69_dialog_content = "Minha dívida com todos vocês é mais do que eu jamais poderia pagar. Eu não poderia deixar de entender isso.",
  ui_story_5089_50891101_70_dialog_content = "Mas e você, Senhora Dantang?",
  ui_story_5089_50891101_71_dialog_content = "Considero que servi fielmente ao seu lado, nunca te abandonando nem por um momento.",
  ui_story_5089_50891101_72_dialog_content = "E ainda assim você me jogou de lado sem dizer outra palavra, como se eu fosse um par de sapatos desgastados!",
  ui_story_5089_50891101_73_dialog_content = "Você está bravo comigo, Jiu?",
  ui_story_5089_50891101_74_dialog_content = "E aqui eu pensei que você tinha se tornado nada mais do que um fantoche sem alma.",
  ui_story_5089_50891101_75_dialog_content = "Peço desculpas. Decepcionei você mais uma vez, Alteza?",
  ui_story_5089_50891101_76_dialog_content = "Sim, realmente.",
  ui_story_5089_50891101_77_dialog_content = "Como sabemos que você ainda é capaz de emoção, significa que você também pode entender nossa preocupação por você.",
  ui_story_5089_50891101_78_dialog_content = "Então por que você insiste em suprimir sua lâmina por coisas como gratidão e vingança?!",
  ui_story_5089_50891101_79_dialog_content = "Sua Alteza...?",
  ui_story_5089_50891101_80_dialog_content = "Dantang, atrás de você—!",
  ui_story_5089_50891101_81_dialog_content = "Begônias Brilhantes!",
  ui_story_5089_50891101_82_dialog_content = "<color=#e8d9bb>Sem olhar para trás, um mar de begônias irrompe atrás de Dantang e avança em todas as direções.</color>",
  ui_story_5089_50891101_83_dialog_content = "Há uma última coisa que preciso te contar.",
  ui_story_5089_50891101_84_dialog_content = "Eu não te deixei por causa da sua lealdade aos outros, mas porque você não entendeu.",
  ui_story_5089_50891101_85_dialog_content = "<color=#e8d9bb>Num piscar de olhos, begônias florescem o quanto os olhos podem ver.</color>",
  ui_story_5089_50891101_86_dialog_content = "<color=#e8d9bb>Ao pisar neste mar de flores, seus inimigos abaixam suas armas e ficam em um estado de transe.</color>",
  ui_story_5089_50891101_87_dialog_content = "<color=#e8d9bb>No meio deles, a aparência manchada de sangue de Dantang é inimaginavelmente cativante.</color>",
  ui_story_5089_50891101_88_dialog_content = "\"O universo segue cinquenta leis, mas o Céu guarda quarenta e nove segredos, deixando um único caminho para a humanidade.\"",
  ui_story_5089_50891101_89_dialog_content = "Até os céus volúveis deixam um caminho para nós, então por que você insiste em se restringir assim?",
  ui_story_5089_50891101_90_dialog_content = "Vou te dizer de novo as palavras que não consegui terminar na estalagem.",
  ui_story_5089_50891101_91_dialog_content = "Deve ser engaiolado se você busca admirar a plumagem esplêndida de um pássaro.",
  ui_story_5089_50891101_92_dialog_content = "Se você busca admirar a vibrante pelagem de um tigre, ele deve ser caçado e transformado em um casaco.",
  ui_story_5089_50891101_93_dialog_content = "Mas isso não é verdadeira admiração.",
  ui_story_5089_50891101_94_dialog_content = "Todas as criaturas vivas nascem livres. Deixe-as voar pelo céu e rugir dos topos das montanhas se você realmente deseja admirá-las.",
  ui_story_5089_50891101_95_dialog_content = "Forcei você a buscar a verdade porque não quero ser o grilhão que te prende para sempre.",
  ui_story_5089_50891101_96_dialog_content = "Não desejo mais que você me proteja e obedeça a todos os meus caprichos. Não quero que você passe o resto da sua vida como uma lâmina escondida nas sombras.",
  ui_story_5089_50891101_97_dialog_content = "Quero que você mantenha a cabeça erguida e viva livremente sob a luz do sol.",
  ui_story_5089_50891101_98_dialog_content = "Quero que seu nome esteja ao lado do meu nos anais da história, não como um silencioso guardião, mas como um orgulhoso e amado general.",
  ui_story_5089_50891101_99_dialog_content = "Quero que você me siga por vontade própria.",
  ui_story_5089_50891101_100_dialog_content = "Eu quero-",
  ui_story_5089_50891101_101_dialog_content = "Ser um verdadeiro governante para você!",
  ui_story_5089_50891101_102_dialog_content = "Princesa Dantang...",
  ui_story_5089_50891101_103_dialog_content = "Você não é mais meu protetor. Eu não tenho mais o direito de lhe dar comandos agora.",
  ui_story_5089_50891101_104_dialog_content = "Mas agora que você não está mais preso por dever, gratidão ou vingança, se ainda estiver disposto a me emprestar sua força...",
  ui_story_5089_50891101_105_dialog_content = "Então levante-se! Rasteje se precisar, mas faça isso agora—",
  ui_story_5089_50891101_106_dialog_content = "Jiu!",
  ui_story_5089_50891101_107_dialog_content = "Levante-se e fique ao meu lado!",
  ui_story_5089_50891101_108_dialog_content = "... Já lhe disse alguma vez o quão teimoso você pode ser, Sua Alteza?",
  ui_story_5089_50891101_109_dialog_content = "Nem mesmo uma vez.",
  ui_story_5089_50891101_110_dialog_content = "Então venha aqui e diga para mim.",
  ui_story_5089_50891101_111_dialog_content = "...",
  ui_story_5089_50891101_112_dialog_content = "Como desejar.",
  ui_story_5089_50891101_113_dialog_content = "<color=#e8d9bb>Momentos depois.</color>",
  ui_story_5089_50891101_114_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5089_50891101_115_dialog_content = "<color=#e8d9bb>Os portões do palácio recém-reparados desmoronam pela segunda vez.</color>",
  ui_story_5089_50891101_116_dialog_content = "O condenado está fugindo! Vá atrás dela!",
  ui_story_5089_50891101_117_dialog_content = "Estou de volta, Irmã Xu—Ah! O-O que diabos está acontecendo aqui?!",
  ui_story_5089_50891101_118_dialog_content = "Ah, nada, nosso convidado mais recente apenas decidiu partir, só isso.",
  ui_story_5089_50891101_119_dialog_content = "Es-Esse vento que senti agora... Foi ela?!",
  ui_story_5089_50891101_120_dialog_content = "Isso mesmo. Minha última luta me deixou um pouco esgotado, então pedi a ela para abrir um caminho para sairmos da prisão.",
  ui_story_5089_50891101_121_dialog_content = "Sinceramente... Ei, espere um minuto!",
  ui_story_5089_50891101_122_dialog_content = "Essa garota realmente acabou de sair sem uma arma?",
  ui_story_5089_50891101_123_dialog_content = "Claro. Com suas habilidades, ela poderia facilmente dividir este palácio ao meio.",
  ui_story_5089_50891101_124_dialog_content = "Eu também não ousaria colocar uma espada nas mãos dela agora.",
  ui_story_5089_50891101_125_dialog_content = "Então ela planeja enfrentar todo o exército do rei completamente desarmada?! Você não está preocupado com a segurança dela?!",
  ui_story_5089_50891101_126_dialog_content = "O que há para se preocupar?",
  ui_story_5089_50891101_127_dialog_content = "Eu sei que a tristeza dela não era muito para se ver antes, mas agora—",
  ui_story_5089_50891101_128_dialog_content = "Ninguém pode pará-la a menos que ela mesma permita.",
  ui_story_5089_50891101_129_dialog_content = "Lá está ela! Cerquem a fugitiva antes que ela tente escapar!",
  ui_story_5089_50891101_130_dialog_content = "Olha, ela está desarmada! Agarrem ela!",
  ui_story_5089_50891101_131_dialog_content = "Que ingenuidade sua assumir que estou desarmado.",
  ui_story_5089_50891101_132_dialog_content = "Eu posso não ter uma lâmina na mão, mas qualquer coisa pode servir como arma para um verdadeiro espadachim.",
  ui_story_5089_50891101_133_dialog_content = "<color=#e8d9bb>Com um rodopio, ela desaparece na escuridão da noite. De repente—</color>",
  ui_story_5089_50891101_134_dialog_content = "<color=#e8d9bb>Pétalas se espalham.</color>",
  ui_story_5089_50891101_135_dialog_content = "O que... O que é isso...?",
  ui_story_5089_50891101_136_dialog_content = "<color=#e8d9bb>Folhas se reúnem.</color>",
  ui_story_5089_50891101_137_dialog_content = "Ei, qual é o problema com você? Por que você está deitado no chão assim?! Levante-se e—Uwaaaa!",
  ui_story_5089_50891101_138_dialog_content = "<color=#e8d9bb>Vassoura de bambu.</color>",
  ui_story_5089_50891101_139_dialog_content = "Corra! Corra para suas vidas! Aaaahhhh—",
  ui_story_5089_50891101_140_dialog_content = "<color=#e8d9bb>Sombras cintilam.</color>",
  ui_story_5089_50891101_141_dialog_content = "Aí está você! Toma essa!",
  ui_story_5089_50891101_142_dialog_content = "U-Um manto? Mas de onde ela... Urgh...",
  ui_story_5089_50891101_143_dialog_content = "<color=#e8d9bb>Em um instante, Jiu corta um caminho sangrento através de inúmeros soldados.</color>",
  ui_story_5089_50891101_144_dialog_content = "Um demônio... Ela tem que ser algum tipo de demônio!",
  ui_story_5089_50891101_145_dialog_content = "Não. Definitivamente sou uma pessoa.",
  ui_story_5089_50891101_146_dialog_content = "Alguém que é muito diferente de demônios ou espíritos malignos.",
  ui_story_5089_50891101_147_dialog_content = "Levei muito tempo e esforço para finalmente perceber isso, então poderia por favor sair do caminho?",
  ui_story_5089_50891101_148_dialog_content = "Tenho que estar em outro lugar agora.",
  ui_story_5089_50891101_149_dialog_content = "... Pegue ela.",
  ui_story_5089_50891101_150_dialog_content = "Faça do seu jeito, então.",
  ui_story_5089_50891101_151_dialog_content = "<color=#e8d9bb>Jiu se abaixa e pega a lança de um soldado caído. Com um movimento rápido, ela quebra a lâmina e a brande como uma espada.</color>",
  ui_story_5089_50891101_152_dialog_content = "Mover.",
  ui_story_5089_50891101_153_dialog_content = "Meu lugar—",
  ui_story_5089_50891101_154_dialog_content = "Está ao lado do meu mestre!",
  ui_story_5089_50891201_1_dialog_content = "Você já localizou Zhui Hu, PlayerName?",
  ui_story_5089_50891201_2_dialog_content = "Sim! Ela está logo à frente!",
  ui_story_5089_50891201_3_dialog_content = "Hunf.",
  ui_story_5089_50891201_4_dialog_content = "Todas essas pessoas, e ainda assim eram impotentes para te impedir.",
  ui_story_5089_50891201_5_dialog_content = "Parece que eles realmente não se comparam às bestas mecânicas afinal.",
  ui_story_5089_50891201_6_dialog_content = "Se eu me lembro corretamente, não destruímos completamente seu precioso Stinger da última vez?",
  ui_story_5089_50891201_7_dialog_content = "Isso mesmo, e nossos reforços estarão aqui a qualquer segundo. Se eu fosse você, me renderia antes que seja tarde demais.",
  ui_story_5089_50891201_8_dialog_content = "Reforços? Que medonho.",
  ui_story_5089_50891201_9_dialog_content = "Não importa quantos reforços você chame, todos vocês ainda são mortais como qualquer outro. Tem certeza de que quer que eles estejam aqui quando essa montanha desabar?",
  ui_story_5089_50891201_10_dialog_content = "Em vez de perder tempo com essa demonstração fútil de bravura, você deveria começar a evacuar todos imediatamente.",
  ui_story_5089_50891201_11_dialog_content = "Na minha estimativa, uma vez que esta montanha desmorone, todas as terras agrícolas desta área inteira serão completamente dizimadas.",
  ui_story_5089_50891201_12_dialog_content = "Agora vejo por que me foi atribuída uma missão tão bizarra.",
  ui_story_5089_50891201_13_dialog_content = "Este deve ser uma das regiões mais importantes do Reino Ye na produção de grãos. Parece que a colheita deste ano será um pouco escassa.",
  ui_story_5089_50891201_14_dialog_content = "Há rumores de que o Reino de Ji também está interferindo nos suprimentos de alimentos do Reino de Ye. Se algo der errado, uma fome generalizada pode estar logo ali na esquina.",
  ui_story_5089_50891201_15_dialog_content = "Você não é também do Reino Ye? Por que você faria uma coisa dessas?!",
  ui_story_5089_50891201_16_dialog_content = "Achei que tinha deixado bem claro da última vez: qualquer um disposto a apoiar minha arte merece ser chamado de meu mestre.",
  ui_story_5089_50891201_17_dialog_content = "Não deixe que as palavras dela te distraiam, PlayerName.",
  ui_story_5089_50891201_18_dialog_content = "Ela está simplesmente enrolando para... Espere! Onde está o seu Stinger, Zhui Hu?!",
  ui_story_5089_50891201_19_dialog_content = "Hehehe, estou feliz que você finalmente notou, mas já é tarde demais agora.",
  ui_story_5089_50891201_20_dialog_content = "Vê aquela luz ao longe?",
  ui_story_5089_50891201_21_dialog_content = "O ataque do meu Ferrão está totalmente carregado agora, e com o poder da Chama Zhuyin, essa montanha logo será nada mais que um monte de entulho!",
  ui_story_5089_50891201_22_dialog_content = "Tente aproveitar o show, não vai?",
  ui_story_5089_50891201_23_dialog_content = "Você ficou maluco?! Se essa coisa destruir a montanha, você vai morrer junto com todos nós!",
  ui_story_5089_50891201_24_dialog_content = "Fique tranquilo, sou perfeitamente capaz de permanecer vivo.",
  ui_story_5089_50891201_25_dialog_content = "Mais importante, como este é o primeiro ataque em grande escala do meu Stinger, é natural que eu observe seus efeitos em primeira mão.",
  ui_story_5089_50891201_26_dialog_content = "Sejam gratos, vocês dois. Nem todos têm a chance de testemunhar um espetáculo tão maravilhoso.",
  ui_story_5089_50891201_27_dialog_content = "... Ignore-a por agora, PlayerName! Temos que parar o Stinger!",
  ui_story_5089_50891201_28_dialog_content = "Não há como pará-lo agora.",
  ui_story_5089_50891201_29_dialog_content = "<color=#e8d9bb>Bum!!!</color>",
  ui_story_5089_50891201_30_dialog_content = "<color=#e8d9bb>Um feixe cegante de luz rasga a colossal montanha, e incontáveis pedras de todos os tamanhos chovem do céu.</color>",
  ui_story_5089_50891201_31_dialog_content = "Soldados! Escoltem o Mestre Hou - quero dizer, escoltem o rei para a segurança! Uma vez que ele esteja fora de perigo, procurem sobreviventes nos escombros e evacuem-nos!",
  ui_story_5089_50891201_32_dialog_content = "Uma princesa não deveria abandonar seus convidados de maneira tão insensível, sabe.",
  ui_story_5089_50891201_33_dialog_content = "<color=#e8d9bb>Uma besta mecânica surge dos escombros e avança diretamente para Dantang!</color>",
  ui_story_5089_50891201_34_dialog_content = "Cuidado—!",
  ui_story_5089_50891201_35_dialog_content = "Desculpe, mas não posso permitir que você passe. É simplesmente muito perigoso à frente.",
  ui_story_5089_50891201_36_dialog_content = "Argh, estamos discutindo sobre isso há horas, meu bom cara! Por que você não acredita em mim?",
  ui_story_5089_50891201_37_dialog_content = "Minhas divinações claramente sugerem que um evento catastrófico ocorrerá em breve em algum lugar nesta direção.",
  ui_story_5089_50891201_38_dialog_content = "Só podemos conter as marés do caos e prevenir este desastre iminente entregando rapidamente esta espada ao seu legítimo proprietário.",
  ui_story_5089_50891201_39_dialog_content = "Tenho certeza de que nossos soldados podem lidar com esse suposto desastre muito bem. De qualquer forma, você ainda não pode passar.",
  ui_story_5089_50891201_40_dialog_content = "Estou implorando, gentil senhor, apenas deixe-me—",
  ui_story_5089_50891201_41_dialog_content = "<color=#e8d9bb>Bum!!!</color>",
  ui_story_5089_50891201_42_dialog_content = "A-A montanha...! Mas como pode ser isso?!",
  ui_story_5089_50891201_43_dialog_content = "Eu te avisei, não avisei?",
  ui_story_5089_50891201_44_dialog_content = "Não há tempo a perder! Vou me despedir agora!",
  ui_story_5089_50891201_45_dialog_content = "Espere, você—",
  ui_story_5089_50891201_46_dialog_content = "<color=#e8d9bb>De repente, um vento escuro e inquietante parece passar.</color>",
  ui_story_5089_50891201_47_dialog_content = "Hmm? Alguém passou por aqui agora mesmo?",
  ui_story_5089_50891201_48_dialog_content = "Begônias Brilhantes!",
  ui_story_5089_50891201_49_dialog_content = "Ugh!",
  ui_story_5089_50891201_50_dialog_content = "Parece que você ficou mais forte desde o nosso último encontro no mar.",
  ui_story_5089_50891201_51_dialog_content = "Ao contrário de você, nem todos nós nos apegamos às nossas coisas e nos recusamos a seguir em frente.",
  ui_story_5089_50891201_52_dialog_content = "Heh, palavras tão mordazes.",
  ui_story_5089_50891201_53_dialog_content = "Saiam, todos vocês!",
  ui_story_5089_50891201_54_dialog_content = "Estou curioso para ver se você pode ou não sobreviver contra meus chamados \"pertences\"!",
  ui_story_5089_50891201_55_dialog_content = "!",
  ui_story_5089_50891201_56_dialog_content = "(Dantang já está no seu limite. Ela não conseguirá continuar nesse ritmo.)",
  ui_story_5089_50891201_57_dialog_content = "(A montanha ainda não desabou, mas pode acontecer a qualquer segundo... O que devemos fazer?)",
  ui_story_5089_50891201_58_dialog_content = "<color=#e8d9bb>Zuuup...</color>",
  ui_story_5089_50891201_59_dialog_content = "<color=#e8d9bb>Um rápido relâmpago corta a noite densa.</color>",
  ui_story_5089_50891201_60_dialog_content = "Jiu!",
  ui_story_5089_50891201_61_dialog_content = "Você foi muito lento!",
  ui_story_5089_50891201_62_dialog_content = "Por favor, seja razoável, Alteza. Eu vim aqui o mais rápido que pude.",
  ui_story_5089_50891201_63_dialog_content = "Mas mesmo assim, ainda te devo um pedido de desculpas.",
  ui_story_5089_50891201_64_dialog_content = "Perdoe-me por estar tão atrasado.",
  ui_story_5089_50891201_65_dialog_content = "Pedido de desculpas aceito.",
  ui_story_5089_50891201_66_dialog_content = "Hunf, mais um incômodo.",
  ui_story_5089_50891201_67_dialog_content = "Não importa. Duvido que até mesmo os três de vocês possam resistir ao ataque de uma oficina inteira cheia de bestas mecânicas!",
  ui_story_5089_50891201_68_dialog_content = "Roooorrr!!!",
  ui_story_5089_50891201_69_dialog_content = "Eu posso lidar com isso sozinho.",
  ui_story_5089_50891201_70_dialog_content = "Se você deseja se aproximar da Princesa Dantang e PlayerName, vai ter que passar por mim primeiro!",
  ui_story_5089_50891201_71_dialog_content = "(A batalha que se desenrolou diante de nós só poderia ser descrita como \"deslumbrante.\")",
  ui_story_5089_50891201_72_dialog_content = "(Apesar de enfrentar um exército de bestas mecânicas e rochas caindo sem parar, Jiu não se moveu nem um centímetro.)",
  ui_story_5089_50891201_73_dialog_content = "(Armas, galhos, folhas, pedras e até mesmo os destroços de bestas mecânicas abatidas...)",
  ui_story_5089_50891201_74_dialog_content = "(Qualquer objeto à vista de Jiu tinha o potencial de se tornar uma arma poderosa. Ela era imparável, desde que tivesse algo em suas mãos.)",
  ui_story_5089_50891201_75_dialog_content = "Tão rápido quanto o lendário arqueiro que derrubou os Nove Sóis, e tão majestoso quanto os imperadores em seus dragões voadores.",
  ui_story_5089_50891201_76_dialog_content = "Descendo sobre o campo de batalha como uma tempestade se formando, ela separa um mar de soldados como um brilhante raio de relâmpago.",
  ui_story_5089_50891201_77_dialog_content = "Você finalmente descobriu sua verdadeira lâmina, Jiu?",
  ui_story_5089_50891201_78_dialog_content = "Ranger—",
  ui_story_5089_50891201_79_dialog_content = "Não... Isso não pode ser! Como um mero mortal pode comandar tal poder?!",
  ui_story_5089_50891201_80_dialog_content = "Ainda não terminei—!",
  ui_story_5089_50891201_81_dialog_content = "<color=#e8d9bb>Mas Jiu aparece instantaneamente atrás dela antes que ela possa invocar mais bestas de engrenagens.</color>",
  ui_story_5089_50891201_82_dialog_content = "Não se mexa.",
  ui_story_5089_50891201_83_dialog_content = "!",
  ui_story_5089_50891201_84_dialog_content = "Hmph, você acha que acabou só porque me capturou?",
  ui_story_5089_50891201_85_dialog_content = "Enquanto os Cavaleiros do Destino conseguirem recuperar meu ferrão todo-poderoso, ele continuará causando estragos no campo de batalha!",
  ui_story_5089_50891201_86_dialog_content = "E além disso, mesmo com sua força sobrenatural, você nunca poderia esperar impedir que esta montanha desabasse!",
  ui_story_5089_50891201_87_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5089_50891201_88_dialog_content = "<color=#e8d9bb>Sob enorme pressão, as camadas de rocha sob a montanha começam a emitir sons ameaçadores. De repente, enormes rochedos começam a se desprender e a cair no chão.</color>",
  ui_story_5089_50891201_89_dialog_content = "Dantang! Jiu! Não é seguro aqui! Precisamos sair agora mesmo!",
  ui_story_5089_50891201_90_dialog_content = "Parece ser a nossa única escolha. Até agora, os guardas reais deveriam ter evacuado os civis.",
  ui_story_5089_50891201_91_dialog_content = "Discutiremos as coisas uma vez que chegarmos em segurança.",
  ui_story_5089_50891201_92_dialog_content = "... Jiu? Por que você não está recuando?",
  ui_story_5089_50891201_93_dialog_content = "Eu posso pará-lo.",
  ui_story_5089_50891201_94_dialog_content = "O quê?",
  ui_story_5089_50891201_95_dialog_content = "Meu mestre uma vez disse que a técnica da Lâmina Trovejante é capaz de dividir montanhas e separar mares.",
  ui_story_5089_50891201_96_dialog_content = "Mas eu pensei que você disse que seu mestre nunca te ensinou esse movimento?",
  ui_story_5089_50891201_97_dialog_content = "Ele afirmou que não tinha como me ensinar, sim. No início, pensei que ele estava simplesmente inventando desculpas.",
  ui_story_5089_50891201_98_dialog_content = "Mas agora estou começando a ver que ele estava certo o tempo todo.",
  ui_story_5089_50891201_99_dialog_content = "A Lâmina Trovejante não pode ser ensinada porque não é uma técnica de espada real.",
  ui_story_5089_50891201_100_dialog_content = "Em vez disso, é o coração da espada de alguém.",
  ui_story_5089_50891201_101_dialog_content = "Mesmo que seja o caso, você não tem uma espada agora—",
  ui_story_5089_50891201_102_dialog_content = "Amigos! Eu realmente poderia usar alguma assistência agora mesmo!",
  ui_story_5089_50891201_103_dialog_content = "Oh querido, oh meu, como eu supostamente vou desviar de todas essas pedras—",
  ui_story_5089_50891201_104_dialog_content = "Tianxian! Este não é o momento para jogar jogos!",
  ui_story_5089_50891201_105_dialog_content = "Estou no meio de sérias adivinhações agora—Ah! Acho que não podemos ir por esse caminho.",
  ui_story_5089_50891201_106_dialog_content = "Senhorita Jiu, tenho sua espada bem aqui! Pegue!",
  ui_story_5089_50891201_107_dialog_content = "Não no meu turno!",
  ui_story_5089_50891201_108_dialog_content = "!",
  ui_story_5089_50891201_109_dialog_content = "<color=#e8d9bb>Enquanto a espada de Jiu voa pelo ar, vários caranguejos de fogo avançam imediatamente em direção a Dantang.</color>",
  ui_story_5089_50891201_110_dialog_content = "<color=#e8d9bb>Jiu tropeça e sua lâmina cai nas garras de um caranguejo de fogo. No próximo momento, ele se apressa em direção a uma área de escombros extremamente densos.</color>",
  ui_story_5089_50891201_111_dialog_content = "<color=#e8d9bb>Quase instantaneamente, o caranguejo de fogo é esmagado sob as rochas que caem, prendendo a lâmina de Jiu junto com ele.</color>",
  ui_story_5089_50891201_112_dialog_content = "... Eu vou buscá-lo!",
  ui_story_5089_50891201_113_dialog_content = "PlayerName! / PlayerName!",
  ui_story_5089_50891201_114_dialog_content = "Aumento de Força!",
  ui_story_5089_50891201_115_dialog_content = "(Contanto que eu possa prever com precisão onde as pedras vão cair, eu consigo!)",
  ui_story_5089_50891201_116_dialog_content = "Sim!",
  ui_story_5089_50891201_117_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5089_50891201_118_dialog_content = "<color=#e8d9bb>A terra treme violentamente enquanto a montanha, que tem estado instável por muito tempo, finalmente desaba completamente!</color>",
  ui_story_5089_50891201_119_dialog_content = "(Não é bom, não consigo desviar de tantas pedras de uma vez—!)",
  ui_story_5089_50891201_120_dialog_content = "<color=#e8d9bb>Um flash de luz dourada.</color>",
  ui_story_5089_50891201_121_dialog_content = "As pedras... Todas estão sendo desviadas?",
  ui_story_5089_50891201_122_dialog_content = "<color=#e8d9bb>Uma barreira dourada e familiar em forma de lótus paira no céu, bloqueando a cascata de rochedos cadentes.</color>",
  ui_story_5089_50891201_123_dialog_content = "Huh? Algo parece quente no meu bolso... Espere... Não é a folha que Chen'ni me deu?",
  ui_story_5089_50891201_124_dialog_content = "<color=#e8d9bb>Essa não era uma folha comum...</color>",
  ui_story_5089_50891201_125_dialog_content = "<color=#e8d9bb>Mas uma escama de dragão iridescente.</color>",
  ui_story_5089_50891201_126_dialog_content = "... Obrigado, Chen'ni.",
  ui_story_5089_50891201_127_dialog_content = "Com certeza vou comprar muitos petiscos para você na próxima vez que nos encontrarmos!",
  ui_story_5089_50891201_128_dialog_content = "Atenção, Jiu—!",
  ui_story_5089_50891201_129_dialog_content = "Eu agradeço.",
  ui_story_5089_50891201_130_dialog_content = "<color=#e8d9bb>A montanha continua sua descida cataclísmica, como se ameaçasse estilhaçar todo o planeta sob seu peso imensurável.</color>",
  ui_story_5089_50891201_131_dialog_content = "<color=#e8d9bb>De pé em meio à terra tremendo e aos escombros caindo, Jiu fecha os olhos e bloqueia o mundo ao seu redor.</color>",
  ui_story_5089_50891201_132_dialog_content = "Mestre, parece que finalmente entendi o significado de uma espada.",
  ui_story_5089_50891201_133_dialog_content = "\"O universo segue cinquenta leis, mas o Céu guarda quarenta e nove segredos, deixando um único caminho para a humanidade.\"",
  ui_story_5089_50891201_134_dialog_content = "Até os céus volúveis deixam um caminho para nós, então por que você insiste em se restringir assim?",
  ui_story_5089_50891201_135_dialog_content = "Não importa. Se você realmente precisa de um limite de tempo, então...",
  ui_story_5089_50891201_136_dialog_content = "Suas ordens não terminarão até o dia em que você possa balançar sua lâmina sem fazê-lo por gratidão ou vingança. Que tal isso?",
  ui_story_5089_50891201_137_dialog_content = "Eu tenho uma pergunta para você, senhorita Jiu.",
  ui_story_5089_50891201_139_dialog_content = "Por favor, me perdoe, Senhora Xuan Ji. Eu fui um tolo demais para entender sua pergunta naquele momento.",
  ui_story_5089_50891201_140_dialog_content = "Mas, felizmente, tenho muitas pessoas maravilhosas ao meu lado que me guiarão quando eu estiver perdido.",
  ui_story_5089_50891201_141_dialog_content = "Então agora, permita-me dar-lhe a minha resposta.",
  ui_story_5089_50891201_142_dialog_content = "A maior diferença entre nós e os Eclipsitas é que nossos instintos ou ordens não nos controlam totalmente.",
  ui_story_5089_50891201_143_dialog_content = "Se esse fosse o caso, estaríamos desprovidos de significado sem eles.",
  ui_story_5089_50891201_144_dialog_content = "Mesmo que nos percamos, caiamos na escuridão ou nos aprisionemos em uma gaiola de tolice, sempre podemos encontrar pessoas de bondade e calor sem limites.",
  ui_story_5089_50891201_145_dialog_content = "Almas gentis que nos guiarão para fora das sombras opressivas—",
  ui_story_5089_50891201_146_dialog_content = "E para o brilho quente do sol!",
  ui_story_5089_50891201_147_dialog_content = "<color=#e8d9bb>Jiu de repente abre os olhos e balança sua lâmina com uma velocidade quase imperceptível.</color>",
  ui_story_5089_50891201_148_dialog_content = "<color=#e8d9bb>A montanha se desintegra imediatamente depois, enquanto o céu e a terra ressoam em uníssono.</color>",
  ui_story_5089_50891201_149_dialog_content = "<color=#e8d9bb>Uma lâmina que incorpora a máxima ferocidade, mas carrega uma leveza extrema.</color>",
  ui_story_5089_50891201_150_dialog_content = "Não empunho mais minha espada por gratidão ou vingança.",
  ui_story_5089_50891201_151_dialog_content = "<color=#e8d9bb>Ao invés disso, ela o usa como um presente para os muitos amigos que lhe mostraram bondade.</color>",
  ui_story_5089_50891201_152_dialog_content = "<color=#e8d9bb>A onda de choque de seu ataque final varre desde o menor seixo até a montanha mais alta, esmagando tudo que toca em pó.</color>",
  ui_story_5089_50891201_153_dialog_content = "Incrível...",
  ui_story_5089_50891201_154_dialog_content = "<color=#e8d9bb>Olhando para cima novamente, a imensa montanha que estava desabando há um momento atrás se transformou em uma nuvem de poeira.</color>",
  ui_story_5089_50891201_155_dialog_content = "<color=#e8d9bb>A lâmina de gelo corta o ar, deixando o trovão em seu rastro.</color>",
  ui_story_5089_50891201_156_dialog_content = "<color=#e8d9bb>Ecoando pelos topos das montanhas distantes.</color>",
  ui_story_5089_50891201_157_dialog_content = "Irmã Xuan Ji... Esse ataque de agora não vai acontecer de novo, vai?",
  ui_story_5089_50891201_158_dialog_content = "Provavelmente não.",
  ui_story_5089_50891201_159_dialog_content = "Ainda assim, eu nunca esperava que sua lâmina possuísse um poder tão formidável.",
  ui_story_5089_50891201_160_dialog_content = "Mesmo a essa distância, o Stinger foi completamente dividido ao meio... Hmm?",
  ui_story_5089_50891201_161_dialog_content = "Irmã... É essa a Chama Zhuyin?!",
  ui_story_5089_50891201_162_dialog_content = "Como eu sempre digo, um artesão deve ser meticuloso em tudo o que faz.",
  ui_story_5089_50891201_163_dialog_content = "Embora eu deva dizer, essa é a primeira vez que vejo alguém cortar uma chama ao meio.",
  ui_story_5089_50891201_164_dialog_content = "Não é hora de brincar, Irmã Xuan Ji!",
  ui_story_5089_50891201_165_dialog_content = "A Chama Zhuyin é o artefato mais precioso de nossa seita, mas olhe para ela agora! Foi cortada ao meio!",
  ui_story_5089_50891201_166_dialog_content = "Sim, e duas metades perfeitamente simétricas, nada menos.",
  ui_story_5089_50891201_167_dialog_content = "A senhorita Jiu realmente nos fez um grande favor.",
  ui_story_5089_50891201_168_dialog_content = "Do que diabos você está falando?! Como vamos explicar isso para a guilda?!",
  ui_story_5089_50891201_169_dialog_content = "Não se preocupe, eu vou cuidar de tudo.",
  ui_story_5089_50891201_170_dialog_content = "Agora vá e informe os outros abaixo. A Besta Mecânica aqui foi tratada, então peça a eles para ajudar com o resto dos esforços.",
  ui_story_5089_50891201_171_dialog_content = "Afinal, devemos ser os responsáveis por limpar a bagunça de nossos próprios traidores.",
  ui_story_5089_50891201_172_dialog_content = "Entendi.",
  ui_story_5089_50891201_173_dialog_content = "Nngh.",
  ui_story_5089_50891201_174_dialog_content = "Você está bem, Jiu?",
  ui_story_5089_50891201_175_dialog_content = "Estou bem, só me sentindo um pouco esgotado...",
  ui_story_5089_50891201_176_dialog_content = "Espere um minuto... Você está completamente coberto de sangue! Você esteve lutando nessa condição o tempo todo?!",
  ui_story_5089_50891201_177_dialog_content = "Rápido, chame um médico!",
  ui_story_5089_50891201_178_dialog_content = "Agradeço sua preocupação, PlayerName, mas ainda tenho algo que devo fazer.",
  ui_story_5089_50891201_179_dialog_content = "O que você poderia possivelmente ter que fazer depois de tudo isso?!",
  ui_story_5089_50891201_180_dialog_content = "Não fique aí parado, Dantang! Diga algo para ela!",
  ui_story_5089_50891201_181_dialog_content = "Deixe-a em paz, PlayerName.",
  ui_story_5089_50891201_182_dialog_content = "É hora dela colocar tudo para descansar de uma vez por todas.",
  ui_story_5089_50891201_183_dialog_content = "Mas o que ela pode ser... Ahhh agora entendi!",
  ui_story_5089_50891201_184_dialog_content = "Você está certo, é hora de terminar isso.",
  ui_story_5089_50891201_185_dialog_content = "Então você veio.",
  ui_story_5089_50891201_186_dialog_content = "Isso mesmo.",
  ui_story_5089_50891201_187_dialog_content = "Guardas, tragam-me uma espada.",
  ui_story_5089_50891201_188_dialog_content = "Mas Alteza, você ainda está gravemente ferido! Você não deveria estar se movendo agora!",
  ui_story_5089_50891201_189_dialog_content = "Eu disse traga-me uma espada.",
  ui_story_5089_50891201_190_dialog_content = "Eu devo isso a ela, pelo menos.",
  ui_story_5089_50891201_191_dialog_content = "<color=#e8d9bb>Jiu tira sua máscara e a coloca novamente.</color>",
  ui_story_5089_50891201_192_dialog_content = "Vamos resolver isso.",
  ui_story_5089_50891202_1_dialog_content = "<color=#e8d9bb>Clam—</color>",
  ui_story_5089_50891202_2_dialog_content = "<color=#e8d9bb>Em um campo vazio, as duas figuras colidem. Após uma breve troca, a espada do falso rei é golpeada de suas mãos e lançada ao ar.</color>",
  ui_story_5089_50891202_3_dialog_content = "Tosse... Tosse, tosse...",
  ui_story_5089_50891202_4_dialog_content = "Por favor, Alteza! Chega dessa luta!",
  ui_story_5089_50891202_5_dialog_content = "O resultado é claro.",
  ui_story_5089_50891202_6_dialog_content = "Você me superou.",
  ui_story_5089_50891202_7_dialog_content = "...",
  ui_story_5089_50891202_8_dialog_content = "<color=#e8d9bb>Rachadura.</color>",
  ui_story_5089_50891202_9_dialog_content = "<color=#e8d9bb>A máscara de Jiu é cortada em dois pelo ataque do falso rei, e cai no chão.</color>",
  ui_story_5089_50891202_10_dialog_content = "Com isso, nossos rancores estão agora resolvidos.",
  ui_story_5089_50891202_11_dialog_content = "Concordo.",
  ui_story_5089_50891202_12_dialog_content = "Agora vá.",
  ui_story_5089_50891202_13_dialog_content = "<color=#e8d9bb>Jiu guarda sua espada, faz uma leve reverência para Dantang à distância, depois se vira e vai embora.</color>",
  ui_story_5089_50891202_14_dialog_content = "<color=#e8d9bb>Nem uma vez ela olha para trás.</color>",
  ui_story_5089_50891300_1_dialog_content = "<color=#e8d9bb>Palácio Real do Reino Ji</color>",
  ui_story_5089_50891300_2_dialog_content = "Pai! Pai! Ouvi dizer que meu noivo me enviou presentes!",
  ui_story_5089_50891300_3_dialog_content = "De fato, meu filho.",
  ui_story_5089_50891300_4_dialog_content = "Deixe-me ver! Deixe-me ver!",
  ui_story_5089_50891300_5_dialog_content = "Aqui, uma fortuna em ouro.",
  ui_story_5089_50891300_6_dialog_content = "Eh? Mas esses não são os presentes que ofereci a ele antes de ele partir?",
  ui_story_5089_50891300_7_dialog_content = "Ele não gosta de ouro? Eu deveria saber que meu amado herói não se importaria com bugigangas insignificantes como essas.",
  ui_story_5089_50891300_8_dialog_content = "Vou ter que pensar mais nos meus presentes de agora em diante!",
  ui_story_5089_50891300_9_dialog_content = "Esse garoto...",
  ui_story_5089_50891300_10_dialog_content = "Esse homem jovem usou o presente de ouro do príncipe herdeiro para trocar pela comida que compramos anteriormente do Reino Ye. Suas intenções parecem ser bastante claras.",
  ui_story_5089_50891300_11_dialog_content = "Como devemos proceder, Sua Alteza?",
  ui_story_5089_50891300_12_dialog_content = "PlayerName é um amigo do Reino Ji, cuja honra posso garantir pessoalmente. Ainda tenho que retribuir a ele por salvar Haojin, também.",
  ui_story_5089_50891300_13_dialog_content = "Se ele deseja se envolver nestes assuntos, eu respeitarei sua decisão.",
  ui_story_5089_50891300_14_dialog_content = "No entanto, não serei tão generoso se o Reino buscar conflito conosco novamente no futuro.",
  ui_story_5089_50891300_15_dialog_content = "Sim, meu senhor.",
  ui_story_5089_50891300_16_dialog_content = "<color=#e8d9bb>Fwoosh—</color>",
  ui_story_5089_50891300_17_dialog_content = "<color=#e8d9bb>No cais movimentado, outro grande navio içar suas velas e parte.</color>",
  ui_story_5089_50891300_18_dialog_content = "Então, Jiu nunca volta depois disso?",
  ui_story_5089_50891300_19_dialog_content = "Sim. Considerando que eu concedi a ela a liberdade voluntariamente, é natural que eu respeite a escolha dela.",
  ui_story_5089_50891300_20_dialog_content = "Mesmo que ela nunca volte, sempre me lembrarei de como fui sortudo por ter uma amiga tão próxima.",
  ui_story_5089_50891300_21_dialog_content = "Mas e você, PlayerName? O que vai fazer em seguida?",
  ui_story_5089_50891300_22_dialog_content = "Huh? Estamos em um navio a caminho do Reino de Ji agora, não estamos?",
  ui_story_5089_50891300_23_dialog_content = "Você é quem disse que os Fate Riders são nosso inimigo comum. Nosso próximo objetivo é convencer os Reinos Ji e Ye a deixarem suas diferenças de lado por enquanto.",
  ui_story_5089_50891300_24_dialog_content = "Também preciso devolver todo esse ouro ao príncipe herdeiro. Nunca tive a chance de agradecer a Houfeng... Quero dizer, o Rei de Ye... Por me ajudar a cobrir a diferença.",
  ui_story_5089_50891300_25_dialog_content = "Falando nisso, tem certeza de que está tudo bem em deixá-lo continuar servindo como rei?",
  ui_story_5089_50891300_26_dialog_content = "Infelizmente, não temos outra escolha.",
  ui_story_5089_50891300_27_dialog_content = "Meu verdadeiro tio é mentalmente incapaz de governar, e minha irmã mais velha ainda é muito jovem para assumir as responsabilidades do trono. Como está, o Reino Ye não pode se dar ao luxo de nem a menor perturbação.",
  ui_story_5089_50891300_28_dialog_content = "Embora o Mestre Houfeng seja um tanto arrogante, ele realmente tem os melhores interesses do Reino Ye em seu coração.",
  ui_story_5089_50891300_29_dialog_content = "Além disso, com a Ministra Armilla e a Guilda dos Artesãos comandando maior autoridade do que antes, ele não poderá agir com impunidade por enquanto.",
  ui_story_5089_50891300_30_dialog_content = "Mas esse não era o ponto da minha pergunta. Eu estava me referindo mais aos seus planos futuros.",
  ui_story_5089_50891300_31_dialog_content = "Bem, agora que estive em Haojin e na cidade de Jingliang, quero ver mais de Longzhou.",
  ui_story_5089_50891300_32_dialog_content = "Mas depois de ficar tanto tempo longe de Astra, talvez eu devesse fazer uma viagem de volta primeiro? Eu preferiria não fazer Vice e Carleen se preocuparem mais do que eu preciso.",
  ui_story_5089_50891300_33_dialog_content = "O que você acha, Dantang?",
  ui_story_5089_50891300_34_dialog_content = "Certamente você está brincando?",
  ui_story_5089_50891300_35_dialog_content = "Você não é nem um pássaro em uma gaiola nem uma fera em um canil. Não é meu lugar ditar seu futuro.",
  ui_story_5089_50891300_36_dialog_content = "Então, se eu não sou um ou outro, o que exatamente eu sou aos seus olhos, Dantang?",
  ui_story_5089_50891300_37_dialog_content = "Se eu tivesse que dizer...",
  ui_story_5089_50891300_38_dialog_content = "<color=#e8d9bb>Sob o sol da manhã, ela ri enquanto olha para cima, seus olhos sérios transbordando com uma luz radiante.</color>",
  ui_story_5089_50891300_39_dialog_content = "Você é o Peng para o meu Kun.",
  ui_story_5089_50891300_40_dialog_content = "Um grande e majestoso pássaro que eventualmente voará pelos nove céus.",
  ui_story_5089_50891300_41_dialog_content = "Isso é um pouco demais, você não acha?",
  ui_story_5089_50891300_42_dialog_content = "Não mesmo.",
  ui_story_5089_50891300_43_dialog_content = "Ei, olhe lá fora! Alguém está perseguindo nosso navio!",
  ui_story_5089_50891300_44_dialog_content = "Você ficou muito tempo no sol? Como alguém poderia—Espere, você está certo! A Donzela do Dragão está acima; realmente tem alguém correndo na água!",
  ui_story_5089_50891300_45_dialog_content = "Sobre o que vocês dois estão gritando—Uau!",
  ui_story_5089_50891300_46_dialog_content = "É aquele Jiu?!",
  ui_story_5089_50891300_47_dialog_content = "<color=#e8d9bb>O navio navegou longe da costa, mas uma figura caminha sobre a água, correndo em direção a ele a uma velocidade incrível.</color>",
  ui_story_5089_50891300_48_dialog_content = "<color=#e8d9bb>À medida que se aproxima do navio, ela faz um salto ousado e aterrissa graciosamente no convés.</color>",
  ui_story_5089_50891300_49_dialog_content = "<color=#e8d9bb>De pé diante de nós, fresca como a brisa do oceano, é ninguém menos que a própria Jiu.</color>",
  ui_story_5089_50891300_50_dialog_content = "Alteza, não acha que foi imprudente partir para outro reino sem o seu leal guarda?",
  ui_story_5089_50891300_51_dialog_content = "Então, você decidiu?",
  ui_story_5089_50891300_52_dialog_content = "Se você escolheu continuar me seguindo, saiba que não vou tolerar o mesmo erro duas vezes, Jiu.",
  ui_story_5089_50891300_53_dialog_content = "Minha decisão está tomada, Sua Alteza.",
  ui_story_5089_50891300_54_dialog_content = "Em minha honra, não vou decepcioná-lo.",
  ui_story_5089_50891300_55_dialog_content = "Bom. Agora vamos.",
  ui_story_5089_50891300_56_dialog_content = "Os Cavaleiros do Destino ainda são uma ameaça para todo o Império Zhao. Uma vez que nossos negócios no Reino Ji estejam concluídos, viajaremos para os outros reinos vassalos para continuar nossa investigação.",
  ui_story_5089_50891300_57_dialog_content = "Mas com o império em tal perigo, não seria melhor enviar outros aos reinos vassalos em seu lugar?",
  ui_story_5089_50891300_58_dialog_content = "Viajar por toda a terra em todas as direções concebíveis é uma oportunidade concedida a muito poucas pessoas.",
  ui_story_5089_50891300_59_dialog_content = "Sempre aspirei viajar assim. Como eu poderia deixar uma pequena crise me impedir de alcançar meu sonho de vida inteira?",
  ui_story_5089_50891300_60_dialog_content = "Além disso, pássaros e peixes são livres para percorrer o mundo.",
  ui_story_5089_50891300_61_dialog_content = "Se eu não ousar explorar todos os cantos do mundo, como posso esperar encontrar um companheiro tão extraordinário quanto eles para voar ao meu lado?",
  ui_story_5089_50891300_62_dialog_content = "Ainda temos uma longa jornada à nossa frente.",
  ui_story_5089_50891300_63_dialog_content = "<color=#e8d9bb>Em uma casa de chá em algum lugar</color>",
  ui_story_5089_50891300_64_dialog_content = "... E assim, a Princesa Zhuohua e o Enviado de Astra partiram em suas respectivas jornadas.",
  ui_story_5089_50891300_65_dialog_content = "Os ventos cambiantes e as nuvens rolando acima deles finalmente diminuíram, pelo menos por enquanto.",
  ui_story_5089_50891300_66_dialog_content = "Quanto a mim, esta é a oportunidade perfeita para pedir algumas moedas de sobra em troca da minha maravilhosa história. Afinal, meus pobres passarinhos também precisam comer!",
  ui_story_5089_50891300_67_dialog_content = "O que é isso? Você acha que estou inventando tudo? Nossa, que grave mal-entendido!",
  ui_story_5089_50891300_68_dialog_content = "Cada palavra do que eu acabei de dizer é verdade, e este oceano é a prova disso!",
  ui_story_5089_50891300_69_dialog_content = "Gravado nas ondas do oceano, um navio cheio de begônias brilhantes navega adiante.",
  ui_story_5089_50891300_70_dialog_content = "Na véspera do Festival da Primavera, ocorre uma dança entre peixes e dragões, e o poder da tempestade acalma o mar.",
  ui_story_5089_50891300_71_dialog_content = "Uma espada trovejante se torna uma lâmina de puro gelo, e transforma os demônios em pó.",
  ui_story_5089_50891300_72_dialog_content = "O pássaro engaiolado se liberta, agitando os céus com suas asas enquanto encontra alegria na vastidão do mundo.",
  ui_story_5089_50891300_73_dialog_content = "Assim, o Conto da Begônia à Deriva chega ao fim.",
  ui_story_5089_50891300_74_dialog_content = "Naturalmente, a jornada do herói ainda está longe de terminar. Se você gostaria de ouvir o resto dela—",
  ui_story_5089_50891300_75_dialog_content = "<color=#e8d9bb>Clac!</color>",
  ui_story_5089_50891300_76_dialog_content = "<color=#e8d9bb>Com um clique do martelo de madeira, o livro que havia sido virado até o fim fecha lentamente, a luz da vela desaparece e a cortina cai.</color>",
  ui_story_5089_50891300_77_dialog_content = "O que vem a seguir... Bem, talvez estejamos em extremos opostos do mar, nos encontraremos novamente, desde que o destino permita.",
  ui_story_5089_50891400_1_dialog_content = "Você já tomou sua decisão?",
  ui_story_5089_50891400_2_dialog_content = "Avançar significa dizer adeus a todos que você conhece agora.",
  ui_story_5089_50891400_3_dialog_content = "Todas as conexões que você trabalhou tanto para construir vão desaparecer.",
  ui_story_5089_50891400_4_dialog_content = "Mas mesmo assim, você ainda viajaria até os fins do mundo por ela, não é?",
  ui_story_5089_50891400_5_option_content = "Sim.",
  ui_story_5089_50891400_6_option_content = "Sim, eu decidi.",
  ui_story_5089_50891400_7_dialog_content = "...",
  ui_story_5089_50891400_8_dialog_content = "Suas viagens em Longzhou parecem ter te tornado mais decisivo.",
  ui_story_5089_50891400_9_dialog_content = "Então, vamos dizer nossos adeus.",
  ui_story_5089_50891400_10_dialog_content = "No último dos últimos, com todos os meus amigos...",
  ui_story_5089_50891400_11_dialog_content = "Uma última viagem ao redor de Astra, certo?",
  ui_story_5089_50891400_12_dialog_content = "Assim como no início, vamos partir com estilo!",
  ui_story_5089_50891400_13_dialog_content = "Você veio todo esse caminho apenas para dizer adeus?",
  ui_story_5089_50891400_14_dialog_content = "Ah, eu sou bom nisso, você sabe. Mas você vai voltar algum dia, certo?",
  ui_story_5089_50891400_15_option_content = "Também não tenho certeza.",
  ui_story_5089_50891400_16_option_content = "Hum...",
  ui_story_5089_50891400_17_dialog_content = "Suspiro, venha aqui.",
  ui_story_5089_50891400_18_dialog_content = "Aqui. Quando os caras se abraçam assim, eles não precisam dizer mais nada.",
  ui_story_5089_50891400_19_dialog_content = "Sei que você tem suas razões, e eu te apoio.",
  ui_story_5089_50891400_20_dialog_content = "E... Obrigado. Você sempre foi de grande ajuda para nós, e para mim.",
  ui_story_5089_50891400_21_dialog_content = "Se você algum dia voltar, lembre-se de nos dar um grito.",
  ui_story_5089_50891400_22_dialog_content = "E se as coisas não derem certo, não esqueça que você sempre terá um lugar aqui.",
  ui_story_5089_50891400_23_dialog_content = "Valeu, com certeza vou me lembrar.",
  ui_story_5089_50891400_24_dialog_content = "Argh, lá vou eu, ficando com os olhos cheios de lágrimas... Isso é culpa sua.",
  ui_story_5089_50891400_25_dialog_content = "Agora vá dizer seus adeus para Eve e os outros.",
  ui_story_5089_50891400_26_dialog_content = "Adeus, Sinsa.",
  ui_story_5089_50891400_27_dialog_content = "... Tchau, PlayerName.",
  ui_story_5089_50891400_28_dialog_content = "O que? Assim mesmo... e você vai embora e nunca mais volta?!",
  ui_story_5089_50891400_29_dialog_content = "Ah, n-não é necessariamente assim, mas não tenho certeza de quando voltarei...",
  ui_story_5089_50891400_30_dialog_content = "O-Oh, Eve, não chore. Se Sinsa ver isso, vou estar em grandes apuros!",
  ui_story_5089_50891400_31_dialog_content = "Mas...",
  ui_story_5089_50891400_32_dialog_content = "Sei que nos encontraremos novamente algum dia!",
  ui_story_5089_50891400_33_dialog_content = "E quando eu finalmente encontrar meu caminho de volta aqui...",
  ui_story_5089_50891400_34_dialog_content = "Terei muitas novas histórias para compartilhar com você, histórias que você nunca poderia ver aqui em Astra!",
  ui_story_5089_50891400_35_dialog_content = "Você promete?",
  ui_story_5089_50891400_36_dialog_content = "Claro que não!",
  ui_story_5089_50891400_37_dialog_content = "Promessa de mindinho?",
  ui_story_5089_50891400_38_dialog_content = "Com certeza!",
  ui_story_5089_50891400_39_dialog_content = "Bom! Vamos, eu te levarei até os outros para que você possa se despedir deles.",
  ui_story_5089_50891400_40_dialog_content = "Sentimos sua falta o tempo todo, sabe?",
  ui_story_5089_50891400_41_dialog_content = "Ah, e lembra daquela senhora que você nos apresentou antes? Você ainda não a viu por aqui!",
  ui_story_5089_50891400_42_dialog_content = "E tem também a Senhorita Attar! Ela...",
  ui_story_5089_50891400_43_dialog_content = "Eve?",
  ui_story_5089_50891400_44_dialog_content = "Peço desculpas. Eu sei que prometi que não iria chorar mais.",
  ui_story_5089_50891400_45_dialog_content = "Mas... De repente me lembrei de tudo o que passamos juntos...",
  ui_story_5089_50891400_46_dialog_content = "Eu sei o que você quer dizer. Já faz um tempo, hein?",
  ui_story_5089_50891400_47_dialog_content = "Antes que percebêssemos, fizemos muitos novos amigos. Eles também cresceram de tantas maneiras.",
  ui_story_5089_50891400_48_dialog_content = "Este lugar sempre estará perto e querido do meu coração.",
  ui_story_5089_50891400_49_dialog_content = "Assim como a panela quente em Longzhou.",
  ui_story_5089_50891400_50_dialog_content = "É por isso que acho que você vai ficar bem, Eve.",
  ui_story_5089_50891400_51_dialog_content = "Porque você ainda terá todos ao seu lado.",
  ui_story_5089_50891400_52_dialog_content = "A-Tudo bem.",
  ui_story_5089_50891400_54_dialog_content = "Vamos lá, vamos dizer adeus.",
  ui_story_5089_50891400_55_dialog_content = "Fui informado sobre o assunto.",
  ui_story_5089_50891400_56_dialog_content = "Já que envolve Vice, não vou te impedir.",
  ui_story_5089_50891400_57_dialog_content = "Também aprovei o pedido de folga de Vice. Se precisar de mais alguma coisa, não hesite em me informar.",
  ui_story_5089_50891400_58_dialog_content = "Está tudo bem, isso é mais do que suficiente. Obrigado a você e a Reinhardt por toda a sua ajuda!",
  ui_story_5089_50891400_59_dialog_content = "Nossa jornada vai nos levar profundamente em território desconhecido.",
  ui_story_5089_50891400_60_dialog_content = "Não é algo que pode ser resolvido apenas encontrando mais pessoas.",
  ui_story_5089_50891400_61_dialog_content = "Entendo, mas ainda gostaria de ajudar se possível.",
  ui_story_5089_50891400_62_dialog_content = "As coisas ficarão um pouco solitárias sem você, tenho certeza.",
  ui_story_5089_50891400_63_dialog_content = "Eu sei que Barton vai sentir isso quando estiver em casa.",
  ui_story_5089_50891400_64_dialog_content = "Por que não deixar Gronru levá-lo para brincar mais? Não é saudável para ele ficar em casa quando não há batalhas para lutar.",
  ui_story_5089_50891400_65_dialog_content = "Ei, eu só estou brincando.",
  ui_story_5089_50891400_66_dialog_content = "Seu antigo comandante está observando-o de perto agora, então ele terá muito o que fazer.",
  ui_story_5089_50891400_67_dialog_content = "Comandante Hiiro contando piadas... Não acredito que vivi para ver este dia.",
  ui_story_5089_50891400_68_dialog_content = "Hmm. Talvez seja apenas o tipo de mudança que você provoca nas outras pessoas.",
  ui_story_5089_50891400_69_dialog_content = "Você influenciou grandemente o Grande Marechal, e eu não sou exceção.",
  ui_story_5089_50891400_70_dialog_content = "...",
  ui_story_5089_50891400_71_dialog_content = "Você se cuide.",
  ui_story_5089_50891400_72_dialog_content = "Pode deixar!",
  ui_story_5089_50891400_73_dialog_content = "Ei! Por aqui!",
  ui_story_5089_50891400_74_dialog_content = "Aqui, aqui, PlayerName!",
  ui_story_5089_50891400_75_dialog_content = "Estou aqui para dizer tchau tchau.",
  ui_story_5089_50891400_76_dialog_content = "O Colossus sempre decolou tão rápido assim?",
  ui_story_5089_50891400_77_dialog_content = "Ei—PlayerName!",
  ui_story_5089_50891400_78_dialog_content = "Cuide-se bem na sua jornada, ouviu? Lembre-se de comer três refeições completas por dia, e não se atrase para nenhuma delas!",
  ui_story_5089_50891400_79_dialog_content = "E é melhor você trazer Vice de volta para casa seguro e são também!",
  ui_story_5089_50891400_80_dialog_content = "Eu vou—Apenas espere!",
  ui_story_5089_50891400_81_dialog_content = "Prometo que vou trazê-la de volta em segurança!",
  ui_story_5089_50891400_82_dialog_content = "Ah, moleque... Acha que pode simplesmente voar com um dos melhores soldados de Illumina quando quiser...",
  ui_story_5089_50891400_83_dialog_content = "Você não vai dizer adeus?",
  ui_story_5089_50891400_84_dialog_content = "Não.",
  ui_story_5089_50891400_85_dialog_content = "Ele é um pássaro livre. Não quero adicionar fardos desnecessários sobre ele.",
  ui_story_5089_50891400_86_dialog_content = "O que acontece a seguir é para PlayerName decidir. Afinal, é a história dele.",
  ui_story_5089_50891400_87_dialog_content = "Como seu amigo, tudo que posso fazer é oferecer-lhe meus melhores votos enquanto ele decola.",
  ui_story_5089_50891400_88_dialog_content = "... Vamos lá. Temos muitas decisões para tomar por nós mesmos, não temos?",
  ui_story_5089_50891400_89_dialog_content = "Até a próxima...?",
  ui_story_5089_50891400_90_dialog_content = "...",
  ui_story_5089_50891400_91_dialog_content = "Mas ninguém está aqui agora... Senhora Victoria, Paloma, Pasolo... Nenhum deles.",
  ui_story_5089_50891400_92_dialog_content = "É, mas você ainda tá aqui, certo?",
  ui_story_5089_50891400_93_dialog_content = "Pelo menos, posso te ver uma última vez antes de ir.",
  ui_story_5089_50891400_94_dialog_content = "E isso é tudo que eu poderia pedir.",
  ui_story_5089_50891400_95_dialog_content = "Sentiríamos como se algo estivesse faltando se não tivéssemos a oportunidade de nos despedir um do outro.",
  ui_story_5089_50891400_96_dialog_content = "?!",
  ui_story_5089_50891400_97_dialog_content = "Embora seja uma pena que eu não consiga ver Paloma...",
  ui_story_5089_50891400_98_dialog_content = "Talvez a Victoria me ajude a entregar a mensagem, ela sempre sabe de tudo, certo?",
  ui_story_5089_50891400_99_dialog_content = "E se isso não funcionar—",
  ui_story_5089_50891400_100_dialog_content = "Ei—! Mestre Eremita—!",
  ui_story_5089_50891400_101_dialog_content = "Por favor, certifique-se de que Victoria e os outros recebam minha mensagem—!",
  ui_story_5089_50891400_102_dialog_content = "... Com quem você está falando?",
  ui_story_5089_50891400_103_dialog_content = "Heheh... Alguém que entende.",
  ui_story_5089_50891400_104_dialog_content = "...",
  ui_story_5089_50891400_105_dialog_content = "Eu...",
  ui_story_5089_50891400_106_dialog_content = "Espero que você retorne em segurança algum dia.",
  ui_story_5089_50891400_107_dialog_content = "Claro que vou!",
  ui_story_5089_50891400_108_dialog_content = "Adeus!",
  ui_story_5089_50891400_109_dialog_content = "Adeus.",
  ui_story_5089_50891400_110_dialog_content = "... Pronto. Isso deve ser o último.",
  ui_story_5089_50891400_111_dialog_content = "Esses são todos os suprimentos para sua jornada da Guilda de Umbraton e... os Lovegators.",
  ui_story_5089_50891400_112_dialog_content = "Não esperava receber tantas coisas grátis apenas por vir para Umbraton...",
  ui_story_5089_50891400_113_dialog_content = "Tenho um pouco de vergonha de aceitar.",
  ui_story_5089_50891400_114_dialog_content = "Você sempre foi um amigo de Umbraton, e para nós também.",
  ui_story_5089_50891400_115_dialog_content = "Considere isso um símbolo dessa amizade.",
  ui_story_5089_50891400_116_dialog_content = "Uau! V-você me assustou!",
  ui_story_5089_50891400_117_dialog_content = "Hahaha! Não se esqueça, o lugar para onde você está indo fica muito além do olhar atento das sombras de Umbraton.",
  ui_story_5089_50891400_118_dialog_content = "Seja cauteloso em tudo que você faz.",
  ui_story_5089_50891400_119_dialog_content = "Pode deixar.",
  ui_story_5089_50891400_120_dialog_content = "... Deixo o resto com você, Bethel.",
  ui_story_5089_50891400_121_dialog_content = "...",
  ui_story_5089_50891400_122_dialog_content = "Luke, Smokey, Genevieve e Naroxel estão todos te esperando lá atrás.",
  ui_story_5089_50891400_123_dialog_content = "Como uma das celebridades mais famosas de Astra, todos querem se despedir pessoalmente.",
  ui_story_5089_50891400_124_dialog_content = "Entendo...",
  ui_story_5089_50891400_125_dialog_content = "Acho que isso significa que devo oferecer a eles uma despedida adequada.",
  ui_story_5089_50891400_126_dialog_content = "E você também, Bethel.",
  ui_story_5089_50891400_127_dialog_content = "...!",
  ui_story_5089_50891400_128_dialog_content = "... Você realmente vai ficar fora por tanto tempo?",
  ui_story_5089_50891400_129_dialog_content = "Não posso dizer com certeza. Na verdade, nem sei se conseguirei voltar depois.",
  ui_story_5089_50891400_130_dialog_content = "Mas eu sei que nunca vou esquecer nenhuma das ótimas pessoas que conheci aqui.",
  ui_story_5089_50891400_131_dialog_content = "Então, se houver até mesmo uma chance de eu voltar, farei tudo o que puder para que isso aconteça.",
  ui_story_5089_50891400_132_dialog_content = "PlayerName...",
  ui_story_5089_50891400_133_dialog_content = "Por favor, cuide-se.",
  ui_story_5089_50891400_134_dialog_content = "E se eu encontrar algum romance interessante pelo caminho, com certeza trarei para você também.",
  ui_story_5089_50891400_135_dialog_content = "Quando esse dia chegar, podemos passar algum tempo lendo no café com todos!",
  ui_story_5089_50891400_136_dialog_content = "Mas por enquanto...",
  ui_story_5089_50891400_137_dialog_content = "Adeus, Bethel.",
  ui_story_5089_50891400_138_dialog_content = "Encontrei ele. Ele está ali.",
  ui_story_5089_50891400_139_dialog_content = "PlayerName!",
  ui_story_5089_50891400_140_dialog_content = "Adeus!",
  ui_story_5089_50891400_141_dialog_content = "Ah...",
  ui_story_5089_50891400_142_dialog_content = "Adeus—",
  ui_story_5089_50891400_143_dialog_content = "Espero que você sempre tenha música e esperança para guiar seu caminho....",
  ui_story_5089_50891400_144_dialog_content = "... Adeus.",
  ui_story_5089_50891400_145_dialog_content = "Hã? Você quer vir junto também?",
  ui_story_5089_50891400_146_dialog_content = "Não é que eu queira ir com você, propriamente dito...",
  ui_story_5089_50891400_147_dialog_content = "Mas explorar uma terra desconhecida de fantasia parece um tempo interessante.",
  ui_story_5089_50891400_148_dialog_content = "Até mesmo Antony está empolgado com a perspectiva, então não é normal eu estar um pouco interessado?",
  ui_story_5089_50891400_149_dialog_content = "Você deve dizer o que está em sua mente, ou pode se arrepender mais tarde.",
  ui_story_5089_50891400_150_dialog_content = "...",
  ui_story_5089_50891400_151_dialog_content = "Como o Phospherus de Astra, permitir que você embarque em uma jornada tão perigosa é preocupante, para dizer o mínimo.",
  ui_story_5089_50891400_152_dialog_content = "Ah? Então que tal isso?",
  ui_story_5089_50891400_153_dialog_content = "Vou encontrar mais quatro lutadores, e todos nós estaremos ao seu comando!",
  ui_story_5089_50891400_154_dialog_content = "Teremos todos os elementos cobertos, e nada ficará no nosso caminho...",
  ui_story_5089_50891400_155_dialog_content = "Mesmo assim, eu vi o seu futuro.",
  ui_story_5089_50891400_156_dialog_content = "E naquele lugar distante, você ainda possui um brilho infinito.",
  ui_story_5089_50891400_157_dialog_content = "Talvez seja aí onde sua verdadeira batalha reside.",
  ui_story_5089_50891400_158_dialog_content = "Um lugar cheio de fantasia e realidade, onde você lutará para o melhoramento de todos.",
  ui_story_5089_50891400_159_dialog_content = "Esse é o seu próprio caminho.",
  ui_story_5089_50891400_160_dialog_content = "E embora nossos corações estejam cheios de preocupação por você, tudo o que podemos fazer é oferecer nossas bênçãos.",
  ui_story_5089_50891400_161_dialog_content = "Obrigado. Seus votos de bem-estar me tranquilizam mais do que você imagina.",
  ui_story_5089_50891400_162_dialog_content = "Hã? Então não haverá mais chances para nós subirmos de nível juntos? Eu realmente esperava que pudéssemos ter mais aventuras e derrubar alguns Fantasmas a mais.",
  ui_story_5089_50891400_163_dialog_content = "Sinceramente, é tão chato por aqui.",
  ui_story_5089_50891400_164_dialog_content = "Você está aproveitando seu tempo aqui, hein, Freya?",
  ui_story_5089_50891400_165_dialog_content = "Acho que essa é uma maneira de colocar isso...",
  ui_story_5089_50891400_166_dialog_content = "Visitei minha antiga cidade natal, certifiquei-me de que o \"tesouro\" ainda estava seguro e comprei algumas roupas novas...",
  ui_story_5089_50891400_167_dialog_content = "É como se eu tivesse sido tocado no ombro pelo próprio destino.",
  ui_story_5089_50891400_168_dialog_content = "Mas isso não é quase o suficiente para me satisfazer, você sabe!",
  ui_story_5089_50891400_169_dialog_content = "E você tinha que aparecer com uma nova e emocionante aventura, só para nos dizer que não podemos ir com você!",
  ui_story_5089_50891400_170_dialog_content = "Meus punhos estão tão ansiosos para lutar que chega a doer...",
  ui_story_5089_50891400_171_dialog_content = "Então que tal trocarmos alguns socos antes de você ir, Navegador?",
  ui_story_5089_50891400_172_dialog_content = "Afinal, o meu sonho é—",
  ui_story_5089_50891400_173_dialog_content = "Adeus, Freya.",
  ui_story_5089_50891400_174_dialog_content = "...",
  ui_story_5089_50891400_175_dialog_content = "Vendo você sorrir tão feliz e genuinamente assim...",
  ui_story_5089_50891400_176_dialog_content = "Isso realmente também acalma meu coração.",
  ui_story_5089_50891400_177_dialog_content = "... Certifique-se de se despedir deles adequadamente, okay?",
  ui_story_5089_50891400_178_dialog_content = "Pode deixar.",
  ui_story_5089_50891400_179_dialog_content = "Adeus, Queen Bethlehem.",
  ui_story_5089_50891400_180_dialog_content = "Adeus.",
  ui_story_5089_50891400_181_dialog_content = "Os que você deseja ver estão fora do palácio.",
  ui_story_5089_50891400_182_dialog_content = "Vá encontrá-los, PlayerName.",
  ui_story_5089_50891400_183_dialog_content = "Adeus, Zarya.",
  ui_story_5089_50891400_184_dialog_content = "Eu ainda quero ir.",
  ui_story_5089_50891400_185_dialog_content = "Hã?",
  ui_story_5089_50891400_186_dialog_content = "N-Nada.",
  ui_story_5089_50891400_187_dialog_content = "Até mais...",
  ui_story_5089_50891400_188_dialog_content = "Oh céus. Aqui, deixe-me compartilhar um pouco da minha sabedoria de idoso com você.",
  ui_story_5089_50891400_189_dialog_content = "Ei!",
  ui_story_5089_50891400_190_dialog_content = "Esta é uma oportunidade rara, sabe? Você só pode usar o cartão da jovem garota perto do Queen e do Deus da Montanha.",
  ui_story_5089_50891400_191_dialog_content = "Ei!",
  ui_story_5089_50891400_192_dialog_content = "... Então esta é a parada final.",
  ui_story_5089_50891400_193_dialog_content = "PlayerName... Melhor você voltar.",
  ui_story_5089_50891400_194_dialog_content = "Farei o meu melhor, Leyn. Você poderia me ajudar a transmitir meus adeus aos outros?",
  ui_story_5089_50891400_195_dialog_content = "Bem, parece que é hora de deixar os personagens principais tomarem o palco.",
  ui_story_5089_50891400_196_dialog_content = "Vamos, todos.",
  ui_story_5089_50891400_197_dialog_content = "...",
  ui_story_5089_50891400_198_dialog_content = "...",
  ui_story_5089_50891400_199_dialog_content = "Qual é o problema? Você não veio para dizer adeus?",
  ui_story_5089_50891400_200_dialog_content = "Eu fiz, mas por algum motivo, não consigo encontrar as palavras certas para dizer...",
  ui_story_5089_50891400_201_dialog_content = "Então deixe-me falar!",
  ui_story_5089_50891400_202_dialog_content = "Hã? Maya?",
  ui_story_5089_50891400_203_dialog_content = "Espere um minuto... Aquiles?! V-Você não é a Maya!",
  ui_story_5089_50891400_204_dialog_content = "Ela está falando atrás de mim—",
  ui_story_5089_50891400_205_dialog_content = "Cheguei assim que soube que você estava partindo, PlayerName!",
  ui_story_5089_50891400_206_dialog_content = "Mas então eu me perdi... Felizmente, esse grandão foi gentil o suficiente para me trazer até aqui!",
  ui_story_5089_50891400_207_dialog_content = "Isso explica por que não consegui te encontrar mais cedo...",
  ui_story_5089_50891400_208_dialog_content = "Se Jeno e Elvis soubessem que você está correndo assim, eles ficariam preocupados doentes.",
  ui_story_5089_50891400_209_dialog_content = "Aham.",
  ui_story_5089_50891400_210_dialog_content = "E-Eu quero dizer Elvis ficaria triste.",
  ui_story_5089_50891400_211_dialog_content = "Isso é Laird Elvis para você, senhor!",
  ui_story_5089_50891400_212_dialog_content = "Cof, cof.",
  ui_story_5089_50891400_213_dialog_content = "Então você já tomou sua decisão?",
  ui_story_5089_50891400_214_dialog_content = "Porque uma vez que você sair, não poderemos ajudá-lo.",
  ui_story_5089_50891400_215_dialog_content = "Eu sei, mas não posso sempre confiar em todos.",
  ui_story_5089_50891400_216_dialog_content = "...",
  ui_story_5089_50891400_217_dialog_content = "Todos vocês receberam uma chance para um novo futuro...",
  ui_story_5089_50891400_218_dialog_content = "Espero que você possa passar o resto de seus dias exatamente da maneira que deseja passá-los.",
  ui_story_5089_50891400_219_dialog_content = "Entendo... E se alguns de nós quiserem passar esses dias ao seu lado?",
  ui_story_5089_50891400_220_dialog_content = "Hã? Quê?",
  ui_story_5089_50891400_221_dialog_content = "Se você nos confiar o direito de escolher, então deve valorizar cada uma de nossas opiniões.",
  ui_story_5089_50891400_222_dialog_content = "Alguns de nós podem estar relutantes em te deixar.",
  ui_story_5089_50891400_223_dialog_content = "Alguns de nós podem não querer deixar ir as aventuras que compartilhamos com você.",
  ui_story_5089_50891400_224_dialog_content = "Aqueles de nós que sentem dessa maneira podem querer continuar lutando ao seu lado.",
  ui_story_5089_50891400_225_dialog_content = "E pode haver o suficiente de nós para preencher todos os quartos a bordo do seu Colossus.",
  ui_story_5089_50891400_226_dialog_content = "Y-Você realmente acha isso?",
  ui_story_5089_50891400_227_dialog_content = "Então eu quero ir também!",
  ui_story_5089_50891400_228_dialog_content = "E se não houver espaço suficiente para mim, eu posso simplesmente fazer meu ancestral me levar!",
  ui_story_5089_50891400_229_dialog_content = "Mas e o aquário?",
  ui_story_5089_50891400_230_dialog_content = "... Ah, não!!!",
  ui_story_5089_50891400_231_dialog_content = "Estava tão preocupado com PlayerName e sua viagem que eu totalmente esqueci!",
  ui_story_5089_50891400_232_dialog_content = "Ai...",
  ui_story_5089_50891400_233_dialog_content = "Você realmente não precisa se forçar, Maya.",
  ui_story_5089_50891400_234_dialog_content = "Isso não é algo que deve ser decidido em um curto período de tempo.",
  ui_story_5089_50891400_235_dialog_content = "Você não precisa apressar sua decisão. Não vai mudar o que eu penso de você se decidir não ir.",
  ui_story_5089_50891400_236_dialog_content = "Sério?",
  ui_story_5089_50891400_237_dialog_content = "Uhum.",
  ui_story_5089_50891400_238_dialog_content = "Então... Estarei te esperando de volta no aquário.",
  ui_story_5089_50891400_239_dialog_content = "Tudo bem, é um acordo.",
  ui_story_5089_50891400_240_dialog_content = "Ótimo! Vou voltar e contar para Jeno e Elvis imediatamente!",
  ui_story_5089_50891400_241_dialog_content = "AHAM—!",
  ui_story_5089_50891400_242_dialog_content = "Parece que você está começando a entender agora.",
  ui_story_5089_50891400_243_dialog_content = "Dizer \"adeus\" significa que temos que seguir nossos caminhos separados por um tempo.",
  ui_story_5089_50891400_244_dialog_content = "Mas esse tempo não precisa necessariamente durar para sempre.",
  ui_story_5089_50891400_245_dialog_content = "E já que você espera voltar algum dia, não há necessidade de deixar seus \"adeus\" pesarem tanto em seu coração.",
  ui_story_5089_50891400_246_dialog_content = "Você também não deveria se forçar a dizer essas palavras.",
  ui_story_5089_50891400_247_dialog_content = "Afinal, sua história ainda está longe de acabar.",
  ui_story_5089_50891400_248_dialog_content = "Então faça suas escolhas e guie sua história para o final perfeito em seu coração.",
  ui_story_5089_50891400_249_dialog_content = "Aquiles...",
  ui_story_5089_50891400_250_dialog_content = "Adeus, PlayerName.",
  ui_story_5089_50891400_251_dialog_content = "May o Último Celestita voa mais alto no céu do que nunca antes.",
  ui_story_5089_50891400_252_dialog_content = "...",
  ui_story_5089_50891400_253_dialog_content = "...",
  ui_story_5089_50891400_254_dialog_content = "Carleen, eu...",
  ui_story_5089_50891400_255_dialog_content = "Soroz está aqui.",
  ui_story_5089_50891400_256_dialog_content = "O que significa que é hora de partir, certo?",
  ui_story_5089_50891400_257_dialog_content = "Uhum.",
  ui_story_5089_50891400_258_dialog_content = "... É exatamente como quando nos conhecemos pela primeira vez.",
  ui_story_5089_50891400_259_dialog_content = "Você, Soroz, Vice, e eu, todos em Lumópolis...",
  ui_story_5089_50891400_260_dialog_content = "...",
  ui_story_5089_50891400_261_dialog_content = "Bom-",
  ui_story_5089_50891400_262_dialog_content = "Venha conosco, Carleen.",
  ui_story_5089_50891400_263_dialog_content = "Assim como tudo começou?",
  ui_story_5089_50891400_264_dialog_content = "Exatamente assim.",
  ui_story_5089_50891400_265_dialog_content = "...",
  ui_story_5089_50891400_266_dialog_content = "Então vamos, PlayerName!",
  ui_story_5089_50891400_267_dialog_content = "Por que demorou tanto, PlayerName?",
  ui_story_5089_50891400_268_dialog_content = "Estou começando a ficar tonto de pegar todo o seu relaxo!",
  ui_story_5089_50891400_269_dialog_content = "Vice, eu...",
  ui_story_5089_50891400_270_dialog_content = "Eu sabia que você viria, Carleen.",
  ui_story_5089_50891400_271_dialog_content = "Eu simplesmente não esperava que demorasse tanto.",
  ui_story_5089_50891400_272_dialog_content = "Bem, não é legal arrastar as pessoas sem uma explicação adequada...",
  ui_story_5089_50891400_273_dialog_content = "Você quer dizer como o que você fez comigo?",
  ui_story_5089_50891400_274_dialog_content = "Juro, você age como se ainda não nos conhecêssemos.",
  ui_story_5089_50891400_275_dialog_content = "Você vai magoar os sentimentos das pessoas se continuar agindo assim.",
  ui_story_5089_50891400_276_dialog_content = "Suspirar...",
  ui_story_5089_50891400_277_dialog_content = "Há mais alguma coisa com que você precisa de ajuda?",
  ui_story_5089_50891400_278_dialog_content = "Não, estamos quase prontos. Tudo o que resta é definir nosso destino.",
  ui_story_5089_50891400_279_dialog_content = "Nosso destino... Você quer dizer a \"terra da fantasia\" que descobrimos anteriormente?",
  ui_story_5089_50891400_280_dialog_content = "Isso mesmo. Estamos indo direto para aquela fenda, aquela onde os fragmentos de memória de Vice voaram. Ela tem me chamado.",
  ui_story_5089_50891400_281_dialog_content = "E depois de ter Migard, Victoria, a Santinha, e algumas outras partes olhando para isso, nós praticamente confirmamos que há um mundo completamente diferente do outro lado.",
  ui_story_5089_50891400_282_dialog_content = "Fui informado que este outro mundo está praticamente transbordando de N-matéria.",
  ui_story_5089_50891400_283_dialog_content = "Isso mesmo, o que significa que deve ser um mundo extremamente realista. A matéria X que compõe os mundos de fantasia é praticamente indetectável.",
  ui_story_5089_50891400_284_dialog_content = "Deve ser um lugar bastante seguro, mas ainda está envolto em mistério.",
  ui_story_5089_50891400_285_dialog_content = "É por isso que não quero permitir que outras pessoas venham comigo.",
  ui_story_5089_50891400_286_dialog_content = "Mas... Meus amigos... Eles não são apenas \"outras pessoas.\"",
  ui_story_5089_50891400_287_dialog_content = "Ei, isso me lembra. Por que continuamos chamando isso de \"terra de fantasia\"?",
  ui_story_5089_50891400_288_dialog_content = "Bem... No final do dia, é assim que Bethlehem descreveu—",
  ui_story_5089_50891400_289_dialog_content = "Quando comparado ao nosso mundo, é possível que o outro mundo seja o mundo real...",
  ui_story_5089_50891400_290_dialog_content = "E ainda assim, compartilha um vínculo fascinante e inseparável com o Astra.",
  ui_story_5089_50891400_291_dialog_content = "Essa é, em última análise, a razão pela qual as memórias de Vice fluíram para isso. A verdade que você busca também está nesse mundo, Celestita.",
  ui_story_5089_50891400_292_dialog_content = "Talvez, nessa realidade, exista uma fantasia correspondente.",
  ui_story_5089_50891400_293_dialog_content = "Isso implica que mesmo no mundo \"real\", as pessoas ainda podem conjurar belas \"fantasias\" do nada.",
  ui_story_5089_50891400_294_dialog_content = "O anseio deles pelo imaginário acabou levando à conexão dos nossos dois mundos.",
  ui_story_5089_50891400_295_dialog_content = "... Mas não vamos lá para acabar com essas fantasias.",
  ui_story_5089_50891400_296_dialog_content = "Não vamos simplesmente aceitar o mundo deles como a única e verdadeira realidade, também.",
  ui_story_5089_50891400_297_dialog_content = "No final, estamos apenas embarcando em uma nova jornada para o desconhecido, perseguindo os belos sonhos que também anseiamos.",
  ui_story_5089_50891400_298_dialog_content = "Mesmo que só possamos realizar isso no mundo real, acredito verdadeiramente que faremos isso acontecer algum dia.",
  ui_story_5089_50891400_299_dialog_content = "E quando esse momento chegar, todos nós retornaremos ao Astra!",
  ui_story_5089_50891400_300_dialog_content = "Para ser honesto, também não entendo muito bem esse modo de pensar.",
  ui_story_5089_50891400_301_dialog_content = "Estou apenas feliz em me juntar a todos em mais uma aventura.",
  ui_story_5089_50891400_302_dialog_content = "Concordo.",
  ui_story_5089_50891400_303_dialog_content = "Eu posso não falar muito, mas por favor lembre-se de me incluir também.",
  ui_story_5089_50891400_304_dialog_content = "Como poderíamos esquecer?",
  ui_story_5089_50891400_305_dialog_content = "Especialmente depois de quão difícil foi te encontrar novamente!",
  ui_story_5089_50891400_306_dialog_content = "Então, por favor, defina as coordenadas para o nosso novo destino.",
  ui_story_5089_50891400_307_dialog_content = "Vício.",
  ui_story_5089_50891400_308_dialog_content = "Sim! Quer se juntar a nós desta vez, Carleen?",
  ui_story_5089_50891400_309_dialog_content = "Mas eu não posso jogar...",
  ui_story_5089_50891400_310_dialog_content = "Ah, isso não importa. Só resta um pouco deste final fantasy, afinal.",
  ui_story_5089_50891400_311_dialog_content = "Ela está certa! Vice e eu podemos te guiar nisso, contanto que você se dedique.",
  ui_story_5089_50891400_312_dialog_content = "... Entendido.",
  ui_story_5089_50891400_313_dialog_content = "Certo...",
  ui_story_5089_50891400_314_dialog_content = "Vamos!",
  ui_story_5089_50891400_315_dialog_content = "Adeus, Astra.",
  ui_story_5089_50891400_316_dialog_content = "Adeus a todos que viajaram através deste belo sonho comigo.",
  ui_story_5089_50891400_317_dialog_content = "Até a próxima!",
  ui_story_5089_50891400_318_dialog_content = "O FIM",
  ui_story_5089_50891400_319_dialog_content = "Obrigado por jogar."
